        .hp-gov.is-later .hl-dot::after { animation: none; }
        @keyframes hpBlink { 0%, 100% { opacity: 1; box-shadow: 0 0 0 0 rgba(229, 72, 77, .55); } 50% { opacity: .35; box-shadow: 0 0 0 4px rgba(229, 72, 77, 0); } }
        .hp-gov.is-none .hp-gov-meta { color: #E5484D; font-weight: 600; }
        .hp-filters { display: flex; gap: 6px; overflow-x: auto; padding-bottom: 2px; }
