        .hp-body { flex: 1; min-width: 0; }
        .hp-title { display: flex; align-items: center; gap: 6px; flex-wrap: wrap; font-size: 14px; font-weight: 800; color: var(--text); }
        .hp-where { margin-top: 3px; font-size: 12px; font-weight: 700; color: var(--text); }
