        .hl-all { font-size: 11px; font-weight: 700; color: rgb(var(--p)); background: rgb(var(--p) / 0.1); border: 0; padding: 3px 9px; border-radius: 999px; cursor: pointer; }

        /* ===== Profile v2 ===== */
        .pf, .pf *, .pf *::before, .pf *::after { box-sizing: border-box; }
