            background: linear-gradient(135deg, rgb(var(--p)), #0B5E54 55%, #134E4A); box-shadow: 0 18px 36px -20px rgb(var(--p) / 0.9); }
        .pf-cover span { position: absolute; border-radius: 50%; background: rgba(255,255,255,.12); animation: hpFloat 8s ease-in-out infinite alternate; }
        .pf-cover span:first-child { width: 180px; height: 180px; top: -80px; left: -40px; }
        .pf-cover span:last-child { width: 120px; height: 120px; bottom: -60px; right: 20px; animation-duration: 6s; }
        .pf-cover::after { content: ""; position: absolute; inset: 0; background: linear-gradient(110deg, transparent 30%, rgba(255,255,255,.14) 45%, transparent 60%); background-size: 250% 100%; animation: hpShine 5s ease-in-out infinite; }
        .pf-card { position: relative; margin: -56px 10px 0; padding: 0 16px 16px; border-radius: 22px; text-align: center;
            background: var(--surface); border: 1px solid var(--border); box-shadow: var(--shadow-lift); animation: cardIn .55s var(--ease-out) both; }
        .pf-avatar { position: relative; width: 92px; height: 92px; margin: 0 auto; top: -40px; margin-bottom: -32px; border-radius: 50%; padding: 3px; cursor: pointer; }
        /* only the colour ring spins; the photo and camera badge stay still */
        .pf-avatar::before { content: ""; position: absolute; inset: 0; border-radius: 50%; background: conic-gradient(from 0deg, rgb(var(--p)), #F59E0B, #EC4899, rgb(var(--p))); animation: pfRing 6s linear infinite; }
        .pf-avatar img { position: relative; z-index: 1; width: 100%; height: 100%; border-radius: 50%; object-fit: cover; border: 3px solid var(--surface); background: var(--surface); }
        .pf-cam { z-index: 2; }
        @keyframes pfRing { to { transform: rotate(360deg); } }
        .pf-cam { position: absolute; bottom: 2px; left: 2px; width: 28px; height: 28px; border-radius: 50%; display: grid; place-items: center; color: #fff; background: rgb(var(--p)); border: 2px solid var(--surface); }
        .pf-cam svg { width: 14px; height: 14px; }
        .pf-name { font-size: 19px; font-weight: 800; color: var(--text); margin: 0; }
        .pf-school { font-size: 12.5px; color: var(--text2); margin: 2px 0 10px; }
        .pf-chips { display: flex; flex-wrap: wrap; justify-content: center; gap: 6px; }
