        .pf-contact svg { width: 12px; height: 12px; }
        .pf-stats { display: grid; grid-template-columns: repeat(4, 1fr); gap: 8px; padding: 14px 16px 0; }
        .pf-stat { position: relative; display: flex; flex-direction: column; align-items: center; gap: 2px; padding: 10px 4px; border-radius: 16px; background: var(--surface); border: 1px solid var(--border); box-shadow: var(--shadow-card); color: var(--text); animation: hpPop .5s var(--ease-spring) both; }
        .pf-stat:nth-child(2) { animation-delay: .05s; } .pf-stat:nth-child(3) { animation-delay: .1s; } .pf-stat:nth-child(4) { animation-delay: .15s; }
        .pf-stat > svg { width: 18px; height: 18px; color: var(--c); }
        .pf-stat b { font-size: 17px; font-weight: 800; line-height: 1.2; font-variant-numeric: tabular-nums; }
        .pf-stat span:last-of-type { font-size: 10px; color: var(--text2); font-weight: 600; }
        .pf-stat em { position: absolute; top: 6px; left: 6px; min-width: 16px; height: 16px; padding: 0 4px; border-radius: 99px; font-style: normal; font-size: 10px; font-weight: 700; color: #fff; background: #E5484D; display: grid; place-items: center; }
        .pf-stat em.hidden { display: none; }
        .pf-quick { display: grid; grid-template-columns: repeat(4, 1fr); gap: 8px; padding: 12px 16px 0; }
        .pf-quick button { display: flex; flex-direction: column; align-items: center; gap: 6px; font-size: 11.5px; font-weight: 700; color: var(--text); background: none; border: 0; cursor: pointer; }
        .pf-quick button span { width: 48px; height: 48px; border-radius: 16px; display: grid; place-items: center; color: var(--c); background: color-mix(in srgb, var(--c) 13%, transparent); transition: transform .2s var(--ease-spring); }
