        body.focus-mode #mainContent { padding-bottom: 0 !important; }
        .fc-hero { position: relative; overflow: hidden; display: flex; align-items: center; gap: 14px; padding: 16px; border-radius: 24px; color: #fff;
            background: linear-gradient(135deg, #0F172A, #134E4A 60%, rgb(var(--p))); box-shadow: 0 20px 40px -22px rgb(var(--p)); animation: cardIn .5s var(--ease-out) both; }
