        .gr-chips::-webkit-scrollbar { display: none; }
        .gr-chip { flex-shrink: 0; height: 36px; padding: 0 14px; border-radius: 99px; border: 1px solid var(--border); background: var(--surface); color: var(--text); font-size: 12.5px; font-weight: 700; cursor: pointer; display: inline-flex; align-items: center; gap: 6px; }
        .gr-chip.on { color: #fff; background: rgb(var(--p)); border-color: transparent; }
        .gr-chip svg { width: 14px; height: 14px; }
        .gr-add { display: flex; gap: 8px; margin-top: 6px; }
        .gr-add input { flex: 1; min-width: 0; height: 42px; padding: 0 12px; border-radius: 14px; border: 1px solid var(--border); background: var(--input-bg); color: var(--text); font: inherit; font-size: 13px; }
        .gr-add button { height: 42px; padding: 0 16px; border: 0; border-radius: 14px; font: inherit; font-size: 13px; font-weight: 800; color: #fff; background: rgb(var(--p)); cursor: pointer; }
        .gr-card { position: relative; margin-top: 8px; padding: 14px 12px 10px; border-radius: 22px; background: var(--surface); border: 1px solid var(--border); box-shadow: var(--shadow-card); animation: cardIn .45s var(--ease-out) both; }
        .gr-card h4 { margin: 0 4px 2px; font-size: 14px; font-weight: 900; color: var(--text); }
        .gr-trend { margin: 0 4px 6px; font-size: 12px; font-weight: 700; color: var(--text2); display: flex; align-items: center; gap: 5px; }
        .gr-trend svg { width: 14px; height: 14px; }
        .gr-trend.up { color: #15803D; } .gr-trend.down { color: #DC2626; }
        .gr-chart { position: relative; }
        .gr-chart svg { display: block; width: 100%; height: auto; overflow: visible; }
        .gr-chart .grid { stroke: var(--border); stroke-width: 1; }
        .gr-chart .pass { stroke: #DC2626; stroke-width: 1; stroke-dasharray: 4 4; opacity: .55; }
        .gr-chart .ax { fill: var(--text2); font-size: 10px; font-family: inherit; }
        .gr-chart .ln { fill: none; stroke: rgb(var(--p)); stroke-width: 2; stroke-linecap: round; stroke-linejoin: round; stroke-dasharray: 1000; stroke-dashoffset: 1000; animation: grDraw 1.1s var(--ease-out) forwards .15s; }
        .gr-chart .area { fill: url(#grArea); opacity: 0; animation: hpFade .6s ease forwards .5s; }
        @keyframes grDraw { to { stroke-dashoffset: 0; } }
        @keyframes hpFade { to { opacity: 1; } }
        .gr-chart .pt { fill: rgb(var(--p)); stroke: var(--surface); stroke-width: 2; }
        .gr-chart .pt.low { fill: #DC2626; }
        .gr-chart .hit { fill: transparent; cursor: pointer; }
        .gr-chart .lbl { fill: var(--text); font-size: 11px; font-weight: 800; font-family: inherit; }
        .gr-tip { position: absolute; top: 0; transform: translate(50%, -100%); pointer-events: none; padding: 6px 10px; border-radius: 10px; background: var(--text); color: var(--surface); font-size: 11.5px; font-weight: 700; white-space: nowrap; box-shadow: 0 8px 18px -8px rgba(0,0,0,.4); }
        .gr-tip b { font-size: 13px; }
        .gr-empty { padding: 26px 10px; text-align: center; font-size: 12.5px; color: var(--text2); line-height: 1.8; }
        .gr-inputs { display: grid; grid-template-columns: repeat(4, 1fr); gap: 8px; }
        .gr-in { display: flex; flex-direction: column; gap: 4px; padding: 8px 6px; border-radius: 14px; background: var(--surface); border: 1px solid var(--border); }
        .gr-in label { font-size: 10.5px; font-weight: 700; color: var(--text2); text-align: center; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
        .gr-in input { width: 100%; height: 36px; border-radius: 10px; border: 1px solid var(--border); background: var(--input-bg); color: var(--text); text-align: center; font: inherit; font-size: 16px; font-weight: 800; font-variant-numeric: tabular-nums; }
        .gr-in input:focus { outline: none; border-color: rgb(var(--p)); box-shadow: 0 0 0 3px rgb(var(--p) / .15); }
        .gr-in.low input { color: #DC2626; }
        .gr-bars { display: flex; flex-direction: column; gap: 8px; padding: 12px; border-radius: 20px; background: var(--surface); border: 1px solid var(--border); }
        .gr-bar { display: grid; grid-template-columns: 74px 1fr 34px; align-items: center; gap: 8px; background: none; border: 0; padding: 2px 0; font: inherit; color: var(--text); cursor: pointer; text-align: right; }
        .gr-bar > span:first-child { font-size: 12px; font-weight: 700; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
        .gr-bar-track { height: 10px; border-radius: 4px; background: var(--input-bg); overflow: hidden; }
        .gr-bar-track i { display: block; height: 100%; width: var(--w); border-radius: 4px; background: rgb(var(--p)); transform-origin: right; animation: hpGrow .9s var(--ease-out) both; }
        .gr-bar.low .gr-bar-track i { background: #DC2626; }
        .gr-bar b { font-size: 13px; font-weight: 900; font-variant-numeric: tabular-nums; text-align: left; }
        .gr-bar.on > span:first-child { color: rgb(var(--p)); }
        .gr-flag { display: flex; align-items: center; gap: 6px; margin-top: 4px; padding: 8px 10px; border-radius: 12px; font-size: 11.5px; font-weight: 700; color: #B91C1C; background: rgba(220,38,38,.08); }
        .gr-flag svg { width: 14px; height: 14px; flex-shrink: 0; }
        .gr-acts { display: flex; gap: 8px; margin-top: 16px; }
        .gr-acts button { flex: 1; height: 48px; border-radius: 16px; font: inherit; font-size: 13.5px; font-weight: 800; display: flex; align-items: center; justify-content: center; gap: 7px; cursor: pointer; border: 1px solid var(--border); color: var(--text); background: var(--surface); }
        .gr-acts button.pri { border: 0; color: #fff; background: linear-gradient(135deg, rgb(var(--p)), #0B5E54); }
        .gr-acts button.del { flex: 0 0 48px; color: #DC2626; }
        .gr-acts svg { width: 17px; height: 17px; }

        /* ===== Mood of the day (مزاجي اليوم) ===== */
        .mo, .mo * { box-sizing: border-box; }
        .mo { position: relative; overflow: hidden; padding: 14px; border-radius: 22px; background: var(--surface); border: 1px solid var(--border); box-shadow: var(--shadow-card); }
        .mo::before { content: ""; position: absolute; inset: -60% -30% auto auto; width: 200px; height: 200px; border-radius: 50%; background: radial-gradient(closest-side, color-mix(in srgb, var(--mc, rgb(var(--p))) 16%, transparent), transparent); animation: hpFloat 8s ease-in-out infinite; pointer-events: none; }
        .mo-q { position: relative; display: flex; align-items: center; justify-content: space-between; font-size: 14px; font-weight: 900; color: var(--text); }
        .mo-q small { font-size: 11px; font-weight: 700; color: var(--text2); }
        .mo-opts { position: relative; display: grid; grid-template-columns: repeat(4, 1fr); gap: 8px; margin-top: 12px; }
        .mo-opt { display: flex; flex-direction: column; align-items: center; gap: 6px; padding: 10px 2px; border-radius: 16px; border: 1px solid var(--border); background: var(--surface); color: var(--text); font: inherit; font-size: 12px; font-weight: 800; cursor: pointer; transition: transform .2s var(--ease-spring); animation: hpPop .45s var(--ease-spring) both; }
        .mo-opt:active { transform: scale(.92); }
        .mo-ic { width: 40px; height: 40px; border-radius: 14px; display: grid; place-items: center; color: var(--c); background: color-mix(in srgb, var(--c) 14%, transparent); }
        .mo-ic svg { width: 21px; height: 21px; }
        .mo-now { position: relative; display: flex; align-items: center; gap: 12px; }
        .mo-now .mo-ic { width: 46px; height: 46px; animation: hpBob 3s ease-in-out infinite; }
        .mo-now div { flex: 1; min-width: 0; }
        .mo-now b { display: block; font-size: 14px; font-weight: 900; color: var(--text); }
        .mo-now span { font-size: 12px; color: var(--text2); line-height: 1.6; }
        .mo-chg { flex-shrink: 0; align-self: flex-start; padding: 4px 10px; border-radius: 99px; border: 1px solid var(--border); background: none; font: inherit; font-size: 11px; font-weight: 700; color: var(--text2); cursor: pointer; }
        .mo-act { position: relative; width: 100%; height: 42px; margin-top: 12px; border: 0; border-radius: 14px; display: flex; align-items: center; justify-content: center; gap: 7px; font: inherit; font-size: 13px; font-weight: 800; color: #fff; background: var(--mc); cursor: pointer; }
        .mo-act svg { width: 16px; height: 16px; }
        .mo-week { position: relative; display: grid; grid-template-columns: repeat(7, 1fr); gap: 4px; margin-top: 14px; padding-top: 12px; border-top: 1px dashed var(--border); }
        .mo-day { display: flex; flex-direction: column; align-items: center; gap: 4px; font-size: 10px; font-weight: 700; color: var(--text2); }
        .mo-dot { width: 30px; height: 30px; border-radius: 50%; display: grid; place-items: center; color: #fff; background: var(--c); animation: hpPop .4s var(--ease-spring) both; }
        .mo-dot svg { width: 15px; height: 15px; }
        .mo-dot.none { background: none; border: 1.5px dashed var(--border); }
        .mo-day.today span:first-child { color: var(--text); font-weight: 900; }
        .mo-st { width: 6px; height: 6px; border-radius: 50%; background: transparent; }
        .mo-st.on { background: #16A34A; }
        .mo-legend { position: relative; display: flex; flex-wrap: wrap; gap: 4px 12px; margin-top: 10px; font-size: 10.5px; color: var(--text2); }
        .mo-legend span { display: inline-flex; align-items: center; gap: 5px; }
        .mo-legend .mo-lg-st { width: 7px; height: 7px; border-radius: 50%; background: #16A34A; }
        .mo-ins { position: relative; margin-top: 10px; padding: 9px 11px; border-radius: 12px; font-size: 12px; font-weight: 700; color: var(--text); background: var(--input-bg); line-height: 1.6; }

        /* ===== Story share card (بطاقة ستوري) ===== */
        .sc-modal { position: fixed; inset: 0; z-index: 90; display: flex; align-items: flex-end; justify-content: center; background: rgba(2,6,23,.62); backdrop-filter: blur(4px); animation: hpFade .2s ease forwards; opacity: 0; }
        .sc-sheet { box-sizing: border-box; width: 100%; max-width: 480px; max-height: 96vh; overflow-y: auto; padding: 14px 16px 20px; border-radius: 26px 26px 0 0; background: var(--surface); animation: cardIn .35s var(--ease-out) both; }
        .sc-head { display: flex; align-items: center; justify-content: space-between; margin-bottom: 12px; font-size: 15px; font-weight: 900; color: var(--text); }
        .sc-head button { width: 36px; height: 36px; border-radius: 12px; border: 0; display: grid; place-items: center; background: var(--input-bg); color: var(--text); cursor: pointer; }
        .sc-prev { display: grid; place-items: center; min-height: 200px; border-radius: 18px; background: var(--input-bg); }
        .sc-prev img { display: block; max-width: 100%; max-height: 58vh; border-radius: 14px; box-shadow: 0 18px 40px -18px rgba(0,0,0,.45); }
        .sc-prev .sc-wait { font-size: 12.5px; color: var(--text2); }
        .sc-btns { display: flex; gap: 8px; margin-top: 14px; }
        .sc-btns button { flex: 1; height: 50px; border-radius: 16px; font: inherit; font-size: 14px; font-weight: 800; display: flex; align-items: center; justify-content: center; gap: 8px; cursor: pointer; border: 1px solid var(--border); color: var(--text); background: var(--surface); }
        .sc-btns button.pri { border: 0; color: #fff; background: linear-gradient(135deg, rgb(var(--p)), #0B5E54); }
        .sc-btns svg { width: 18px; height: 18px; }
        .sc-note { margin-top: 10px; text-align: center; font-size: 11.5px; color: var(--text2); }

        /* ===== Shared bits for the live pages ===== */
        .lv, .lv * { box-sizing: border-box; }
        .lv { padding: 14px 16px 28px; }
        .lv-sec { display: flex; align-items: center; justify-content: space-between; margin: 20px 4px 10px; font-size: 14px; font-weight: 800; color: var(--text); }
        .lv-sec small { font-size: 11px; font-weight: 700; color: var(--text2); }
        .lv-rules { display: flex; flex-direction: column; gap: 8px; margin-top: 18px; }
        .lv-rules div { display: flex; align-items: center; gap: 10px; padding: 11px 12px; border-radius: 14px; background: var(--surface); border: 1px solid var(--border); font-size: 12px; line-height: 1.6; color: var(--text); }
        .lv-rules svg { width: 17px; height: 17px; flex-shrink: 0; color: rgb(var(--p)); }
        .lv-btn { width: 100%; height: 50px; margin-top: 12px; border: 0; border-radius: 16px; display: flex; align-items: center; justify-content: center; gap: 8px; font: inherit; font-size: 14px; font-weight: 800; color: #fff; cursor: pointer; background: linear-gradient(135deg, rgb(var(--p)), #0B5E54); box-shadow: 0 14px 28px -14px rgb(var(--p)); }
        .lv-btn svg { width: 18px; height: 18px; }
        .lv-btn:disabled { opacity: .6; }
        .lv-empty { padding: 30px 16px; text-align: center; border-radius: 22px; background: var(--surface); border: 1px dashed var(--border); color: var(--text2); font-size: 13px; line-height: 1.8; }
        .lv-empty svg { width: 34px; height: 34px; margin-bottom: 8px; color: var(--text2); }
        .lv-empty b { display: block; font-size: 15px; color: var(--text); }
        @keyframes lvPing { 0% { transform: scale(1); opacity: .7; } 100% { transform: scale(2.4); opacity: 0; } }

        /* ===== Governorate war (حرب المحافظات) ===== */
        .gw-hero { position: relative; overflow: hidden; padding: 16px; border-radius: 24px; color: #fff; background: linear-gradient(135deg, #7F1D1D, #991B1B 35%, #0F172A); box-shadow: 0 20px 40px -22px #991B1B; animation: cardIn .5s var(--ease-out) both; }
        .gw-hero::after { content: ""; position: absolute; inset: 0; background: linear-gradient(110deg, transparent 30%, rgba(255,255,255,.1) 45%, transparent 60%); background-size: 250% 100%; animation: hpShine 6s ease-in-out infinite; pointer-events: none; }
        .gw-hero-top { position: relative; display: flex; align-items: center; justify-content: space-between; gap: 8px; flex-wrap: wrap; font-size: 11px; font-weight: 700; }
        .gw-live { display: inline-flex; align-items: center; gap: 6px; padding: 4px 10px; border-radius: 99px; background: rgba(255,255,255,.14); }
        .gw-live i { position: relative; width: 7px; height: 7px; border-radius: 50%; background: #4ADE80; }
        .gw-live i::after { content: ""; position: absolute; inset: 0; border-radius: 50%; background: #4ADE80; animation: lvPing 1.6s ease-out infinite; }
        .gw-clock { opacity: .9; }
        .gw-clock b { font-variant-numeric: tabular-nums; }
        .gw-lead { position: relative; display: flex; align-items: center; gap: 12px; margin-top: 14px; }
        .gw-crown { flex-shrink: 0; width: 54px; height: 54px; border-radius: 18px; display: grid; place-items: center; color: #FDE68A; background: rgba(250,204,21,.16); animation: hpBob 3s ease-in-out infinite; }
        .gw-crown svg { width: 28px; height: 28px; }
        .gw-lead small { display: block; font-size: 11px; opacity: .75; }
        .gw-lead b { display: block; font-size: 22px; font-weight: 900; }
        .gw-lead em { font-style: normal; font-size: 12px; opacity: .85; }
        .gw-last { display: flex; align-items: center; gap: 10px; margin-top: 10px; padding: 11px 12px; border-radius: 16px; background: var(--surface); border: 1px solid var(--border); font-size: 12px; color: var(--text2); }
        .gw-last > svg { width: 20px; height: 20px; color: #D97706; flex-shrink: 0; }
        .gw-last div { flex: 1; min-width: 0; }
        .gw-last b { display: block; font-size: 13px; color: var(--text); }
        .gw-last button { flex-shrink: 0; height: 36px; padding: 0 12px; border: 0; border-radius: 12px; font: inherit; font-size: 12px; font-weight: 800; color: #fff; background: #D97706; cursor: pointer; }
        .gw-last.win { border-color: rgba(217,119,6,.4); background: rgba(245,158,11,.08); }
        .gw-map { display: grid; grid-template-columns: repeat(5, 1fr); grid-template-rows: repeat(7, 52px); gap: 5px; direction: ltr; }
        .gw-tile { position: relative; min-width: 0; display: flex; flex-direction: column; align-items: center; justify-content: center; gap: 1px; padding: 2px; border-radius: 12px; text-align: center; background: var(--input-bg); border: 1px solid var(--border); color: var(--text); animation: hpPop .45s var(--ease-spring) both; direction: rtl; }
        .gw-tile b { font-size: 10px; font-weight: 800; line-height: 1.2; white-space: nowrap; }
        .gw-tile span { font-size: 9px; font-weight: 700; opacity: .75; white-space: nowrap; }
        .gw-tile.lv1 { background: rgb(var(--p) / .14); border-color: rgb(var(--p) / .2); }
        .gw-tile.lv2 { background: rgb(var(--p) / .32); border-color: transparent; }
        .gw-tile.lv3 { background: rgb(var(--p) / .6); border-color: transparent; color: #fff; }
        .gw-tile.lv4 { background: rgb(var(--p)); border-color: transparent; color: #fff; box-shadow: 0 8px 18px -8px rgb(var(--p)); }
        .gw-tile.me { outline: 2px solid #F59E0B; outline-offset: 1px; }
        .gw-tile em { position: absolute; top: -6px; left: -4px; min-width: 18px; height: 18px; padding: 0 4px; border-radius: 99px; font-style: normal; font-size: 10px; font-weight: 900; line-height: 18px; color: #fff; background: #16A34A; box-shadow: 0 0 0 2px var(--surface); }
        .gw-tile.on::after { content: ""; position: absolute; inset: -1px; border-radius: inherit; border: 2px solid #16A34A; animation: gwGlow 1.8s ease-in-out infinite; pointer-events: none; }
        @keyframes gwGlow { 0%, 100% { opacity: .25; } 50% { opacity: 1; } }
        .gw-t-crown { position: absolute; top: -9px; right: -3px; width: 16px; height: 16px; color: #F59E0B; }
        .gw-legend { display: flex; flex-wrap: wrap; align-items: center; gap: 4px 10px; margin-top: 10px; font-size: 10.5px; color: var(--text2); }
        .gw-legend span { display: inline-flex; align-items: center; gap: 4px; }
        .gw-legend i { width: 14px; height: 10px; border-radius: 3px; background: var(--input-bg); border: 1px solid var(--border); }
        .gw-legend i.lv1 { background: rgb(var(--p) / .14); } .gw-legend i.lv2 { background: rgb(var(--p) / .32); } .gw-legend i.lv3 { background: rgb(var(--p) / .6); } .gw-legend i.lv4 { background: rgb(var(--p)); }
        .gw-legend em { width: 10px; height: 10px; border-radius: 50%; background: #16A34A; }
        .gw-me { margin-top: 16px; padding: 14px; border-radius: 20px; background: var(--surface); border: 1px solid var(--border); box-shadow: var(--shadow-card); }
        .gw-me p { margin: 0; font-size: 13px; color: var(--text2); text-align: center; }
        .gw-me-row { display: flex; align-items: center; gap: 12px; }
        .gw-me-rank { flex-shrink: 0; width: 46px; height: 46px; border-radius: 15px; display: grid; place-items: center; font-size: 20px; font-weight: 900; color: #fff; background: linear-gradient(135deg, #F59E0B, #D97706); }
        .gw-me-row b { display: block; font-size: 14px; font-weight: 900; color: var(--text); }
        .gw-me-row small { font-size: 11.5px; color: var(--text2); }
        .gw-rank { display: flex; flex-direction: column; gap: 6px; }
        .gw-row { display: flex; align-items: center; gap: 10px; padding: 9px 11px; border-radius: 14px; background: var(--surface); border: 1px solid var(--border); animation: cardIn .4s var(--ease-out) both; }
        .gw-row.me { border-color: rgba(245,158,11,.5); background: rgba(245,158,11,.06); }
        .gw-n { flex-shrink: 0; width: 26px; height: 26px; border-radius: 9px; display: grid; place-items: center; font-size: 12px; font-weight: 900; color: var(--text2); background: var(--input-bg); }
        .gw-n.top1 { color: #fff; background: #D97706; } .gw-n.top2 { color: #fff; background: #64748B; } .gw-n.top3 { color: #fff; background: #B45309; }
        .gw-row-main { flex: 1; min-width: 0; }
        .gw-row-top { display: flex; align-items: center; gap: 6px; font-size: 12.5px; color: var(--text); }
        .gw-row-top b { font-weight: 800; }
        .gw-row-top em { margin-right: auto; font-style: normal; font-size: 11.5px; font-weight: 800; color: var(--text2); font-variant-numeric: tabular-nums; }
        .gw-row-live { display: inline-flex; align-items: center; gap: 4px; font-size: 10px; font-weight: 800; color: #16A34A; }
        .gw-row-live i { width: 6px; height: 6px; border-radius: 50%; background: #16A34A; animation: gwGlow 1.4s ease-in-out infinite; }
        .gw-bar { height: 6px; margin-top: 6px; border-radius: 4px; background: var(--input-bg); overflow: hidden; }
        .gw-bar i { display: block; height: 100%; width: var(--w); border-radius: 4px; background: rgb(var(--p)); transform-origin: right; animation: hpGrow .9s var(--ease-out) both; }
        .gw-more { display: block; width: 100%; height: 42px; margin-top: 8px; border-radius: 14px; border: 1px dashed var(--border); background: none; font: inherit; font-size: 12.5px; font-weight: 800; color: var(--text2); cursor: pointer; }
        /* ===== 3D satellite battlefield ===== */
        .gw3d { position: relative; height: 420px; margin: 0 -16px; overflow: hidden; touch-action: pan-y; user-select: none; -webkit-user-select: none;
            background: radial-gradient(120% 85% at 50% 35%, #10283a 0%, #071521 55%, #02070c 100%); }
        .gw3d canvas { position: absolute; inset: 0; width: 100%; height: 100%; display: block; cursor: grab; }
        .gw3d::after { content: ""; position: absolute; inset: 0; pointer-events: none; z-index: 2;
            background: repeating-linear-gradient(0deg, rgba(255,255,255,.028) 0 1px, transparent 1px 3px), radial-gradient(130% 100% at 50% 50%, transparent 60%, rgba(0,0,0,.55) 100%); }
        .gw3d-labels { position: absolute; inset: 0; pointer-events: none; z-index: 3; }
        .gw3d-lb { position: absolute; left: 0; top: 0; pointer-events: auto; display: inline-flex; align-items: center; gap: 4px; padding: 2px 7px; border-radius: 8px; border: 1px solid rgba(255,255,255,.2);
            background: rgba(3,12,20,.62); color: #fff; font: inherit; font-size: 10px; font-weight: 800; white-space: nowrap; text-shadow: 0 1px 3px #000; cursor: pointer; -webkit-backdrop-filter: blur(2px); backdrop-filter: blur(2px); transition: opacity .2s; }
        .gw3d-lb small { font-size: 9px; font-weight: 800; color: #99F6E4; }
