        @keyframes tkListIn { from { opacity: 0; transform: translateY(-6px); } to { opacity: 1; transform: none; } }
        .tk-item { display: flex; gap: 10px; align-items: flex-start; width: 100%; padding: 10px 8px; background: none; border: 0; border-radius: 12px; text-align: start; font: inherit; color: var(--text); cursor: pointer; }
        .tk-item:hover { background: var(--input-bg); }
        .tk-item-mark { flex-shrink: 0; width: 6px; height: 6px; margin-top: 8px; border-radius: 50%; background: var(--border); }
        .tk-item.is-current { background: var(--input-bg); }
        .tk-item.is-current .tk-item-mark { background: var(--error); }
        .tk-item-body { flex: 1; min-width: 0; font-size: 13.5px; line-height: 1.6; }
        .tk-item-time { display: block; margin-top: 2px; font-size: 11px; color: var(--text2); }
        /* Fade hint at the scroll edges of horizontal chip/pill rows (category tabs, stage
           tabs, forum subjects...) so it's visually obvious there's more content off-screen —
           these rows had no affordance before, just an abrupt cut at the container edge. */
        .scroll-fade-x {
            mask-image: linear-gradient(to left, transparent, black 24px, black calc(100% - 24px), transparent);
            -webkit-mask-image: linear-gradient(to left, transparent, black 24px, black calc(100% - 24px), transparent);
        }
        #walletTransactionsList > div:not(:last-child) {
            border-bottom: 1px solid var(--border);
        }

        body.header-hidden #appHeaderBar { display: none; }
        body.header-hidden #mainContent { padding-top: 0; }
        body.header-hidden .sticky.top-16 { top: 0; }
        body.header-hidden .sticky.top-\[116px\] { top: 52px; }

        body.chat-nav-hidden #bottomNav { display: none; }
        body.chat-nav-hidden #mainContent { padding-bottom: 0; }

        body.results-nav-hidden #bottomNav { display: none; }
        body.results-nav-hidden #mainContent { padding-bottom: 0; }

        body.store-nav-hidden #bottomNav { display: none; }
        body.store-nav-hidden #mainContent { padding-bottom: 0; padding-top: 0; }
        .store-feed { position: absolute; inset: 0; overflow-y: auto; scroll-snap-type: y mandatory; -webkit-overflow-scrolling: touch; background: #000; }
        .store-card { position: relative; width: 100%; height: 100dvh; scroll-snap-align: start; scroll-snap-stop: always; background: #111; overflow: hidden; }
        .store-card-media { position: absolute; inset: 0; width: 100%; height: 100%; object-fit: cover; }
        .store-card-gradient { position: absolute; inset: 0; background: linear-gradient(to top, rgba(0,0,0,0.8) 0%, rgba(0,0,0,0.1) 38%, rgba(0,0,0,0.4) 100%); pointer-events: none; }
        .store-card-actions { position: absolute; left: 12px; bottom: 118px; display: flex; flex-direction: column; gap: 22px; align-items: center; z-index: 2; }
        /* FIX (UI/UX): the action icons used to sit bare over a moving video with only 20px
           between them — easy to fat-finger the wrong one while scrolling a full-bleed reel.
           A round backdrop behind each icon both raises contrast against busy video frames
           and pads the tappable area closer to the 44px minimum touch target. */
        .store-action-circle { width: 44px; height: 44px; border-radius: 50%; background: rgba(0,0,0,0.38); display: flex; align-items: center; justify-content: center; }
        .store-card-info { position: absolute; right: 16px; left: 72px; bottom: 24px; z-index: 2; }
        .store-action-btn { display: flex; flex-direction: column; align-items: center; gap: 4px; cursor: pointer; background: none; border: none; }

        /* the streak flame: a looping animated WebP (transparent), made from a cartoon fire clip */
        .flame {
            display: inline-block;
            width: 16px;
            height: 24px;
            margin: -6px 0 0;
            vertical-align: middle;
            flex-shrink: 0;
            background: url('../assets/flame.webp') center bottom / contain no-repeat;
            filter: drop-shadow(0 0 4px rgba(255, 120, 0, 0.45));
        }

        .study-scene { position: relative; width: 100%; height: 92px; }
        .study-desk {
            position: absolute; bottom: 14px; left: 50%; transform: translateX(-50%);
            width: 110px; height: 8px; background: rgb(var(--p)); opacity: 0.15; border-radius: 4px;
        }
        .study-person {
            position: absolute; bottom: 20px; left: 50%; transform: translateX(-46px);
            animation: studyBob 2.6s ease-in-out infinite;
        }
        .study-head { width: 22px; height: 22px; border-radius: 50%; background: rgb(var(--p)); margin: 0 auto; }
        .study-body { width: 32px; height: 26px; border-radius: 14px 14px 5px 5px; background: rgb(var(--p)); margin: -3px auto 0; }
        @keyframes studyBob {
            0%, 100% { transform: translateX(-46px) translateY(0) rotate(0deg); }
            50%      { transform: translateX(-46px) translateY(-3px) rotate(-3deg); }
        }
        .study-book {
            position: absolute; bottom: 20px; left: 50%; transform: translateX(6px);
            width: 36px; height: 24px; background: var(--surface); border: 2px solid #8B5CF6; border-radius: 4px; overflow: hidden;
        }
        .study-page {
            position: absolute; top: 2px; right: 2px; width: 15px; height: 19px;
            background: #C7D2FE; transform-origin: left center;
            animation: studyPageFlip 2.6s ease-in-out infinite;
        }
        @keyframes studyPageFlip {
            0%, 38%  { transform: scaleX(1); }
            50%      { transform: scaleX(0.08); }
            62%, 100%{ transform: scaleX(1); }
        }
    
        /* ================= UI/UX 2026 layer =================
           Visual system: "دجلة" — calm river-teal primary, warm date-gold accent,
           soft mineral background. One family (Readex Pro). Motion answers actions:
           page pushes, a springy tab capsule, press feedback, sheets that rise. */

        html { -webkit-text-size-adjust: 100%; }
        body { font-feature-settings: "ss01"; letter-spacing: 0; line-height: 1.6; }
        body::before {
            content: ""; position: fixed; inset: -20vh -20vw auto auto; width: 80vw; height: 60vh;
            background: radial-gradient(closest-side, var(--blob-a), transparent 70%);
            pointer-events: none; z-index: -1;
        }
        body::after {
            content: ""; position: fixed; inset: auto auto -25vh -25vw; width: 90vw; height: 60vh;
            background: radial-gradient(closest-side, var(--blob-b), transparent 70%);
            pointer-events: none; z-index: -1;
        }
        ::selection { background: rgb(var(--p) / 0.22); }

        /* ---- Type scale ---- */
        #mainContent h2.text-lg { font-size: 1.2rem; font-weight: 700; letter-spacing: -0.01em; }
        #mainContent h2.text-sm { font-size: 0.95rem; }
        #mainContent .text-xs { line-height: 1.55; }

        /* ---- Radii: a clear hierarchy instead of one radius everywhere ---- */
        html .rounded-2xl { border-radius: 22px; }
        html .rounded-xl { border-radius: 14px; }
        html .rounded-lg { border-radius: 10px; }
        html .rounded-2xl.rounded-ee-md { border-end-end-radius: 8px; }
        html .rounded-2xl.rounded-es-md { border-end-start-radius: 8px; }

        /* ---- App header (home) ---- */
        header.app-header {
            height: calc(64px + var(--safe-t)) !important;
            padding-top: var(--safe-t);
            background-color: rgba(var(--bg-rgb), 0.72) !important;
            border-bottom-color: transparent !important;
            transition: border-color .3s ease, box-shadow .3s ease, background-color .3s ease;
        }
        body.is-scrolled header.app-header {
            border-bottom-color: var(--border) !important;
            box-shadow: 0 8px 24px -18px rgba(0, 0, 0, 0.35);
        }
        header.app-header h1 { font-size: 1.05rem; font-weight: 700; letter-spacing: -0.01em; }
        header.app-header .w-10.h-10 { width: 42px; height: 42px; border-radius: 14px; box-shadow: 0 0 0 1px var(--border), 0 4px 10px -4px rgb(var(--p) / 0.45); }
        header.app-header button { width: 42px !important; height: 42px !important; border-radius: 50% !important; background-color: var(--input-bg) !important; }
        header.app-header button svg { width: 21px; height: 21px; stroke-width: 1.9; }
        #notifBadge { min-width: 19px; width: auto !important; height: 19px !important; padding: 0 5px; font-size: 10px; top: -2px !important; right: -2px !important; box-shadow: 0 0 0 2px rgba(var(--bg-rgb), 1); }

        #mainContent { padding-top: calc(64px + var(--safe-t)) !important; padding-bottom: calc(112px + var(--safe-b)) !important; }
        body.header-hidden #mainContent, body.store-nav-hidden #mainContent { padding-top: 0 !important; }
        body.chat-nav-hidden #mainContent, body.results-nav-hidden #mainContent, body.store-nav-hidden #mainContent { padding-bottom: 0 !important; }

        /* ---- Sticky page bars (every inner screen) ---- */
        .sticky.top-16 {
            top: calc(64px + var(--safe-t)) !important;
            background-color: rgba(var(--bg-rgb), 0.78) !important;
            backdrop-filter: blur(22px) saturate(180%); -webkit-backdrop-filter: blur(22px) saturate(180%);
        }
        body.header-hidden .sticky.top-16 { top: 0 !important; padding-top: calc(0.75rem + var(--safe-t)); }
        body.header-hidden .sticky.top-\[116px\] { top: calc(64px + var(--safe-t)) !important; }
        .sticky.top-16.border-b { border-bottom-color: transparent !important; box-shadow: 0 1px 0 var(--border); }
        .sticky.top-16 > span.font-bold, .sticky.top-16 > h2 { font-size: 1.1rem; letter-spacing: -0.01em; }
        .sticky.top-16 > button:first-child { border-radius: 50% !important; }

        /* ---- Surfaces & cards ---- */
        #mainContent .rounded-2xl.border[style*="var(--surface)"],
        #mainContent .rounded-2xl[style*="var(--surface)"],
        .news-card {
            box-shadow: var(--shadow-card) !important;
        }
        .news-card { border-color: var(--border) !important; padding: 14px !important; }
        .news-card.border-r-4 { border-right-width: 1px !important; }
        .news-card.border-r-4::before {
            content: ""; position: absolute; right: 0; top: 20px; bottom: 20px; width: 4px;
            border-radius: 4px 0 0 4px; background: rgb(var(--p));
        }
        .news-card img { transition: transform .5s var(--ease-out); }
        .news-card h3 { font-size: 0.92rem; line-height: 1.65; }
        .news-card .w-24 { width: 92px; height: 78px; border-radius: 16px; }

        .news-badges { display: flex; gap: 6px; flex-wrap: wrap; margin-bottom: 4px; }
        .nb { display: inline-flex; align-items: center; gap: 3px; font-size: 10.5px; font-weight: 700; line-height: 1; padding: 4px 8px; border-radius: 8px; }
        .nb-urgent { background: rgba(229, 72, 77, 0.12); color: #D6343A; }
        .nb-new { background: rgb(var(--p) / 0.12); color: rgb(var(--p)); }
        .nb-pin { background: rgba(212, 148, 15, 0.14); color: var(--gold); }
        .dark .nb-urgent { color: #FF7A7E; }

        /* No sticky hover-lift on touch screens */
        @media (hover: none) {
            .news-card:hover, .notif-card:hover, .file-card:hover, .subject-card:hover { transform: none !important; box-shadow: var(--shadow-card) !important; }
        }

        /* Press feedback: uses the independent `scale` property so it never fights
           Tailwind translate utilities or the swipe-to-delete transforms. */
        #mainContent button:not(:disabled):active,
        #mainContent [onclick]:not(:disabled):active,
        #bottomNav .nav-item:active,
        header.app-header button:active { scale: 0.96; }
        #mainContent article[onclick]:active, #mainContent .w-full[onclick]:active { scale: 0.985; }

        /* ---- Search ---- */
        #searchInput { height: 52px; border-radius: 18px; font-size: 15px; background-color: var(--surface) !important; box-shadow: var(--shadow-card); border: 1px solid var(--border) !important; }
        #searchInput:focus { box-shadow: 0 0 0 4px rgb(var(--p) / 0.14), var(--shadow-card) !important; border-color: rgb(var(--p) / 0.5) !important; }

        /* ---- Category chips ---- */
        #categoryTabs { gap: 8px; display: flex; overflow-x: auto; overscroll-behavior-x: contain; -webkit-overflow-scrolling: touch; scroll-padding-inline: 16px; }
        .cat-tab { padding: 9px 18px !important; font-size: 13.5px; transition: background-color .25s ease, color .25s ease, box-shadow .25s ease, scale .15s ease !important; }
        .cat-tab.bg-primary { box-shadow: 0 8px 18px -8px rgb(var(--p) / 0.7) !important; }
        .cat-tab:not(.bg-primary) { background-color: var(--surface) !important; box-shadow: 0 0 0 1px var(--border) inset !important; color: var(--text2) !important; }

        /* ---- Carousel & ticker ---- */
        .mySwiper { border-radius: 24px !important; box-shadow: var(--shadow-lift) !important; }

        /* ---- Buttons ---- */
        button.bg-primary, a.bg-primary { box-shadow: 0 10px 22px -12px rgb(var(--p) / 0.9); }
        .bg-primary.text-white { background-image: linear-gradient(180deg, rgba(255,255,255,0.10), rgba(255,255,255,0)); }

        /* ---- Inputs ---- */
        .auth-input { border-radius: 14px; font-size: 15px; }
        input, select, textarea { font-size: max(16px, 1em); }
        input.text-sm, textarea.text-sm, select.text-sm { font-size: 15px; }

        /* ---- Bottom navigation (v2): floating glass dock, 8 tabs ----
           A solid gradient capsule glides under the active icon (springy), the active icon
           turns white and lifts, its label turns bold primary. Sized so 8 tabs fit a 360px
           phone: 44px min per tab, 21px icons, 9.5px labels. */
        #bottomNav {
            left: 10px !important; right: 10px !important;
            height: 66px !important; border-radius: 24px !important;
            bottom: calc(8px + var(--safe-b)) !important;
            background-color: rgba(var(--bg-rgb), 0.82) !important;
            border: 1px solid var(--border) !important;
            box-shadow: inset 0 1px 0 var(--glass-highlight), 0 20px 40px -16px rgba(0, 0, 0, 0.4), 0 2px 8px rgba(0, 0, 0, 0.06) !important;
            backdrop-filter: blur(22px) saturate(180%); -webkit-backdrop-filter: blur(22px) saturate(180%);
            overflow: hidden;
        }
        /* A light in the theme colour that keeps travelling around the dock's frame (same
           technique as the news ticker): a big rotating conic spotlight (::before) behind an
           inner glass panel (::after) inset by 2px, so only a thin ring of it shows. */
        #bottomNav { position: fixed; z-index: 50; background-color: var(--border) !important; isolation: isolate; }
        #bottomNav::before { content: ""; position: absolute; z-index: 0; top: 50%; left: 50%; width: 150vmax; height: 150vmax; pointer-events: none;
            background: conic-gradient(from 0deg, transparent 0deg 250deg, rgb(var(--p) / 0.35) 300deg, rgb(var(--p)) 345deg, #CFFAF1 356deg, transparent 360deg);
            transform: translate(-50%, -50%) rotate(0deg); animation: tkBorderSpin 5s linear infinite; }
        #bottomNav::after { content: ""; position: absolute; z-index: 1; inset: 2px; border-radius: 22px; pointer-events: none;
            background: linear-gradient(rgba(var(--bg-rgb), 0.9), rgba(var(--bg-rgb), 0.9)), var(--bg); }
        #bottomNav .nav-track { z-index: 2; }
        @media (min-width: 480px) { #bottomNav { left: 0 !important; right: 0 !important; width: calc(100% - 24px); max-width: 456px !important; } }
        #bottomNav .nav-track { position: relative; display: flex; align-items: center; height: 100%; padding: 0 4px; max-width: none; }
        #bottomNav .nav-indicator {
            position: absolute; left: 0; top: 0; width: 40px; height: 30px; border-radius: 12px;
            background: linear-gradient(135deg, rgb(var(--p)), rgb(var(--p) / 0.78));
            box-shadow: 0 8px 18px -8px rgb(var(--p) / 0.9), inset 0 1px 0 rgba(255, 255, 255, 0.25);
            opacity: 0; pointer-events: none;
            transition: transform .55s var(--ease-spring), opacity .25s ease;
            will-change: transform;
        }
        #bottomNav .nav-indicator.is-ready { opacity: 1; }
        #bottomNav .nav-item {
            flex: 1 1 0; min-width: 0; height: 58px !important; padding: 0 1px; gap: 3px !important;
            display: flex; flex-direction: column; align-items: center; justify-content: center;
            background: transparent !important; box-shadow: none !important; border: 0; border-radius: 14px;
            position: relative; z-index: 1; color: var(--text2);
            transition: transform .2s ease;
        }
        #bottomNav .nav-ic { position: relative; height: 30px; width: 40px; display: flex; align-items: center; justify-content: center; }
        #bottomNav .nav-item svg { width: 21px; height: 21px; stroke-width: 1.8; transition: transform .45s var(--ease-spring), color .25s ease; }
        #bottomNav .nav-item.active svg { color: #fff; stroke-width: 2.2; transform: translateY(-1px) scale(1.04); }
        #bottomNav .nav-item.active { color: rgb(var(--p)) !important; }
        #bottomNav .nav-item:active { transform: scale(.92); }
        .nav-label { max-width: 100%; overflow: hidden; text-overflow: clip; font-size: 9.5px; font-weight: 500; line-height: 1.1; white-space: nowrap; letter-spacing: -0.1px; transition: color .2s; }
        #bottomNav .nav-item.active .nav-label { font-weight: 800; }
        @media (max-width: 350px) { .nav-label { font-size: 8.5px; } #bottomNav .nav-item svg { width: 19px; height: 19px; } }
        #navStoreCartBadge, #navMessagesBadge { box-shadow: 0 0 0 2px rgba(var(--bg-rgb), 1); top: -1px !important; right: 0 !important; z-index: 2; }

        /* ---- Page transitions (re-triggered on every navigation) ---- */
        .page-enter, .page-slide-rtl { animation: none !important; }
        .view-in-fwd  { animation: viewInFwd  .42s var(--ease-out) both; }
        .view-in-back { animation: viewInBack .42s var(--ease-out) both; }
        .view-in-tab  { animation: viewInTab  .34s var(--ease-out) both; }
        @keyframes viewInFwd  { from { opacity: 0; transform: translate3d(-28px, 0, 0); } to { opacity: 1; transform: none; } }
        @keyframes viewInBack { from { opacity: 0; transform: translate3d(28px, 0, 0); }  to { opacity: 1; transform: none; } }
        @keyframes viewInTab  { from { opacity: 0; transform: translate3d(0, 10px, 0) scale(0.99); } to { opacity: 1; transform: none; } }

        /* The one orchestrated moment: news cards settle in, one after another */
        #newsList > * { animation: cardIn .55s var(--ease-out) both; }
        #newsList > *:nth-child(2) { animation-delay: .05s; }
        #newsList > *:nth-child(3) { animation-delay: .10s; }
        #newsList > *:nth-child(4) { animation-delay: .15s; }
        #newsList > *:nth-child(5) { animation-delay: .20s; }
        #newsList > *:nth-child(6) { animation-delay: .25s; }
        #newsList > *:nth-child(n+7) { animation-delay: .30s; }
        #moreView .space-y-2 > * { animation: cardIn .45s var(--ease-out) both; }
        #moreView .space-y-2 > *:nth-child(2) { animation-delay: .03s; }
        #moreView .space-y-2 > *:nth-child(3) { animation-delay: .06s; }
        #moreView .space-y-2 > *:nth-child(4) { animation-delay: .09s; }
        #moreView .space-y-2 > *:nth-child(5) { animation-delay: .12s; }
        #moreView .space-y-2 > *:nth-child(n+6) { animation-delay: .15s; }
        @keyframes cardIn { from { opacity: 0; transform: translate3d(0, 14px, 0); } to { opacity: 1; transform: none; } }

        /* ---- Bottom sheets ---- */
        .fixed.inset-0 > .absolute.inset-0 { animation: fadeIn .28s ease both; backdrop-filter: blur(4px); -webkit-backdrop-filter: blur(4px); }
        .fixed.inset-0 .rounded-t-3xl {
            border-radius: 28px 28px 0 0 !important;
            animation: sheetUp .45s var(--ease-out) both;
            box-shadow: 0 -20px 50px -20px rgba(0, 0, 0, 0.4);
            padding-bottom: var(--safe-b);
            background-color: rgba(var(--bg-rgb), 0.96) !important;
            backdrop-filter: blur(24px); -webkit-backdrop-filter: blur(24px);
        }
        .fixed.inset-0 .rounded-t-3xl::before {
            content: ""; display: block; width: 38px; height: 5px; border-radius: 3px;
            background: var(--text2); opacity: .3; margin: 10px auto 0;
        }
        @keyframes sheetUp { from { transform: translate3d(0, 100%, 0); } to { transform: none; } }
        @keyframes fadeIn { from { opacity: 0; } to { opacity: 1; } }

        /* ---- Toasts: floating pill above the nav ---- */
        #toastContainer { bottom: calc(92px + var(--safe-b)) !important; align-items: center; }
        #toastContainer > div {
            border-radius: 999px !important; padding: 11px 20px !important; max-width: 92%;
            background-color: rgba(18, 28, 26, 0.9) !important; color: #fff !important;
            backdrop-filter: blur(16px); -webkit-backdrop-filter: blur(16px);
            box-shadow: 0 14px 30px -12px rgba(0, 0, 0, 0.5) !important;
        }
        .dark #toastContainer > div { background-color: rgba(242, 246, 245, 0.95) !important; color: #0E1F1B !important; }
        .toast-enter { animation: toastPop .45s var(--ease-spring) forwards !important; }
        .toast-exit { animation: toastOut .25s ease-in forwards !important; }
        @keyframes toastPop { from { opacity: 0; transform: translate3d(0, 18px, 0) scale(0.92); } to { opacity: 1; transform: none; } }
        @keyframes toastOut { to { opacity: 0; transform: translate3d(0, 10px, 0) scale(0.96); } }

        /* ---- Small polish ---- */
        .toggle-slider { background-color: rgba(120, 130, 128, 0.35); }
        .toggle-slider:before { box-shadow: 0 2px 6px rgba(0, 0, 0, 0.2); transition: transform .35s var(--ease-spring); }
        .skeleton { background: linear-gradient(90deg, var(--input-bg) 25%, rgba(255,255,255,0.35) 50%, var(--input-bg) 75%); background-size: 200% 100%; }
        .dark .skeleton { background: linear-gradient(90deg, rgba(255,255,255,0.05) 25%, rgba(255,255,255,0.1) 50%, rgba(255,255,255,0.05) 75%); background-size: 200% 100%; }
        .menu-item { border-radius: 16px; }

        #ptrIndicator { top: calc(64px + var(--safe-t)) !important; }

        @media (prefers-reduced-motion: reduce) {
            *, *::before, *::after { animation-duration: 0.01ms !important; animation-iteration-count: 1 !important; transition-duration: 0.01ms !important; scroll-behavior: auto !important; }
            .tk-dot::after { animation: none !important; }
        }

    

/* ===== بدون نت ===== */
.offline-bar { display: none; position: fixed; top: 0; left: 0; right: 0; z-index: 9999; padding: calc(var(--safe-t) + 6px) 14px 6px; text-align: center; font-size: 11.5px; font-weight: 700; color: #FFF7ED; background: linear-gradient(90deg, #B45309, #D97706); box-shadow: 0 4px 14px -6px rgba(0,0,0,.4); }
body.is-offline .offline-bar { display: block; }

/* ===== الساعة الذهبية ===== */
.gold-bar { position: relative; display: flex; align-items: center; gap: 10px; padding: 10px 12px; border-radius: 16px; overflow: hidden; border: 1px solid rgba(217,160,40,.35); background: linear-gradient(120deg, rgba(251,191,36,.12), rgba(245,158,11,.06)); }
.gold-bar .gold-ic { width: 36px; height: 36px; border-radius: 12px; display: grid; place-items: center; flex-shrink: 0; color: #fff; background: linear-gradient(135deg, #FBBF24, #D97706); box-shadow: 0 6px 16px -6px rgba(217,119,6,.8); }
.gold-bar .gold-ic svg { width: 19px; height: 19px; }
.gold-bar .gold-tx { flex: 1; min-width: 0; }
.gold-bar .gold-tx b { display: block; font-size: 13.5px; font-weight: 800; color: var(--text); font-variant-numeric: tabular-nums; }
.gold-bar .gold-tx small { display: block; margin-top: 2px; font-size: 11px; line-height: 1.5; color: var(--text2); }
.gold-bar.after { opacity: .75; border-color: rgba(148,163,184,.3); background: rgba(148,163,184,.08); }
.gold-bar.after .gold-ic { background: linear-gradient(135deg, #94A3B8, #64748B); box-shadow: none; }
.gold-bar.soon { animation: goldPulse 1.6s ease-in-out infinite; }
.gold-bar.on { border-color: #F59E0B; background: linear-gradient(120deg, #FDE68A, #FBBF24 45%, #F59E0B); box-shadow: 0 10px 28px -12px rgba(217,119,6,.9); }
.gold-bar.on .gold-tx b { color: #422006; }
.gold-bar.on .gold-tx small { color: #713F12; }
.gold-bar.on .gold-ic { background: #422006; color: #FDE68A; }
.gold-bar.on::after { content: ""; position: absolute; top: 0; bottom: 0; width: 40%; left: -40%; background: linear-gradient(100deg, transparent, rgba(255,255,255,.55), transparent); animation: goldShine 2.6s ease-in-out infinite; pointer-events: none; }
.gold-go { flex-shrink: 0; height: 36px; padding: 0 14px; border: 0; border-radius: 11px; background: #422006; color: #FDE68A; font: inherit; font-size: 12.5px; font-weight: 800; cursor: pointer; }
@keyframes goldShine { 0% { left: -40%; } 60%, 100% { left: 110%; } }
@keyframes goldPulse { 0%, 100% { box-shadow: 0 0 0 0 rgba(245,158,11,.0); } 50% { box-shadow: 0 0 0 5px rgba(245,158,11,.22); } }
.gold-x2, .gold-hint { display: none; }
body.golden-on .gold-x2 { display: inline-block; margin-top: 3px; padding: 1px 8px; border-radius: 99px; font-style: normal; font-size: 10.5px; font-weight: 900; color: #422006; background: linear-gradient(135deg, #FDE68A, #F59E0B); }
body.golden-on .gold-hint { display: flex; align-items: center; gap: 7px; margin-top: 10px; padding: 8px 11px; border-radius: 12px; font-size: 11.5px; font-weight: 800; color: #FDE68A; background: rgba(245,158,11,.14); border: 1px solid rgba(251,191,36,.4); }
.gold-hint svg { width: 15px; height: 15px; flex-shrink: 0; }
body.golden-on .fr-ring .fg { stroke: #FBBF24; filter: drop-shadow(0 0 6px rgba(251,191,36,.9)); }
body.golden-on #fcArc { stroke: #F59E0B; }
.gold-t { color: #D97706; font-weight: 800; }
.fr .gold-t { color: #FCD34D; }
@media (prefers-reduced-motion: reduce) { .gold-bar.on::after, .gold-bar.soon { animation: none; } }

/* ===== Review cards (بطاقات المراجعة) ===== */
.kd { position: relative; padding: 16px 16px calc(var(--safe-b) + 150px); }
.kd-in > * { animation: kdUp .55s cubic-bezier(.2,.8,.2,1) both; }
.kd-in > *:nth-child(2) { animation-delay: .06s; } .kd-in > *:nth-child(3) { animation-delay: .12s; } .kd-in > *:nth-child(4) { animation-delay: .18s; } .kd-in > *:nth-child(5) { animation-delay: .24s; }
@keyframes kdUp { from { opacity: 0; transform: translateY(18px); } }
.kd-loading { display: flex; justify-content: center; gap: 8px; padding: 90px 0; }
.kd-loading span { width: 34px; height: 46px; border-radius: 9px; background: rgb(var(--p)); opacity: .25; animation: kdLoad 1s ease-in-out infinite; }
.kd-loading span:nth-child(2) { animation-delay: .15s; } .kd-loading span:nth-child(3) { animation-delay: .3s; }
@keyframes kdLoad { 50% { opacity: .9; transform: translateY(-10px) rotate(-6deg); } }

.kd-ring { display: block; transform: rotate(-90deg); }
.kd-ring circle { fill: none; }
.kd-ring-bg { stroke: var(--input-bg); }
.kd-ring-fg { stroke: rgb(var(--p)); stroke-linecap: round; stroke-dashoffset: var(--c-len); animation: kdRing 1.2s .15s cubic-bezier(.2,.8,.2,1) forwards; filter: drop-shadow(0 0 6px rgba(var(--p), .45)); }
@keyframes kdRing { to { stroke-dashoffset: var(--c-off); } }

.kd-hero { position: relative; display: flex; align-items: center; gap: 16px; padding: 18px; border-radius: 26px; overflow: hidden; background: linear-gradient(135deg, rgba(var(--p), .16), rgba(139, 92, 246, .12) 60%, transparent), var(--surface); border: 1px solid var(--border); box-shadow: 0 20px 40px -26px rgba(var(--p), .55); }
.kd-hero::before { content: ''; position: absolute; width: 180px; height: 180px; left: -60px; top: -80px; border-radius: 50%; background: radial-gradient(circle, rgba(139, 92, 246, .28), transparent 70%); animation: kdFloat 7s ease-in-out infinite; pointer-events: none; }
@keyframes kdFloat { 50% { transform: translate(24px, 18px) scale(1.1); } }
.kd-hero-ring { position: relative; flex-shrink: 0; }
.kd-hero-n { position: absolute; inset: 0; display: flex; flex-direction: column; align-items: center; justify-content: center; }
.kd-hero-n b { font-size: 34px; font-weight: 900; line-height: 1; color: var(--text); font-variant-numeric: tabular-nums; }
.kd-hero-n.big b { font-size: 46px; }
.kd-hero-n small { font-size: 11.5px; color: var(--text2); margin-top: 4px; font-weight: 700; }
.kd-hero-tx { position: relative; min-width: 0; }
.kd-hero-tx > b { display: block; font-size: 17px; font-weight: 900; color: var(--text); }
.kd-hero-tx p { margin: 4px 0 10px; font-size: 12.5px; line-height: 1.7; color: var(--text2); }
.kd-chips-row { display: flex; flex-wrap: wrap; gap: 6px; }
.kd-chips-row span { display: inline-flex; align-items: center; gap: 4px; padding: 5px 9px; border-radius: 99px; background: var(--input-bg); color: var(--text2); font-size: 11.5px; font-weight: 800; }
.kd-chips-row svg { width: 13px; height: 13px; }
.kd-chips-row span.hot { color: #F97316; background: rgba(249, 115, 22, .12); }

.kd-go { position: relative; display: flex; align-items: center; justify-content: center; gap: 8px; width: 100%; margin-top: 14px; padding: 15px 16px; border: 0; border-radius: 18px; background: linear-gradient(135deg, rgb(var(--p)), #8B5CF6); color: #fff; font: inherit; font-size: 15px; font-weight: 900; box-shadow: 0 14px 28px -14px rgba(var(--p), .9); overflow: hidden; transition: transform .15s ease, opacity .2s; }
.kd-go::after { content: ''; position: absolute; inset: 0; background: linear-gradient(110deg, transparent 30%, rgba(255,255,255,.32) 50%, transparent 70%); transform: translateX(-120%); animation: kdShine 3.2s 1s ease-in-out infinite; }
@keyframes kdShine { 60%, 100% { transform: translateX(120%); } }
.kd-go:active { transform: scale(.97); }
.kd-go svg { width: 18px; height: 18px; }
.kd-go:disabled { opacity: .45; box-shadow: none; }
.kd-go:disabled::after { display: none; }
.kd-go.ghost { background: var(--input-bg); color: var(--text); box-shadow: none; }
.kd-go.ghost::after, .kd-go.danger::after { display: none; }
.kd-go.danger { background: rgba(229, 72, 77, .12); color: #E5484D; box-shadow: none; }

.kd-sec { display: flex; align-items: center; justify-content: space-between; margin: 24px 2px 10px; }
.kd-sec b { font-size: 15px; font-weight: 900; color: var(--text); }
.kd-sec button { display: inline-flex; align-items: center; gap: 5px; border: 0; background: none; color: rgb(var(--p)); font: inherit; font-size: 12.5px; font-weight: 800; }
.kd-sec svg { width: 15px; height: 15px; }
.kd-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 14px 12px; }
.kd-deck { position: relative; display: flex; flex-direction: column; align-items: flex-start; gap: 2px; min-height: 128px; padding: 14px; border: 1px solid color-mix(in srgb, var(--c) 28%, var(--border)); border-radius: 22px; background: linear-gradient(155deg, color-mix(in srgb, var(--c) 18%, var(--bg)), var(--bg) 75%); color: var(--text); font: inherit; text-align: right; box-shadow: 0 16px 30px -22px var(--c); animation: kdDeal .6s calc(var(--i) * 60ms + .2s) cubic-bezier(.2,.9,.25,1.2) both; transition: transform .2s ease; }
.kd-deck::before, .kd-deck::after { content: ''; position: absolute; inset: 0; z-index: -1; border-radius: inherit; background: color-mix(in srgb, var(--c) 22%, var(--bg)); border: 1px solid color-mix(in srgb, var(--c) 25%, transparent); transition: transform .3s cubic-bezier(.2,.8,.2,1); }
.kd-deck::before { transform: translate(-5px, 6px) rotate(-3deg); opacity: .7; }
.kd-deck::after { transform: translate(-9px, 11px) rotate(-6deg); opacity: .4; }
.kd-deck:active { transform: scale(.96); }
.kd-deck:hover::before { transform: translate(-9px, 8px) rotate(-6deg); }
.kd-deck:hover::after { transform: translate(-16px, 14px) rotate(-11deg); }
@keyframes kdDeal { from { opacity: 0; transform: translateY(40px) rotate(-6deg) scale(.9); } }
.kd-deck-bg { position: absolute; inset: 0; border-radius: inherit; overflow: hidden; pointer-events: none; }
.kd-deck-bg::after { content: ''; position: absolute; width: 90px; height: 90px; left: -30px; bottom: -40px; border-radius: 50%; background: radial-gradient(circle, color-mix(in srgb, var(--c) 45%, transparent), transparent 70%); }
.kd-deck-ic { width: 40px; height: 40px; margin-bottom: 10px; border-radius: 13px; display: grid; place-items: center; background: var(--c); color: #fff; box-shadow: 0 8px 16px -8px var(--c); }
.kd-deck-ic svg { width: 20px; height: 20px; }
.kd-deck b { position: relative; font-size: 14.5px; font-weight: 900; }
.kd-deck small { position: relative; font-size: 11.5px; color: var(--text2); font-weight: 700; }
.kd-due { position: absolute; top: 12px; left: 12px; min-width: 24px; height: 24px; padding: 0 7px; border-radius: 99px; background: #EF4444; color: #fff; font-style: normal; font-size: 12px; font-weight: 900; display: grid; place-items: center; box-shadow: 0 0 0 0 rgba(239, 68, 68, .6); animation: kdPulse 2s ease-out infinite; }
@keyframes kdPulse { 70% { box-shadow: 0 0 0 9px rgba(239, 68, 68, 0); } 100% { box-shadow: 0 0 0 0 rgba(239, 68, 68, 0); } }
.kd-bar { position: relative; display: block; width: 100%; height: 5px; margin-top: auto; padding: 0; border-radius: 99px; background: var(--input-bg); overflow: hidden; }
.kd-deck .kd-bar { margin-top: 10px; }
.kd-bar i { position: absolute; top: 0; bottom: 0; right: 0; border-radius: inherit; background: var(--c); transform-origin: right; animation: kdBar 1s .5s cubic-bezier(.2,.8,.2,1) both; }
@keyframes kdBar { from { transform: scaleX(0); } }

.kd-fab { position: fixed; left: 18px; bottom: calc(var(--safe-b) + 92px); z-index: 40; width: 60px; height: 60px; border: 0; border-radius: 20px; display: grid; place-items: center; color: #fff; background: linear-gradient(135deg, var(--c, rgb(var(--p))), #8B5CF6); box-shadow: 0 16px 30px -10px rgba(139, 92, 246, .7); animation: kdFab .6s .35s cubic-bezier(.2,1.4,.4,1) both; transition: transform .15s; }
.kd-fab svg { width: 28px; height: 28px; transition: transform .3s; }
.kd-fab:active { transform: scale(.9); }
.kd-fab:active svg { transform: rotate(90deg); }
@keyframes kdFab { from { opacity: 0; transform: scale(.3) rotate(-90deg); } }

.kd-dhead { display: flex; align-items: center; gap: 12px; padding: 16px; border-radius: 24px; background: linear-gradient(135deg, var(--c), color-mix(in srgb, var(--c) 55%, #000)); color: #fff; box-shadow: 0 18px 34px -20px var(--c); }
.kd-dhead-ic { width: 48px; height: 48px; flex-shrink: 0; border-radius: 15px; display: grid; place-items: center; background: rgba(255,255,255,.2); }
.kd-dhead-ic svg { width: 24px; height: 24px; }
.kd-dhead-tx { flex: 1; min-width: 0; }
.kd-dhead-tx b { display: block; font-size: 18px; font-weight: 900; }
.kd-dhead-tx small { font-size: 12px; opacity: .85; font-weight: 700; }
.kd-icbtn { width: 40px; height: 40px; border: 0; border-radius: 12px; display: grid; place-items: center; background: rgba(255,255,255,.16); color: #fff; }
.kd-icbtn svg { width: 18px; height: 18px; }
.kd-dbtns { display: flex; gap: 8px; }
.kd-dbtns .kd-go { flex: 1; }
.kd-dbtns .kd-go.ghost { flex: 0 0 auto; width: auto; padding-inline: 18px; }
.kd-dbtns.col { flex-direction: column; gap: 0; width: 100%; }
.kd-dbtns.col .kd-go.ghost { width: 100%; }
.kd[style*="--c"] .kd-go:not(.ghost):not(.danger) { background: linear-gradient(135deg, var(--c), color-mix(in srgb, var(--c) 60%, #8B5CF6)); box-shadow: 0 14px 28px -14px var(--c); }
.kd-search { display: flex; align-items: center; gap: 8px; margin-top: 14px; padding: 0 14px; border-radius: 14px; background: var(--input-bg); color: var(--text2); }
.kd-search svg { width: 17px; height: 17px; flex-shrink: 0; }
.kd-search input { flex: 1; min-width: 0; padding: 12px 0; border: 0; background: none; color: var(--text); font: inherit; font-size: 14px; outline: none; }
.kd-list { display: flex; flex-direction: column; gap: 8px; margin-top: 14px; }
.kd-row { display: flex; align-items: center; gap: 10px; width: 100%; padding: 13px 14px; border: 1px solid var(--border); border-right: 4px solid var(--c); border-radius: 16px; background: var(--surface); color: var(--text); font: inherit; text-align: right; animation: kdUp .45s calc(var(--i) * 35ms) cubic-bezier(.2,.8,.2,1) both; transition: transform .15s; }
.kd-row:active { transform: scale(.98); }
.kd-row-tx { flex: 1; min-width: 0; }
.kd-row-tx b, .kd-row-tx small { display: block; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.kd-row-tx b { font-size: 14px; font-weight: 800; }
.kd-row-tx small { margin-top: 2px; font-size: 12px; color: var(--text2); }
.kd-row-side { display: flex; flex-direction: column; align-items: flex-end; gap: 5px; flex-shrink: 0; }
.kd-lv { display: flex; gap: 2px; }
.kd-lv i { width: 5px; height: 12px; border-radius: 3px; background: var(--input-bg); }
.kd-lv i.on { background: var(--c); }
.kd-row-side em { font-style: normal; font-size: 10.5px; font-weight: 800; color: var(--text2); }
.kd-row-side em.due { color: #EF4444; }
.kd-none { text-align: center; color: var(--text2); font-size: 13px; padding: 24px 0; }
.kd-empty { display: flex; flex-direction: column; align-items: center; text-align: center; padding: 34px 20px 10px; }
.kd-empty b { font-size: 16px; font-weight: 900; color: var(--text); }
.kd-empty p { margin: 6px 0 0; font-size: 13px; color: var(--text2); line-height: 1.7; }
.kd-empty-art { position: relative; width: 110px; height: 110px; margin-bottom: 14px; }
.kd-empty-art span { position: absolute; left: 22px; top: 12px; width: 66px; height: 88px; border-radius: 14px; background: linear-gradient(155deg, color-mix(in srgb, var(--c) 40%, var(--bg)), var(--bg)); border: 1px solid color-mix(in srgb, var(--c) 40%, transparent); animation: kdFan 3s ease-in-out infinite; }
.kd-empty-art span:nth-child(1) { --r: -14deg; } .kd-empty-art span:nth-child(2) { --r: 0deg; animation-delay: .15s; } .kd-empty-art span:nth-child(3) { --r: 14deg; animation-delay: .3s; background: var(--c); }
@keyframes kdFan { 0%, 100% { transform: rotate(0); } 40%, 60% { transform: rotate(var(--r)) translateY(-4px); } }

/* sheets */
.kd-sheet-bg { position: fixed; inset: 0; z-index: 9000; display: flex; align-items: flex-end; justify-content: center; background: rgba(2, 6, 23, 0); transition: background .3s; }
.kd-sheet-bg.on { background: rgba(2, 6, 23, .55); backdrop-filter: blur(4px); -webkit-backdrop-filter: blur(4px); }
.kd-sheet { width: 100%; max-width: 560px; max-height: 92vh; overflow-y: auto; padding: 10px 18px calc(var(--safe-b) + 20px); border-radius: 28px 28px 0 0; background: var(--bg); border: 1px solid var(--border); border-bottom: 0; box-shadow: 0 -20px 50px -20px rgba(0,0,0,.5); transform: translateY(105%); transition: transform .42s cubic-bezier(.2,.9,.25,1.05); }
.kd-sheet-bg.on .kd-sheet { transform: none; }
.kd-sheet.kd-pop { animation: kdPop .35s ease; }
@keyframes kdPop { 40% { transform: translateY(-8px) scale(1.01); } }
.kd-grab { display: block; width: 44px; height: 5px; margin: 0 auto 12px; border-radius: 99px; background: var(--input-bg); }
.kd-sh-t { display: block; font-size: 18px; font-weight: 900; color: var(--text); margin-bottom: 8px; }
.kd-flipdemo { display: flex; align-items: center; gap: 8px; margin-bottom: 6px; color: var(--text2); font-size: 11.5px; font-weight: 800; }
.kd-flipdemo span { padding: 4px 10px; border-radius: 8px; background: var(--input-bg); }
.kd-flipdemo svg { width: 15px; height: 15px; color: rgb(var(--p)); animation: kdSpin 2.4s ease-in-out infinite; }
@keyframes kdSpin { 50% { transform: rotateY(180deg); } }
.kd-lbl { display: block; margin: 12px 2px 6px; font-size: 12.5px; font-weight: 800; color: var(--text2); }
.kd-sheet textarea, .kd-sheet input { width: 100%; padding: 12px 14px; border: 1px solid var(--border); border-radius: 14px; background: var(--input-bg); color: var(--text); font: inherit; font-size: 16px; line-height: 1.6; resize: none; outline: none; transition: border-color .2s, box-shadow .2s; }
.kd-sheet textarea:focus, .kd-sheet input:focus { border-color: rgb(var(--p)); box-shadow: 0 0 0 3px rgba(var(--p), .15); }
.kd-chips { display: flex; flex-wrap: wrap; gap: 6px; }
.kd-chips button { padding: 8px 12px; border: 1px solid color-mix(in srgb, var(--c) 35%, var(--border)); border-radius: 99px; background: none; color: var(--text); font: inherit; font-size: 12.5px; font-weight: 800; transition: all .2s; }
.kd-chips button.on { background: var(--c); border-color: var(--c); color: #fff; transform: scale(1.04); box-shadow: 0 6px 14px -8px var(--c); }
.kd-swatches { display: flex; flex-wrap: wrap; gap: 10px; }
.kd-swatches button { width: 38px; height: 38px; border-radius: 12px; border: 3px solid transparent; background: var(--c); transition: transform .2s; }
.kd-swatches button.on { border-color: var(--text); transform: scale(1.1); }
.kd-sh-btns { display: flex; gap: 8px; margin-top: 4px; }
.kd-sh-btns .kd-go { flex: 1; }

/* review */
body.kd-reviewing #bottomNav { display: none; }
.kd-rv { display: flex; flex-direction: column; min-height: calc(100vh - 150px); padding: 12px 16px calc(var(--safe-b) + 18px); }
.kd-rv-top { display: flex; align-items: center; gap: 10px; }
.kd-prog { flex: 1; height: 8px; border-radius: 99px; background: var(--input-bg); overflow: hidden; }
.kd-prog i { display: block; height: 100%; width: 0; border-radius: inherit; background: linear-gradient(90deg, #8B5CF6, rgb(var(--p))); transition: width .5s cubic-bezier(.2,.8,.2,1); box-shadow: 0 0 10px rgba(var(--p), .6); }
.kd-rv-top span { font-size: 12.5px; font-weight: 900; color: var(--text2); font-variant-numeric: tabular-nums; }
.kd-stage { position: relative; flex: 1; min-height: 330px; max-height: 470px; margin: 22px 4px 40px; }
.kd-card { position: absolute; inset: 0; perspective: 1400px; transition: transform .5s cubic-bezier(.2,.9,.25,1.1), opacity .4s ease; will-change: transform; touch-action: pan-y; user-select: none; -webkit-user-select: none; cursor: pointer; --ok: 0; --bad: 0; --hard: 0; }
.kd-card.pos0 { z-index: 3; }
.kd-card.pos1 { z-index: 2; transform: translate3d(0, 20px, 0) scale(.94); opacity: .85; }
.kd-card.pos2 { z-index: 1; transform: translate3d(0, 38px, 0) scale(.88); opacity: .55; }
.kd-card.pos3 { z-index: 0; transform: translate3d(0, 54px, 0) scale(.82); opacity: 0; }
.kd-card.pos1 .kd-inner, .kd-card.pos2 .kd-inner { filter: saturate(.7); }
.kd-card.drag { transition: none; cursor: grabbing; }
.kd-card.gone { z-index: 4; transition: transform .55s cubic-bezier(.3,.5,.3,1), opacity .55s ease; opacity: 0; pointer-events: none; }
.kd-card.deal .kd-inner { animation: kdDealCard .7s var(--d, 0ms) cubic-bezier(.2,.9,.25,1.15) backwards; }
@keyframes kdDealCard { from { opacity: 0; transform: translate3d(0, 70vh, 0) rotate(-14deg); } }
.kd-inner { position: relative; width: 100%; height: 100%; transform-style: preserve-3d; transition: transform .7s cubic-bezier(.3,1.35,.45,1); }
.kd-card.flipped .kd-inner { transform: rotateY(180deg); }
.kd-face { position: absolute; inset: 0; display: flex; flex-direction: column; align-items: center; justify-content: center; gap: 14px; padding: 28px 24px; border-radius: 30px; text-align: center; backface-visibility: hidden; -webkit-backface-visibility: hidden; overflow: hidden; }
.kd-front { background: radial-gradient(120% 80% at 50% 0%, color-mix(in srgb, var(--c) 22%, var(--bg)), var(--bg) 70%); border: 1.5px solid color-mix(in srgb, var(--c) 35%, var(--border)); box-shadow: 0 30px 60px -30px color-mix(in srgb, var(--c) 70%, transparent), inset 0 1px 0 rgba(255,255,255,.08); }
.kd-front::before { content: ''; position: absolute; inset: -40%; background: conic-gradient(from 0deg, transparent, color-mix(in srgb, var(--c) 18%, transparent), transparent 30%); animation: kdSweep 6s linear infinite; pointer-events: none; }
@keyframes kdSweep { to { transform: rotate(360deg); } }
.kd-back { transform: rotateY(180deg); background: linear-gradient(150deg, var(--c), color-mix(in srgb, var(--c) 45%, #0B1020)); color: #fff; box-shadow: 0 30px 60px -28px var(--c); }
.kd-back::before { content: ''; position: absolute; width: 70%; height: 70%; top: -25%; right: -20%; border-radius: 50%; background: radial-gradient(circle, rgba(255,255,255,.25), transparent 70%); pointer-events: none; }
.kd-face p { position: relative; margin: 0; font-size: clamp(19px, 5.4vw, 25px); font-weight: 900; line-height: 1.65; color: var(--text); overflow-wrap: anywhere; max-height: 72%; overflow: auto; }
.kd-back p { color: #fff; }
.kd-tag { position: absolute; top: 18px; right: 18px; display: inline-flex; align-items: center; gap: 5px; padding: 5px 10px; border-radius: 99px; background: color-mix(in srgb, var(--c) 16%, transparent); color: var(--c); font-size: 11.5px; font-weight: 900; }
.kd-back .kd-tag { background: rgba(255,255,255,.18); color: #fff; }
.kd-tag svg { width: 13px; height: 13px; }
.kd-face em { position: absolute; bottom: 18px; display: inline-flex; align-items: center; gap: 6px; font-style: normal; font-size: 12px; font-weight: 800; color: var(--text2); animation: kdNudge 2.2s ease-in-out infinite; }
.kd-face em svg { width: 15px; height: 15px; }
@keyframes kdNudge { 50% { transform: translateY(-4px); opacity: .6; } }
.kd-face small { position: absolute; bottom: 18px; left: 22px; right: 22px; font-size: 11.5px; opacity: .75; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.kd-card::after { content: ''; position: absolute; inset: 0; border-radius: 30px; pointer-events: none; box-shadow: 0 0 0 3px rgba(16, 185, 129, calc(var(--ok) * .9)), 0 0 50px rgba(16, 185, 129, calc(var(--ok) * .55)), 0 0 0 3px rgba(239, 68, 68, calc(var(--bad) * .9)), 0 0 50px rgba(239, 68, 68, calc(var(--bad) * .55)); }
.kd-stamp { position: absolute; top: 34px; z-index: 5; padding: 6px 14px; border: 3px solid; border-radius: 12px; font-size: 20px; font-weight: 900; opacity: 0; pointer-events: none; background: color-mix(in srgb, var(--bg) 70%, transparent); }
.kd-stamp.ok { left: 22px; color: #10B981; transform: rotate(-14deg); opacity: var(--ok); }
.kd-stamp.bad { right: 22px; color: #EF4444; transform: rotate(14deg); opacity: var(--bad); }
.kd-stamp.hard { left: 50%; top: 40%; color: #F59E0B; transform: translateX(-50%) rotate(-6deg); opacity: var(--hard); }
.kd-hint { margin: 0 0 12px; text-align: center; font-size: 12.5px; font-weight: 700; color: var(--text2); min-height: 20px; }
.kd-rate { display: grid; grid-template-columns: 1fr 1fr 1fr; gap: 10px; opacity: 0; transform: translateY(24px); pointer-events: none; transition: opacity .35s ease, transform .45s cubic-bezier(.2,1.3,.4,1); }
.kd-rate.on { opacity: 1; transform: none; pointer-events: auto; }
.kd-rate button { display: flex; flex-direction: column; align-items: center; gap: 4px; padding: 12px 6px; border: 0; border-radius: 18px; font: inherit; font-size: 12.5px; font-weight: 900; transition: transform .15s; }
.kd-rate button:active { transform: scale(.93); }
.kd-rate button svg { width: 22px; height: 22px; }
.kd-rate .bad { background: rgba(239, 68, 68, .13); color: #EF4444; }
.kd-rate .hard { background: rgba(245, 158, 11, .14); color: #D97706; }
.kd-rate .ok { background: linear-gradient(135deg, #10B981, #059669); color: #fff; box-shadow: 0 12px 24px -12px #10B981; }
.kd-rate.on button { animation: kdUp .45s cubic-bezier(.2,1.2,.4,1) both; }
.kd-rate.on button:nth-child(2) { animation-delay: .05s; } .kd-rate.on button:nth-child(3) { animation-delay: .1s; }

/* result */
.kd-done { display: flex; flex-direction: column; align-items: center; text-align: center; padding-top: 30px; overflow: hidden; }
.kd-fx { position: absolute; inset: 0; width: 100%; height: 100%; pointer-events: none; z-index: 5; }
.kd-done-ring { position: relative; animation: kdZoom .8s cubic-bezier(.2,1.4,.4,1) both; }
.kd-done-ring .kd-ring-fg { stroke: #10B981; filter: drop-shadow(0 0 10px rgba(16, 185, 129, .6)); }
@keyframes kdZoom { from { opacity: 0; transform: scale(.4) rotate(-20deg); } }
.kd-done-t { margin: 18px 10px 16px; font-size: 19px; font-weight: 900; color: var(--text); animation: kdUp .5s .3s both; }
.kd-done-stats { display: grid; grid-template-columns: repeat(3, 1fr); gap: 8px; width: 100%; animation: kdUp .5s .4s both; }
.kd-done-stats span { display: flex; flex-direction: column; align-items: center; gap: 2px; padding: 12px 6px; border-radius: 18px; background: var(--surface); border: 1px solid var(--border); font-size: 11.5px; font-weight: 800; color: var(--text2); }
.kd-done-stats b { font-size: 22px; font-weight: 900; color: var(--text); }
.kd-done-stats svg { width: 18px; height: 18px; }
.kd-done-stats .ok svg { color: #10B981; } .kd-done-stats .hard svg { color: #F59E0B; } .kd-done-stats .bad svg { color: #EF4444; }
.kd-pts { display: inline-flex; align-items: center; gap: 6px; margin-top: 14px; padding: 8px 14px; border-radius: 99px; background: rgba(245, 158, 11, .14); color: #D97706; font-size: 13px; font-weight: 900; animation: kdZoom .6s .6s both; }
.kd-pts svg { width: 16px; height: 16px; }
.kd-done .kd-dbtns { animation: kdUp .5s .5s both; }

@media (prefers-reduced-motion: reduce) {
    .kd-in > *, .kd-deck, .kd-row, .kd-fab, .kd-done-ring, .kd-done-t, .kd-done-stats, .kd-pts, .kd-rate.on button, .kd-card.deal .kd-inner { animation: none !important; }
    .kd-hero::before, .kd-front::before, .kd-go::after, .kd-due, .kd-face em, .kd-empty-art span, .kd-flipdemo svg { animation: none !important; }
    .kd-ring-fg { animation: none; stroke-dashoffset: var(--c-off); }
    .kd-inner, .kd-card { transition-duration: .01s !important; }
}
.kd-added { display: block; height: 0; overflow: hidden; color: #10B981; font-size: 12.5px; font-weight: 900; opacity: 0; transition: height .25s, opacity .25s; }
.kd-added.on { height: 22px; opacity: 1; animation: kdPop .35s ease; }

/* ===== Attack mode on the governorate war page ===== */
.gw-bt { position: relative; margin-top: 16px; padding: 16px; border-radius: 24px; color: #fff; overflow: hidden; background: radial-gradient(120% 90% at 100% 0%, rgba(239, 68, 68, .35), transparent 60%), linear-gradient(160deg, #1F0A0A, #0B1120 75%); border: 1px solid rgba(248, 113, 113, .35); box-shadow: 0 22px 44px -24px rgba(220, 38, 38, .9); animation: cardIn .5s var(--ease-out) both; }
.gw-bt::before { content: ''; position: absolute; inset: 0; background: repeating-linear-gradient(135deg, rgba(255,255,255,.025) 0 10px, transparent 10px 20px); pointer-events: none; }
.gw-bt-h { position: relative; display: flex; align-items: center; gap: 12px; }
.gw-bt-ic { width: 46px; height: 46px; flex-shrink: 0; border-radius: 15px; display: grid; place-items: center; background: linear-gradient(135deg, #EF4444, #B91C1C); box-shadow: 0 0 22px -4px #EF4444; animation: gwPulse 2s ease-in-out infinite; }
.gw-bt-ic svg { width: 24px; height: 24px; }
@keyframes gwPulse { 50% { box-shadow: 0 0 34px 2px rgba(239, 68, 68, .75); transform: scale(1.05); } }
.gw-bt-h b { display: block; font-size: 16.5px; font-weight: 900; }
.gw-bt-h small { display: block; margin-top: 2px; font-size: 11.5px; line-height: 1.6; color: rgba(254, 226, 226, .75); }
.gw-durs { position: relative; display: grid; grid-template-columns: repeat(4, 1fr); gap: 7px; margin-top: 14px; }
.gw-durs button { padding: 8px 2px 7px; border-radius: 14px; border: 1px solid rgba(255,255,255,.12); background: rgba(255,255,255,.05); color: #fff; font: inherit; cursor: pointer; transition: all .25s; }
.gw-durs b { display: block; font-size: 19px; font-weight: 900; line-height: 1.1; }
.gw-durs span { display: block; font-size: 10px; color: rgba(254, 226, 226, .6); }
.gw-durs em { display: block; margin-top: 3px; font-style: normal; font-size: 10px; font-weight: 800; color: #FCD34D; }
.gw-durs button.on { background: linear-gradient(160deg, rgba(239, 68, 68, .45), rgba(185, 28, 28, .25)); border-color: #F87171; box-shadow: 0 0 18px -4px rgba(239, 68, 68, .8); transform: translateY(-2px); }
.gw-go { position: relative; width: 100%; height: 52px; margin-top: 12px; display: flex; align-items: center; justify-content: center; gap: 8px; border: 0; border-radius: 16px; font: inherit; font-size: 16px; font-weight: 900; color: #fff; cursor: pointer; background: linear-gradient(135deg, #F97316, #DC2626 50%, #991B1B); background-size: 200% 100%; box-shadow: 0 12px 30px -10px rgba(239, 68, 68, .95); animation: frShine 3s ease-in-out infinite; }
.gw-go:active { transform: scale(.97); }
.gw-go svg { width: 20px; height: 20px; }
.gw-bt-rules { position: relative; display: flex; flex-direction: column; gap: 5px; margin-top: 11px; }
.gw-bt-rules span { display: flex; align-items: center; gap: 7px; font-size: 11px; font-weight: 600; color: rgba(254, 226, 226, .66); }
.gw-bt-rules svg { width: 14px; height: 14px; color: #FCA5A5; flex-shrink: 0; }
