/* running: the panel sticks to the bottom of the screen over the page */
body.gw-running #bottomNav { display: none; }
.gw-bt.run { position: fixed; left: 10px; right: 10px; bottom: calc(var(--safe-b) + 10px); z-index: 60; margin: 0; display: flex; align-items: center; gap: 10px; padding: 12px 14px; animation: gwRise .5s cubic-bezier(.2,1.2,.4,1) both; }
@keyframes gwRise { from { transform: translateY(120%); } }
body.gw-running #govWarContent { padding-bottom: 150px; }
.gw-bt-run { position: relative; flex: 1; min-width: 0; display: flex; align-items: center; gap: 12px; }
.gw-ring { position: relative; width: 84px; height: 84px; flex-shrink: 0; }
