.gw-quit { position: relative; flex-shrink: 0; align-self: flex-start; padding: 8px 12px; border: 1px solid rgba(255,255,255,.18); border-radius: 12px; background: rgba(255,255,255,.06); color: rgba(254, 226, 226, .85); font: inherit; font-size: 12px; font-weight: 800; cursor: pointer; }
.gw-bt.res { text-align: center; }
