@media (prefers-reduced-motion: reduce) { .gw-bt-ic, .gw-go, .gw-power i, .gw-hud-dot { animation: none; } }
.gw-ck { color: #fff; }

/* ===== 3D biology diagrams ===== */
.b3-list { padding: 16px 16px calc(var(--safe-b) + 120px); }
.b3-hero { display: flex; gap: 12px; align-items: flex-start; padding: 16px; border-radius: 22px; color: #fff; background: radial-gradient(120% 100% at 0% 0%, rgba(16, 185, 129, .5), transparent 60%), linear-gradient(150deg, #0F3D35, #0B1322); box-shadow: 0 18px 36px -22px #10B981; animation: kdUp .5s both; }
.b3-hero > svg { width: 34px; height: 34px; flex-shrink: 0; color: #6EE7B7; animation: b3Spin 6s linear infinite; }
@keyframes b3Spin { to { transform: rotateY(360deg); } }
.b3-hero b { display: block; font-size: 16px; font-weight: 900; }
.b3-hero small { display: block; margin-top: 4px; font-size: 12px; line-height: 1.75; color: rgba(236, 253, 245, .8); }
.b3-ch { display: flex; align-items: center; justify-content: space-between; margin: 22px 2px 10px; }
