.b3-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 10px; }
.b3-card { position: relative; display: flex; flex-direction: column; align-items: flex-start; gap: 8px; min-height: 112px; padding: 14px; border: 1px solid color-mix(in srgb, var(--c) 30%, var(--border)); border-radius: 20px; background: linear-gradient(160deg, color-mix(in srgb, var(--c) 16%, var(--bg)), var(--bg) 80%); color: var(--text); font: inherit; text-align: right; animation: kdDeal .55s calc(var(--i) * 50ms + .1s) cubic-bezier(.2,.9,.25,1.2) both; transition: transform .15s; overflow: hidden; }
.b3-card:active { transform: scale(.96); }
.b3-card-ic { width: 40px; height: 40px; border-radius: 13px; display: grid; place-items: center; background: var(--c); color: #fff; box-shadow: 0 8px 18px -8px var(--c); }
.b3-card-ic svg { width: 21px; height: 21px; }
.b3-card b { font-size: 13.5px; font-weight: 900; line-height: 1.5; }
.b3-card em { position: absolute; top: 12px; left: 12px; display: inline-flex; align-items: center; gap: 3px; padding: 3px 7px; border-radius: 99px; background: color-mix(in srgb, var(--c) 18%, transparent); color: var(--c); font-style: normal; font-size: 10.5px; font-weight: 900; }
.b3-card em svg { width: 12px; height: 12px; }
.b3-soon { margin: 22px 0 0; text-align: center; font-size: 12px; font-weight: 700; color: var(--text2); }
.b3-err { padding: 60px 20px; text-align: center; color: var(--text2); font-weight: 700; }

body.b3-on #bottomNav { display: none; }
body.b3-on #mainContent { padding-bottom: 0 !important; }
.b3-wrap { display: flex; flex-direction: column; height: calc(100dvh - 76px); }
.b3 { position: relative; flex: 1; min-height: 300px; overflow: hidden; touch-action: none; background: radial-gradient(90% 70% at 50% 42%, color-mix(in srgb, rgb(var(--p)) 14%, var(--bg)), var(--bg) 75%); }
