.mr-tile { position: relative; display: flex; flex-direction: column; align-items: center; justify-content: center; gap: 8px; min-height: 96px; padding: 14px 6px 12px; border-radius: 20px; text-align: center; background: var(--surface); border: 1px solid var(--border); box-shadow: 0 1px 2px rgba(0,0,0,.04); transition: transform .2s, box-shadow .25s, border-color .25s; -webkit-tap-highlight-color: transparent; }
