.yr-btn { flex: none; display: inline-flex; align-items: center; justify-content: center; gap: 6px; height: 40px; padding: 0 16px; border-radius: 12px; font-size: 13.5px; font-weight: 900; color: #fff; background: #E11D48; transition: transform .15s, opacity .2s; }
.yr-btn:active { transform: scale(.95); }
.yr-btn.wide { height: 46px; }
.yr-btn.done { background: var(--input-bg); color: var(--text2); }
.yr-btn svg { width: 17px; height: 17px; }
.yr-x { flex: none; width: 36px; height: 36px; border-radius: 11px; display: grid; place-items: center; color: var(--text2); background: var(--input-bg); }
.yr-x svg { width: 17px; height: 17px; }
.yr-inv { display: flex; align-items: center; gap: 10px; padding: 12px; border-radius: 18px; margin-bottom: 8px; background: color-mix(in srgb, #E11D48 8%, var(--surface)); border: 1px solid color-mix(in srgb, #E11D48 30%, transparent); animation: unPop .4s ease; }
.yr-inv > div { flex: 1; min-width: 0; display: flex; flex-direction: column; }
.yr-inv b { font-size: 14px; color: var(--text); }
.yr-inv small { font-size: 12px; color: var(--text2); }
.yr-recent { width: 100%; display: flex; align-items: center; gap: 10px; padding: 12px 14px; margin-bottom: 8px; border-radius: 16px; background: var(--surface); border: 1px solid var(--border); color: var(--text); font-weight: 800; font-size: 14px; text-align: right; }
.yr-recent span { flex: 1; }
.yr-recent svg { width: 18px; height: 18px; color: #E11D48; }
.yr-recent svg:last-child { color: var(--text2); }
.yr-muted { font-size: 12.5px; color: var(--text2); line-height: 1.7; padding: 10px 4px; text-align: center; }

.yr-stage { position: relative; margin: -14px -16px 0; background: #000; }
.yr-frame { position: relative; width: 100%; aspect-ratio: 16 / 9; }
.yr-frame iframe, .yr-frame #yrPlayer { position: absolute; inset: 0; width: 100%; height: 100%; border: 0; }
.yr-empty { position: absolute; inset: 0; display: flex; flex-direction: column; align-items: center; justify-content: center; gap: 8px; color: rgba(255,255,255,.6); font-size: 13px; font-weight: 700; }
.yr-empty svg { width: 34px; height: 34px; }
.yr-marks { position: relative; height: 6px; background: #1a1a1a; direction: ltr; }
.yr-marks button { position: absolute; top: -3px; width: 12px; height: 12px; margin-left: -6px; border-radius: 50%; background: #F59E0B; border: 2px solid #000; }
.yr-stage.sm { position: fixed; z-index: 45; left: 10px; bottom: 96px; width: 56%; max-width: 320px; margin: 0; border-radius: 14px; overflow: hidden; box-shadow: 0 12px 30px rgba(0,0,0,.45); animation: unPop .3s ease; }
body.yr-mini-on #yrContent { padding-top: 14px; }
.yr-stage:fullscreen { display: flex; flex-direction: column; justify-content: center; }
.yr-stage:fullscreen .yr-frame { flex: 1; aspect-ratio: auto; }
.yr-stage:-webkit-full-screen .yr-frame { height: 100%; aspect-ratio: auto; }
.yr-bar { display: flex; align-items: center; gap: 8px; margin: 10px 0 8px; }
.yr-size { flex: 1; display: flex; padding: 3px; border-radius: 13px; background: var(--input-bg); }
.yr-size button { flex: 1; display: flex; align-items: center; justify-content: center; gap: 4px; padding: 7px 0; border-radius: 10px; font-size: 11.5px; font-weight: 800; color: var(--text2); transition: background .2s, color .2s; }
.yr-size button svg { width: 15px; height: 15px; }
.yr-size button.on { background: var(--surface); color: var(--text); box-shadow: 0 1px 3px rgba(0,0,0,.08); }
.yr-q { flex: none; display: flex; align-items: center; gap: 5px; padding: 8px 12px; border-radius: 13px; font-size: 12px; font-weight: 900; color: #B45309; background: color-mix(in srgb, #F59E0B 16%, transparent); }
.yr-q svg { width: 15px; height: 15px; }
.dark .yr-q { color: #FCD34D; }
.yr-now { display: flex; align-items: center; gap: 10px; padding: 10px 12px; border-radius: 16px; background: var(--surface); border: 1px solid var(--border); }
.yr-now-t { flex: 1; min-width: 0; display: flex; flex-direction: column; }
.yr-now-t b { font-size: 13.5px; font-weight: 800; color: var(--text); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.yr-now-t small { font-size: 11.5px; color: var(--text2); }
.yr-now-t small.solo { color: #D97706; font-weight: 800; }
.yr-stack { display: flex; flex-direction: row-reverse; }
.yr-stack .yr-av { width: 28px; height: 28px; margin-left: -8px; border: 2px solid var(--surface); font-size: 11px; }
.yr-acts { display: flex; flex-wrap: wrap; gap: 6px; margin-top: 8px; }
.yr-acts:empty { display: none; }
.yr-acts button { display: flex; align-items: center; gap: 6px; padding: 8px 12px; border-radius: 12px; font-size: 12.5px; font-weight: 900; color: var(--text); background: var(--input-bg); }
.yr-acts button.go { color: #fff; background: #16A34A; animation: yrGlow 1.6s ease-in-out infinite; }
.yr-acts svg { width: 15px; height: 15px; }
@keyframes yrGlow { 50% { box-shadow: 0 0 0 6px color-mix(in srgb, #16A34A 20%, transparent); } }
.yr-tabs { display: flex; gap: 4px; margin: 12px 0 10px; padding: 3px; border-radius: 14px; background: var(--input-bg); }
.yr-tabs button { position: relative; flex: 1; display: flex; align-items: center; justify-content: center; gap: 5px; padding: 9px 0; border-radius: 11px; font-size: 12.5px; font-weight: 800; color: var(--text2); }
.yr-tabs button svg { width: 15px; height: 15px; }
.yr-tabs button.on { background: var(--surface); color: var(--text); box-shadow: 0 1px 3px rgba(0,0,0,.08); }
.yr-tabs em { font-style: normal; position: absolute; top: 3px; left: 8px; min-width: 16px; height: 16px; padding: 0 4px; border-radius: 99px; font-size: 10px; line-height: 16px; color: #fff; background: #E11D48; }
.yr-tabs em:empty { display: none; }
.yr-av { position: relative; flex: none; width: 42px; height: 42px; border-radius: 50%; overflow: hidden; display: grid; place-items: center; font-weight: 900; color: #fff; background: linear-gradient(135deg, #F43F5E, #9F1239); }
.yr-av img { width: 100%; height: 100%; object-fit: cover; }
.yr-av.s-play { box-shadow: 0 0 0 2px #16A34A; }
.yr-av.s-done { box-shadow: 0 0 0 2px #2563EB; }
.yr-people { display: flex; flex-direction: column; gap: 8px; }
.yr-p { display: flex; align-items: center; gap: 11px; padding: 10px 12px; border-radius: 16px; background: var(--surface); border: 1px solid var(--border); }
.yr-p.me-row { border-color: color-mix(in srgb, #E11D48 35%, transparent); }
.yr-p-b { flex: 1; min-width: 0; }
.yr-p-t { display: flex; align-items: center; gap: 6px; flex-wrap: wrap; }
.yr-p-t b { font-size: 13.5px; color: var(--text); }
.yr-p-t em.host { font-style: normal; font-size: 10.5px; font-weight: 900; padding: 1px 7px; border-radius: 99px; color: #B45309; background: color-mix(in srgb, #F59E0B 16%, transparent); }
.yr-p-t small { margin-right: auto; font-size: 11.5px; font-weight: 800; color: var(--text2); }
.yr-p.s-play .yr-p-t small { color: #16A34A; }
.yr-p.s-done .yr-p-t small { color: #2563EB; }
.yr-p.s-pause .yr-p-t small { color: #D97706; }
.yr-prog { height: 6px; margin: 6px 0 4px; border-radius: 99px; background: var(--input-bg); overflow: hidden; }
.yr-prog i { display: block; height: 100%; border-radius: 99px; background: linear-gradient(90deg, #E11D48, #F97316); transition: width .8s ease; }
.yr-p.s-done .yr-prog i { background: #2563EB; }
.yr-p-n { font-size: 11px; color: var(--text2); }
.yr-p.s-off { opacity: .6; }
.yr-invite-btn, .yr-menu-i { width: 100%; display: flex; align-items: center; justify-content: center; gap: 8px; margin-top: 10px; padding: 12px; border-radius: 14px; font-size: 13.5px; font-weight: 900; color: #E11D48; border: 1.5px dashed color-mix(in srgb, #E11D48 45%, transparent); }
.yr-invite-btn svg, .yr-menu-i svg { width: 17px; height: 17px; }
.yr-menu-i { justify-content: flex-start; margin-top: 0; border: 0; color: var(--text); background: var(--input-bg); }
.yr-menu-i.red { color: #DC2626; }
.yr-v { display: flex; align-items: center; gap: 10px; padding: 8px; margin-top: 8px; border-radius: 16px; background: var(--surface); border: 1px solid var(--border); }
.yr-v.cur { border-color: #E11D48; box-shadow: 0 0 0 1px #E11D48; }
.yr-v-m { position: relative; flex: none; width: 108px; aspect-ratio: 16 / 9; border-radius: 10px; overflow: hidden; background: #000; }
.yr-v-m img { width: 100%; height: 100%; object-fit: cover; }
.yr-v-n { position: absolute; top: 4px; right: 4px; min-width: 20px; height: 20px; padding: 0 5px; border-radius: 6px; font-size: 11px; font-weight: 900; line-height: 20px; color: #fff; background: rgba(0,0,0,.65); }
.yr-v-b { flex: 1; min-width: 0; cursor: pointer; }
.yr-v-b b { display: -webkit-box; -webkit-line-clamp: 2; -webkit-box-orient: vertical; overflow: hidden; font-size: 13px; color: var(--text); line-height: 1.45; }
.yr-v-b small { font-size: 11px; color: var(--text2); }
.yr-v-b small em { font-style: normal; font-weight: 900; color: #E11D48; }
.yr-chat { display: flex; flex-direction: column; gap: 6px; max-height: 46vh; overflow-y: auto; padding: 4px 2px 8px; }
.yr-msg { align-self: flex-end; max-width: 82%; padding: 8px 12px; border-radius: 16px 16px 16px 4px; background: var(--surface); border: 1px solid var(--border); }
.yr-msg.mine { align-self: flex-start; border-radius: 16px 16px 4px 16px; background: color-mix(in srgb, #E11D48 10%, var(--surface)); }
.yr-msg small { display: block; font-size: 11px; font-weight: 800; color: #E11D48; }
.yr-msg p { font-size: 13.5px; color: var(--text); line-height: 1.6; word-break: break-word; }
.yr-msg.mark { border-color: color-mix(in srgb, #F59E0B 50%, transparent); background: color-mix(in srgb, #F59E0B 10%, var(--surface)); }
.yr-msg button { display: inline-flex; align-items: center; gap: 5px; margin-top: 5px; padding: 4px 10px; border-radius: 99px; font-size: 12px; font-weight: 900; color: #fff; background: #D97706; }
.yr-msg button svg { width: 12px; height: 12px; }
.yr-send { display: flex; gap: 8px; margin-top: 6px; }
.yr-send button { flex: none; width: 44px; height: 44px; border-radius: 12px; display: grid; place-items: center; color: #fff; background: #E11D48; }
.yr-send button svg { width: 18px; height: 18px; }
.yr-fr { display: flex; flex-direction: column; gap: 8px; max-height: 50vh; overflow-y: auto; }
.yr-fr-i { display: flex; align-items: center; gap: 10px; }
.yr-fr-i b { flex: 1; font-size: 14px; color: var(--text); }
.yr-fr-i em { font-style: normal; font-size: 12px; font-weight: 800; color: #16A34A; }
.yr-pop { position: fixed; z-index: 80; top: 76px; left: 12px; right: 12px; max-width: 460px; margin: 0 auto; display: flex; align-items: center; gap: 10px; padding: 12px 14px; border-radius: 18px; color: #fff; background: linear-gradient(135deg, #E11D48, #9F1239); box-shadow: 0 16px 36px -12px rgba(159,18,57,.6); animation: yrDrop .45s cubic-bezier(.2,.8,.2,1); }
.yr-pop > svg { width: 24px; height: 24px; flex: none; }
.yr-pop > div { flex: 1; min-width: 0; display: flex; flex-direction: column; }
.yr-pop b { font-size: 14px; }
.yr-pop small { font-size: 12px; opacity: .85; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.yr-pop button { flex: none; height: 34px; min-width: 34px; padding: 0 10px; border-radius: 10px; display: grid; place-items: center; font-weight: 900; font-size: 13px; color: #fff; background: rgba(255,255,255,.18); }
.yr-pop button.go { background: #fff; color: #BE123C; }
.yr-pop button svg { width: 16px; height: 16px; }
@keyframes yrDrop { from { opacity: 0; transform: translateY(-20px); } to { opacity: 1; transform: none; } }
@media (prefers-reduced-motion: reduce) { .yr-acts button.go, .yr-pop, .yr-inv, .yr-stage.sm { animation: none; } }

.yr-spin { width: 16px; height: 16px; border-radius: 50%; border: 2.5px solid rgba(255,255,255,.35); border-top-color: #fff; animation: yrSpin .8s linear infinite; }
@keyframes yrSpin { to { transform: rotate(360deg); } }
.yr-btn:disabled { opacity: .85; }
.yr-find { display: flex; align-items: center; gap: 8px; padding: 6px 6px 6px 6px; padding-right: 12px; border-radius: 16px; background: var(--surface); border: 1.5px solid var(--border); transition: border-color .2s; }
.yr-find:focus-within { border-color: #E11D48; }
.yr-find > svg { width: 18px; height: 18px; color: var(--text2); flex: none; }
.yr-find input { flex: 1; min-width: 0; height: 40px; background: none; border: 0; outline: 0; font: inherit; font-size: 14px; color: var(--text); }
.yr-res { margin-top: 10px; padding: 10px; border-radius: 18px; background: color-mix(in srgb, #E11D48 5%, var(--surface)); border: 1px solid var(--border); animation: unPop .3s ease; }
.yr-res-h { display: flex; align-items: center; justify-content: space-between; gap: 8px; margin-bottom: 4px; }
.yr-res-h b { font-size: 13px; color: var(--text); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.yr-res-h button { flex: none; display: flex; align-items: center; gap: 4px; font-size: 12px; font-weight: 800; color: var(--text2); }
.yr-res-h button svg { width: 14px; height: 14px; }
.yr-r { display: flex; gap: 10px; padding: 8px 0; border-top: 1px solid var(--border); }
.yr-r:first-of-type { border-top: 0; }
.yr-r .yr-v-m { width: 128px; align-self: flex-start; }
.yr-len { position: absolute; bottom: 4px; left: 4px; padding: 1px 5px; border-radius: 5px; font-size: 10.5px; font-weight: 800; color: #fff; background: rgba(0,0,0,.75); direction: ltr; }
.yr-r-b { flex: 1; min-width: 0; display: flex; flex-direction: column; gap: 2px; }
.yr-r-b b { display: -webkit-box; -webkit-line-clamp: 2; -webkit-box-orient: vertical; overflow: hidden; font-size: 13px; line-height: 1.45; color: var(--text); }
.yr-r-b small { font-size: 11px; color: var(--text2); }
.yr-r-a { display: flex; gap: 6px; margin-top: 6px; flex-wrap: wrap; }
.yr-r-a button, .yr-sug-a button { display: flex; align-items: center; gap: 4px; padding: 6px 10px; border-radius: 10px; font-size: 12px; font-weight: 900; color: var(--text); background: var(--input-bg); }
.yr-r-a button.go { color: #fff; background: #E11D48; }
.yr-r-a svg, .yr-sug-a svg { width: 13px; height: 13px; }
.yr-sug { display: flex; align-items: center; gap: 8px; margin-top: 6px; padding: 6px; border-radius: 12px; background: var(--input-bg); }
.yr-sug img { width: 72px; aspect-ratio: 16 / 9; object-fit: cover; border-radius: 7px; flex: none; }
.yr-sug span { font-size: 12px; font-weight: 700; color: var(--text); display: -webkit-box; -webkit-line-clamp: 2; -webkit-box-orient: vertical; overflow: hidden; }
.yr-sug-a { display: flex; gap: 6px; margin-top: 6px; }
.yr-msg .yr-sug-a button { margin-top: 0; color: var(--text); background: var(--input-bg); }

/* landscape view, reactions, speed */
.yr-rail { display: none; }
.yr-float { position: absolute; inset: 0; pointer-events: none; overflow: hidden; }
.yr-fr-r { position: absolute; bottom: 18%; right: 14%; display: flex; flex-direction: column; align-items: center; gap: 3px; color: var(--c); animation: yrRise 2.6s ease-out forwards; }
.yr-fr-r svg { width: 34px; height: 34px; padding: 7px; border-radius: 50%; color: #fff; background: var(--c); box-shadow: 0 6px 16px rgba(0,0,0,.35); }
.yr-fr-r small { font-size: 11px; font-weight: 900; color: #fff; padding: 1px 7px; border-radius: 99px; background: rgba(0,0,0,.55); white-space: nowrap; }
@keyframes yrRise { 0% { opacity: 0; transform: translate(0, 20px) scale(.6); } 15% { opacity: 1; transform: translate(calc(var(--x) * .3), 0) scale(1.1); } 100% { opacity: 0; transform: translate(var(--x), -150px) scale(.9); } }
.yr-fr-m { position: relative; width: fit-content; max-width: 55%; direction: rtl; text-align: right; margin: 8px 10px 0 auto; padding: 6px 10px; border-radius: 12px; font-size: 12.5px; line-height: 1.5; color: #fff; background: rgba(0,0,0,.6); backdrop-filter: blur(6px); animation: yrMsgIn 6s ease forwards; }
.yr-fr-m b { display: block; font-size: 11px; color: #FDA4AF; }
@keyframes yrMsgIn { 0% { opacity: 0; transform: translateX(-20px); } 8%, 85% { opacity: 1; transform: none; } 100% { opacity: 0; } }
.yr-reacts { display: flex; gap: 6px; margin: 0 0 8px; }
.yr-reacts button { flex: 1; display: flex; align-items: center; justify-content: center; gap: 5px; padding: 7px 0; border-radius: 12px; font-size: 12px; font-weight: 900; color: var(--c); background: color-mix(in srgb, var(--c) 12%, transparent); transition: transform .15s; }
.yr-reacts button:active { transform: scale(.92); }
.yr-reacts button svg { width: 15px; height: 15px; }
.yr-reacts button.yr-sp { --c: #475569; flex: .8; }
.dark .yr-reacts button.yr-sp { --c: #CBD5E1; }
.yr-stage.land { position: fixed; z-index: 95; top: 0; left: 0; width: 100vw; height: 100vh; height: 100dvh; margin: 0; display: flex; flex-direction: row; direction: ltr; background: #000; }
.yr-stage.land.rot { width: 100vh; width: 100dvh; height: 100vw; transform-origin: 0 0; transform: rotate(90deg) translateY(-100%); }
.yr-stage.land .yr-frame { flex: 1; height: 100%; aspect-ratio: auto; }
.yr-stage.land .yr-marks { display: none; }
.yr-stage.land .yr-rail { display: flex; flex-direction: column; align-items: center; justify-content: center; gap: 8px; width: 58px; padding: 8px 0; background: #0b0b0b; }
.yr-rail button { width: 42px; height: 42px; border-radius: 13px; display: grid; place-items: center; color: #fff; background: rgba(255,255,255,.1); }
.yr-rail button[style] { color: var(--c); background: color-mix(in srgb, var(--c) 22%, transparent); }
.yr-rail button.q { color: #FCD34D; background: rgba(245,158,11,.22); }
.yr-rail button svg { width: 19px; height: 19px; }
.yr-rail b { font-size: 12px; font-weight: 900; }
.yr-rail small { font-size: 11px; font-weight: 900; color: #93C5FD; }
body.yr-land-on { overflow: hidden; }
body.yr-land-on nav, body.yr-land-on .yr-pop { visibility: hidden; }
@media (prefers-reduced-motion: reduce) { .yr-fr-r, .yr-fr-m { animation-duration: .01s; } }

/* room points */
.yr-earn { display: flex; align-items: center; gap: 10px; padding: 9px 12px; margin-bottom: 8px; border-radius: 16px; background: color-mix(in srgb, #F59E0B 10%, var(--surface)); border: 1px solid color-mix(in srgb, #F59E0B 35%, transparent); transition: background .3s, border-color .3s; }
.yr-earn:empty { display: none; }
.yr-earn.off { background: var(--surface); border-color: var(--border); }
.yr-earn-i { width: 32px; height: 32px; flex: none; border-radius: 10px; display: grid; place-items: center; color: #fff; background: linear-gradient(135deg, #FBBF24, #D97706); }
.yr-earn.off .yr-earn-i { background: var(--input-bg); color: var(--text2); }
.yr-earn-i svg { width: 17px; height: 17px; }
.yr-earn > div { flex: 1; min-width: 0; }
.yr-earn b { display: block; font-size: 12px; font-weight: 800; color: var(--text); line-height: 1.5; }
.yr-earn.off b { color: var(--text2); }
.yr-earn .yr-prog { margin: 5px 0 0; height: 5px; }
.yr-earn .yr-prog i { background: linear-gradient(90deg, #FBBF24, #D97706); }
.yr-earn em { flex: none; font-style: normal; font-size: 15px; font-weight: 900; color: #B45309; text-align: center; line-height: 1.1; }
.dark .yr-earn em { color: #FCD34D; }
.yr-earn em small { display: block; font-size: 10px; font-weight: 700; color: var(--text2); }
.yr-rail small.coin { color: #FCD34D; }
.yr-rail small.coin.off { color: #6B7280; }
.yr-coin { position: absolute; top: 40%; left: 50%; font-size: 30px; font-weight: 900; color: #FBBF24; text-shadow: 0 3px 12px rgba(0,0,0,.6); animation: yrCoin 2.2s ease-out forwards; }
@keyframes yrCoin { 0% { opacity: 0; transform: translate(-50%, 20px) scale(.5); } 20% { opacity: 1; transform: translate(-50%, 0) scale(1.2); } 100% { opacity: 0; transform: translate(-50%, -90px) scale(1); } }
.yr-check { position: absolute; inset: 0; z-index: 5; display: grid; place-items: center; background: rgba(0,0,0,.72); backdrop-filter: blur(3px); direction: rtl; animation: unPop .3s ease; }
.yr-check-c { width: min(300px, 86%); padding: 16px; border-radius: 20px; text-align: center; color: #fff; background: #111827; box-shadow: 0 20px 40px rgba(0,0,0,.5); }
.yr-check-c b { font-size: 15px; }
.yr-check-c p { font-size: 13px; opacity: .85; margin: 4px 0 12px; }
.yr-check-c strong { font-size: 22px; color: #FBBF24; }
.yr-check-o { display: grid; grid-template-columns: repeat(4, 1fr); gap: 8px; }
.yr-check-o button { height: 48px; border-radius: 14px; font-size: 20px; font-weight: 900; color: #fff; background: rgba(255,255,255,.12); transition: transform .12s; }
.yr-check-o button:active { transform: scale(.9); }
.yr-check-t { height: 4px; margin-top: 12px; border-radius: 99px; background: rgba(255,255,255,.12); overflow: hidden; }
.yr-check-t i { display: block; height: 100%; width: 100%; background: #FBBF24; transition: width 30s linear; }

/* ===== Voice note from the admin ===== */
.vn { position: relative; display: flex; align-items: center; gap: 12px; padding: 12px 14px; border-radius: 20px; background: var(--surface); border: 1px solid var(--border); box-shadow: 0 6px 18px -12px rgba(0,0,0,.25); overflow: hidden; }
.vn.new { border-color: color-mix(in srgb, rgb(var(--p)) 45%, transparent); }
.vn.new::after { content: ''; position: absolute; inset: 0; border-radius: inherit; pointer-events: none; box-shadow: inset 0 0 0 2px color-mix(in srgb, rgb(var(--p)) 35%, transparent); animation: vnPulse 2s ease-in-out infinite; }
@keyframes vnPulse { 50% { opacity: .2; } }
.vn-play { position: relative; flex: none; width: 50px; height: 50px; border-radius: 50%; display: grid; place-items: center; color: #fff; background: rgb(var(--p)); box-shadow: 0 8px 18px -8px rgb(var(--p)); transition: transform .15s; }
.vn-play:active { transform: scale(.92); }
.vn-play svg { margin-inline-start: 2px; }
.vn.playing .vn-play svg { margin: 0; }
.vn.playing .vn-play::before { content: ''; position: absolute; inset: -5px; border-radius: 50%; border: 2px solid rgb(var(--p)); opacity: .5; animation: vnRing 1.4s ease-out infinite; }
@keyframes vnRing { from { transform: scale(.9); opacity: .6; } to { transform: scale(1.25); opacity: 0; } }
.vn-spin { width: 20px; height: 20px; border-radius: 50%; border: 2.5px solid rgba(255,255,255,.35); border-top-color: #fff; animation: yrSpin .8s linear infinite; }
.vn-body { flex: 1; min-width: 0; }
.vn-top { display: flex; align-items: center; gap: 8px; }
.vn-top b { flex: 1; min-width: 0; font-size: 13.5px; font-weight: 800; color: var(--text); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.vn-top em { flex: none; font-style: normal; font-size: 10.5px; font-weight: 900; padding: 2px 8px; border-radius: 99px; color: #fff; background: #E11D48; }
.vn-wave { display: flex; align-items: center; gap: 2px; height: 30px; margin: 6px 0 2px; cursor: pointer; }
.vn-wave i { flex: 1; min-width: 2px; border-radius: 99px; background: color-mix(in srgb, var(--text2) 35%, transparent); transition: background .15s; }
.vn-wave i.on { background: rgb(var(--p)); }
.vn.playing .vn-wave i.on:last-of-type { animation: none; }
.vn-foot { display: flex; align-items: center; justify-content: space-between; }
.vn-foot span { font-size: 11.5px; font-weight: 700; color: var(--text2); direction: ltr; font-variant-numeric: tabular-nums; }
.vn-rate { font-size: 11px; font-weight: 900; padding: 2px 9px; border-radius: 99px; color: var(--text); background: var(--input-bg); }
@media (prefers-reduced-motion: reduce) { .vn.new::after, .vn.playing .vn-play::before { animation: none; } }

/* ===== شجرتي (solo focus tree) ===== */
#gardenView { animation: none !important; }
.gd { position: fixed; inset: 0; z-index: 55; overflow: hidden; color: #fff; background: linear-gradient(180deg, #7fb2e5 0%, #bcd7ee 45%, #3a2a1c 60%, #20160e 100%); }
.gd, .gd * { box-sizing: border-box; }
.gd-root { position: absolute; inset: 0; touch-action: none; }
.gd-root canvas { display: block; }
.gd-load { position: absolute; inset: 0; display: none; flex-direction: column; align-items: center; justify-content: center; gap: 12px; font-size: 14px; font-weight: 800; text-shadow: 0 2px 8px rgba(0,0,0,.4); }
.gd-root.loading .gd-load { display: flex; }
.gd-load span { width: 34px; height: 34px; border-radius: 50%; border: 3px solid rgba(255,255,255,.3); border-top-color: #fff; animation: yrSpin .9s linear infinite; }
.gd-top { position: absolute; top: 0; left: 0; right: 0; z-index: 6; display: flex; align-items: center; gap: 10px; padding: calc(var(--safe-t) + 12px) 14px 30px; background: linear-gradient(180deg, rgba(10,30,60,.45), transparent); pointer-events: none; }
.gd-top > * { pointer-events: auto; }
.gd-ic { width: 42px; height: 42px; flex: none; border-radius: 14px; display: grid; place-items: center; color: #fff; background: rgba(0,0,0,.28); backdrop-filter: blur(10px); -webkit-backdrop-filter: blur(10px); border: 1px solid rgba(255,255,255,.18); }
.gd-ic svg { width: 22px; height: 22px; }
.gd-title { flex: 1; min-width: 0; display: flex; flex-direction: column; text-shadow: 0 1px 6px rgba(0,0,0,.35); }
.gd-title b { font-size: 17px; font-weight: 900; }
.gd-title small { font-size: 12px; opacity: .85; }
.gd-stage { flex: none; padding: 7px 14px; border-radius: 99px; font-size: 13px; font-weight: 900; color: #fff; background: rgba(21,128,61,.75); border: 1px solid rgba(187,247,208,.4); backdrop-filter: blur(10px); -webkit-backdrop-filter: blur(10px); animation: unPop .4s ease; }
.gd-sheet { position: absolute; left: 12px; right: 12px; bottom: calc(var(--safe-b) + 12px); z-index: 6; max-width: 520px; margin: 0 auto; padding: 16px; border-radius: 24px; background: linear-gradient(170deg, rgba(20,40,24,.78), rgba(8,18,10,.88)); border: 1px solid rgba(187,247,208,.22); box-shadow: 0 -10px 40px -12px rgba(0,0,0,.6); backdrop-filter: blur(14px); -webkit-backdrop-filter: blur(14px); animation: frUp .5s cubic-bezier(.2,1.2,.4,1); }
.gd-sheet:empty { display: none; }
.gd-h b { display: block; font-size: 16px; font-weight: 900; }
.gd-h small { font-size: 12px; opacity: .75; }
.gd-sp { display: flex; gap: 8px; margin: 12px 0 10px; }
.gd-sp button { flex: 1; position: relative; display: flex; align-items: center; justify-content: center; gap: 7px; padding: 10px 4px; border-radius: 14px; font-size: 14px; font-weight: 900; color: #fff; background: rgba(255,255,255,.08); border: 1.5px solid transparent; transition: border-color .2s, background .2s; }
.gd-sp button.on { background: rgba(255,255,255,.16); border-color: var(--c); }
.gd-sp .dot { width: 12px; height: 12px; border-radius: 50%; background: var(--c); box-shadow: 0 0 10px var(--c); }
.gd-sp em { position: absolute; top: -6px; left: -4px; font-style: normal; font-size: 10px; min-width: 18px; padding: 1px 5px; border-radius: 99px; background: #15803D; }
.gd-durs { display: grid; grid-template-columns: repeat(5, 1fr); gap: 6px; }
.gd-durs button { display: flex; flex-direction: column; align-items: center; padding: 8px 0; border-radius: 12px; color: #fff; background: rgba(255,255,255,.07); border: 1.5px solid transparent; }
.gd-durs button.on { border-color: #4ADE80; background: rgba(74,222,128,.14); }
.gd-durs b { font-size: 17px; font-weight: 900; line-height: 1.1; }
.gd-durs small { font-size: 10.5px; opacity: .7; }
.gd-go { width: 100%; display: flex; align-items: center; justify-content: center; gap: 8px; margin-top: 12px; padding: 14px; border-radius: 16px; font-size: 16px; font-weight: 900; color: #052e16; background: linear-gradient(135deg, #86EFAC, #22C55E); box-shadow: 0 10px 24px -10px #22C55E; transition: transform .15s; }
.gd-go:active { transform: scale(.97); }
.gd-go svg { width: 20px; height: 20px; }
.gd-go em { font-style: normal; font-size: 12px; padding: 2px 8px; border-radius: 99px; background: rgba(5,46,22,.15); }
.gd-rules { display: flex; align-items: center; gap: 7px; margin-top: 10px; font-size: 11.5px; line-height: 1.6; opacity: .8; }
.gd-rules svg, .gd-warn svg { width: 15px; height: 15px; flex: none; color: #FCA5A5; }
.gd-mine { display: flex; gap: 6px; margin-top: 10px; }
.gd-mine span { flex: 1; display: flex; flex-direction: column; align-items: center; padding: 7px 0; border-radius: 12px; font-size: 10.5px; opacity: .9; background: rgba(255,255,255,.06); }
.gd-mine b { font-size: 15px; font-weight: 900; }
.gd-run { display: flex; align-items: center; gap: 14px; }
.gd-ring { position: relative; width: 92px; height: 92px; flex: none; }
.gd-ring svg { width: 100%; height: 100%; transform: rotate(-90deg); }
.gd-ring circle { fill: none; stroke-width: 7; }
.gd-ring .bg { stroke: rgba(255,255,255,.14); }
.gd-ring .fg { stroke: #4ADE80; stroke-linecap: round; transition: stroke-dashoffset .5s linear; }
.gd-ring b { position: absolute; inset: 0; display: grid; place-items: center; font-size: 21px; font-weight: 900; font-variant-numeric: tabular-nums; }
.gd-run-tx { flex: 1; min-width: 0; display: flex; flex-direction: column; gap: 3px; }
.gd-run-tx b { font-size: 15px; font-weight: 900; }
.gd-run-tx small { font-size: 12px; opacity: .8; }
.gd-run-tx em { font-style: normal; color: #86EFAC; font-weight: 900; }
.gd-warn { display: flex; align-items: center; gap: 6px; font-size: 11.5px; opacity: .8; }
.gd-quit { width: 100%; margin-top: 12px; padding: 10px; border-radius: 14px; font-size: 13px; font-weight: 800; color: #FCA5A5; background: rgba(239,68,68,.12); border: 1px solid rgba(239,68,68,.3); }
.gd-sheet.res { text-align: center; }
.gd-res-ic { width: 58px; height: 58px; margin: 0 auto 8px; border-radius: 18px; display: grid; place-items: center; background: rgba(74,222,128,.18); color: #86EFAC; }
.gd-sheet.bad .gd-res-ic { background: rgba(239,68,68,.16); color: #FCA5A5; }
.gd-res-ic svg { width: 30px; height: 30px; }
.gd-res-t { display: block; font-size: 18px; font-weight: 900; }
.gd-res-p { font-size: 13px; line-height: 1.7; opacity: .85; margin-top: 4px; }
.gd-res-p em { font-style: normal; color: #86EFAC; font-weight: 900; }
.gd-check { position: absolute; inset: 0; z-index: 20; display: flex; align-items: center; justify-content: center; padding: 20px; background: rgba(2,12,6,.7); backdrop-filter: blur(5px); -webkit-backdrop-filter: blur(5px); }
.gd-ck { width: min(340px, 100%); padding: 20px 16px; border-radius: 24px; text-align: center; background: #0f1f14; border: 1px solid rgba(187,247,208,.25); animation: unPop .35s ease; }
.gd-ck > b { display: inline-grid; place-items: center; width: 52px; height: 52px; border-radius: 50%; font-size: 20px; font-weight: 900; color: #FCD34D; border: 3px solid rgba(252,211,77,.5); }
.gd-ck strong { display: block; margin-top: 8px; font-size: 18px; }
.gd-ck p { font-size: 13px; opacity: .85; margin: 4px 0 12px; }
.gd-ck p em { font-style: normal; font-weight: 900; color: #FCD34D; font-size: 16px; }
.gd-ck-b { display: flex; justify-content: center; gap: 8px; }
.gd-ck-b button { padding: 11px 16px; border-radius: 14px; font-size: 15px; font-weight: 900; color: #fff; background: rgba(255,255,255,.1); }
.gd-ck-b button.no { animation: gdNo .4s; background: rgba(239,68,68,.35); }
@keyframes gdNo { 25% { transform: translateX(-6px); } 75% { transform: translateX(6px); } }
body.garden-running #bottomNav { display: none; }

/* ===== Bottom bar: 5 tabs, the AI tutor raised in the middle (inside the dock, so the
   travelling light around the frame stays as it is) ===== */
#bottomNav .nav-ai .nav-ic { height: 38px; width: 40px; }
#bottomNav .nav-ai-orb { width: 38px; height: 38px; border-radius: 13px; display: grid; place-items: center; color: #fff;
    background: linear-gradient(140deg, rgb(var(--p)) 0%, #6D5BF6 100%);
    box-shadow: 0 8px 18px -8px #6D5BF6, inset 0 1px 0 rgba(255,255,255,.3);
    animation: navAiBreathe 3.2s ease-in-out infinite; transition: transform .35s var(--ease-spring); }
#bottomNav .nav-ai svg { color: #fff !important; width: 20px; height: 20px; }
#bottomNav .nav-ai.active .nav-ai-orb { transform: translateY(-1px) scale(1.06); box-shadow: 0 10px 22px -8px #6D5BF6, 0 0 0 3px rgb(var(--p) / .22); }
#bottomNav .nav-ai .nav-label { font-weight: 800; color: rgb(var(--p)); }
#bottomNav:has(.nav-ai.active) .nav-indicator { opacity: 0; }
/* the tutor sits exactly in the middle: four tabs on one side, three (a little wider) on the other */
#bottomNav .nav-item { flex: 0 0 calc((100% - 58px) / 8); }
#bottomNav .nav-item.nav-ai { flex: 0 0 58px; }
#bottomNav .nav-ai ~ .nav-item { flex-basis: calc((100% - 58px) / 6); }
@keyframes navAiBreathe { 0%, 100% { box-shadow: 0 8px 18px -8px #6D5BF6, inset 0 1px 0 rgba(255,255,255,.3); } 50% { box-shadow: 0 8px 22px -6px #6D5BF6, 0 0 0 4px rgba(109,91,246,.14), inset 0 1px 0 rgba(255,255,255,.3); } }
/* 8 tabs again: the tutor's orb is sized to fit a 360px phone */
#hdrMoreBtn .nav-dot { position: absolute; top: 4px; right: 4px; width: 10px; height: 10px; border-radius: 50%; background: #EF4444; box-shadow: 0 0 0 2px var(--surface), 0 0 8px #EF4444; animation: hpBlink 1.1s ease-in-out infinite; }
#hdrMoreBtn .nav-dot.amber { background: #F59E0B; box-shadow: 0 0 0 2px var(--surface), 0 0 8px #F59E0B; }
@media (prefers-reduced-motion: reduce) { #bottomNav .nav-ai-orb { animation: none; } }

/* ===== المعلم الذكي ===== */
#tutorView { animation: none !important; }
body.tutor-on #bottomNav, body.tutor-on #appHeaderBar { display: none !important; }
.tt { position: fixed; inset: 0; z-index: 40; display: flex; flex-direction: column; background: var(--bg); }
.tt-top { flex: none; display: flex; align-items: center; gap: 10px; padding: calc(var(--safe-t) + 10px) 12px 10px; background: var(--surface); border-bottom: 1px solid var(--border); }
.tt-ic { width: 40px; height: 40px; flex: none; border-radius: 12px; display: grid; place-items: center; color: var(--text); background: var(--input-bg); }
.tt-ic svg { width: 20px; height: 20px; }
.tt-orb { width: 34px; height: 34px; flex: none; border-radius: 12px; display: grid; place-items: center; color: #fff; background: linear-gradient(140deg, rgb(var(--p)), #6D5BF6); box-shadow: 0 6px 14px -6px #6D5BF6; }
.tt-orb svg { width: 18px; height: 18px; }
.tt-orb.big { width: 64px; height: 64px; border-radius: 22px; margin: 0 auto 12px; }
.tt-orb.big svg { width: 32px; height: 32px; }
.tt-title { flex: 1; min-width: 0; display: flex; flex-direction: column; }
.tt-title b { font-size: 16px; font-weight: 900; color: var(--text); }
.tt-title small { font-size: 11.5px; color: var(--text2); }
.tt-body { flex: 1; overflow-y: auto; padding: 16px 14px 10px; display: flex; flex-direction: column; gap: 12px; overscroll-behavior: contain; }
.tt-hello, .tt-off { margin: auto 0; text-align: center; padding: 10px 6px; }
.tt-hello b, .tt-off b { display: block; font-size: 18px; font-weight: 900; color: var(--text); }
.tt-hello p, .tt-off p { font-size: 13.5px; color: var(--text2); margin: 6px 0 16px; line-height: 1.7; }
.tt-starts { display: grid; grid-template-columns: 1fr 1fr; gap: 8px; }
.tt-starts button { display: flex; align-items: center; gap: 8px; padding: 12px; border-radius: 16px; text-align: right; font-size: 13px; font-weight: 800; color: var(--text); background: var(--surface); border: 1px solid var(--border); }
.tt-starts svg { width: 18px; height: 18px; flex: none; color: #6D5BF6; }
.tt-msg { max-width: 88%; animation: unPop .3s ease; }
.tt-msg.me { align-self: flex-start; padding: 10px 14px; border-radius: 18px 18px 18px 6px; color: #fff; background: linear-gradient(140deg, rgb(var(--p)), rgb(var(--p) / .85)); }
.tt-msg.me p { font-size: 14.5px; line-height: 1.7; white-space: pre-wrap; word-break: break-word; }
.tt-msg.me img { display: block; max-width: 180px; border-radius: 12px; margin-bottom: 6px; }
.tt-msg.ai { align-self: stretch; max-width: 100%; display: flex; gap: 10px; }
.tt-txt { flex: 1; min-width: 0; padding: 12px 14px; border-radius: 6px 18px 18px 18px; background: var(--surface); border: 1px solid var(--border); color: var(--text); font-size: 14.5px; line-height: 1.85; word-break: break-word; }
.tt-txt p { margin: 0 0 8px; }
.tt-txt p:last-child { margin-bottom: 0; }
.tt-txt h4 { font-size: 15px; font-weight: 900; margin: 10px 0 4px; color: rgb(var(--p)); }
.tt-txt ul, .tt-txt ol { margin: 4px 0 8px; padding-inline-start: 20px; }
.tt-txt ul { list-style: disc; }
.tt-txt ol { list-style: decimal; }
.tt-txt li { margin: 2px 0; }
.tt-txt code { font-family: ui-monospace, monospace; font-size: 13px; padding: 1px 6px; border-radius: 6px; background: var(--input-bg); }
.tt-txt b { font-weight: 900; }
.tt-err { color: #DC2626; font-weight: 700; font-size: 13.5px; }
.tt-caret { display: inline-block; width: 7px; height: 16px; margin-inline-start: 2px; vertical-align: -3px; border-radius: 2px; background: #6D5BF6; animation: hpBlink .9s steps(2) infinite; }
.tt-typing { display: inline-flex; gap: 5px; padding: 4px 0; }
.tt-typing i { width: 7px; height: 7px; border-radius: 50%; background: #6D5BF6; animation: ttDot 1.2s ease-in-out infinite; }
.tt-typing i:nth-child(2) { animation-delay: .15s; }
.tt-typing i:nth-child(3) { animation-delay: .3s; }
@keyframes ttDot { 0%, 80%, 100% { opacity: .25; transform: translateY(0); } 40% { opacity: 1; transform: translateY(-4px); } }
.tt-composer { flex: none; padding: 8px 12px calc(var(--safe-b) + 8px); background: var(--surface); border-top: 1px solid var(--border); }
.tt-preview { position: relative; display: inline-block; margin-bottom: 8px; }
.tt-preview img { height: 64px; border-radius: 12px; display: block; }
.tt-preview button { position: absolute; top: -6px; left: -6px; width: 22px; height: 22px; border-radius: 50%; display: grid; place-items: center; color: #fff; background: #111827; }
.tt-preview button svg { width: 13px; height: 13px; }
.tt-row { display: flex; align-items: flex-end; gap: 8px; }
.tt-att { width: 44px; height: 44px; flex: none; border-radius: 14px; display: grid; place-items: center; color: #6D5BF6; background: rgba(109,91,246,.12); cursor: pointer; }
.tt-att svg { width: 21px; height: 21px; }
.tt-row textarea { flex: 1; min-width: 0; min-height: 44px; max-height: 140px; padding: 11px 14px; border-radius: 16px; resize: none; border: 1px solid var(--border); background: var(--input-bg); color: var(--text); font: inherit; font-size: 15px; line-height: 1.5; outline: 0; }
.tt-row textarea:focus { border-color: #6D5BF6; }
.tt-send { width: 44px; height: 44px; flex: none; border-radius: 14px; display: grid; place-items: center; color: #fff; background: linear-gradient(140deg, rgb(var(--p)), #6D5BF6); transition: transform .15s; }
.tt-send:active { transform: scale(.92); }
.tt-send.stop { background: #111827; }
.tt-send svg { width: 20px; height: 20px; }
.tt-note { display: block; text-align: center; font-size: 10.5px; color: var(--text2); margin-top: 6px; }
.tt-msg.ai.nudge .tt-txt { border-color: rgba(109,91,246,.45); box-shadow: 0 0 0 3px rgba(109,91,246,.08); }
.tt-go { display: inline-flex; align-items: center; gap: 6px; margin-top: 10px; padding: 9px 14px; border-radius: 12px; font-size: 13px; font-weight: 800; color: #fff; background: linear-gradient(140deg, rgb(var(--p)), #6D5BF6); }
.tt-go svg { width: 16px; height: 16px; }
.tt-pick { align-self: stretch; padding: 14px; border-radius: 18px; background: var(--surface); border: 1px solid rgba(109,91,246,.4); animation: unPop .3s ease; }
.tt-pick > b { display: block; font-size: 15px; font-weight: 900; color: var(--text); }
.tt-pick > p { font-size: 12.5px; color: var(--text2); margin: 4px 0 10px; line-height: 1.7; }
.tt-pick input { width: 100%; padding: 10px 12px; border-radius: 12px; border: 1px solid var(--border); background: var(--input-bg); color: var(--text); font: inherit; font-size: 14px; outline: 0; margin-bottom: 10px; }
.tt-pick input:focus { border-color: #6D5BF6; }
.tt-chips { display: flex; flex-wrap: wrap; gap: 8px; }
.tt-chips button { display: inline-flex; align-items: center; gap: 6px; padding: 9px 13px; border-radius: 12px; font-size: 13.5px; font-weight: 800; color: var(--text); background: var(--input-bg); border: 1px solid var(--border); }
.tt-chips button:active { transform: scale(.96); }
.tt-chips small { font-size: 11px; font-weight: 800; padding: 1px 6px; border-radius: 8px; color: #6D5BF6; background: rgba(109,91,246,.12); }
.tt-cancel { display: block; margin: 10px auto 0; font-size: 12.5px; font-weight: 700; color: var(--text2); padding: 4px 10px; }
.tq-head { display: flex; align-items: center; justify-content: space-between; gap: 8px; margin-bottom: 8px; }
.tq-head b { font-size: 15px; font-weight: 900; color: rgb(var(--p)); }
.tq-head span { flex: none; font-size: 11.5px; font-weight: 800; color: var(--text2); }
.tq-q { padding-top: 10px; margin-top: 10px; border-top: 1px dashed var(--border); animation: unPop .3s ease; }
.tq-head + .tq-q { border-top: 0; margin-top: 0; padding-top: 0; }
.tq-q > p { margin: 0 0 8px; font-weight: 700; }
.tq-ch { display: grid; gap: 6px; }
.tq-ch button { display: flex; align-items: flex-start; gap: 8px; width: 100%; padding: 9px 11px; border-radius: 12px; text-align: right; font-size: 14px; line-height: 1.6; color: var(--text); background: var(--input-bg); border: 1.5px solid transparent; transition: transform .12s; }
.tq-ch button:not([disabled]):active { transform: scale(.98); }
.tq-ch button span { flex: none; width: 22px; height: 22px; border-radius: 7px; display: grid; place-items: center; font-size: 12px; font-weight: 900; color: #6D5BF6; background: rgba(109,91,246,.12); }
.tq-ch button.ok { border-color: #16A34A; background: rgba(22,163,74,.1); }
.tq-ch button.ok span { color: #fff; background: #16A34A; }
.tq-ch button.bad { border-color: #DC2626; background: rgba(220,38,38,.08); }
.tq-ch button.bad span { color: #fff; background: #DC2626; }
.tq-ch button.off { opacity: .55; }
.tq-why { margin: 8px 0 0; font-size: 13px; line-height: 1.75; padding: 8px 10px; border-radius: 10px; }
.tq-why.ok { background: rgba(22,163,74,.08); }
.tq-why.ok b { color: #16A34A; }
.tq-why.bad { background: rgba(220,38,38,.07); }
