/* ===== خارطة الطلاب (js/moodmap.js) ===== */
body.mm-on #bottomNav, body.mm-on #appHeaderBar { display: none !important; }
#moodMapView { position: fixed; inset: 0; z-index: 40; background: #0B1220; }
.mm { position: absolute; inset: 0; overflow: hidden; color: #fff; }
.mm-map { position: absolute; inset: 0; touch-action: none; cursor: grab; background: radial-gradient(120% 80% at 50% 35%, #1B2638, #0B1220); }
.mm-map .kd-loading { position: absolute; top: 45%; left: 50%; transform: translate(-50%, -50%); }
