.mm-labels, .mm-floats { position: absolute; inset: 0; pointer-events: none; }
.mm-l { position: absolute; transform: translate(-50%, -50%) scale(var(--iz)); display: flex; flex-direction: column; align-items: center; gap: 2px; pointer-events: auto; }
.mm-lb { display: inline-flex; align-items: center; gap: 5px; padding: 3px 9px 3px 7px; border-radius: 999px; background: rgba(11, 18, 32, .78); border: 1px solid rgba(255, 255, 255, .22); box-shadow: 0 4px 12px -4px rgba(0, 0, 0, .6); backdrop-filter: blur(6px); -webkit-backdrop-filter: blur(6px); }
