.mm-stage.zoomed .mm-l small, .mm-l.sel small { display: block; }
.mm-l.sel .mm-lb { background: #FBBF24; color: #111827; border-color: #FBBF24; }
.mm-fl { position: absolute; width: 0; height: 0; transform: scale(var(--iz)); }
.mm-fl span { position: absolute; left: -19px; top: -19px; width: 38px; height: 38px; border-radius: 50%; display: grid; place-items: center; color: #fff; background: var(--c); box-shadow: 0 6px 16px -4px var(--c), 0 0 0 3px rgba(255, 255, 255, .85); animation: mmFloat 2.2s cubic-bezier(.2, .7, .3, 1) forwards; }
