.mm-top { position: absolute; top: 0; left: 0; right: 0; display: flex; align-items: center; gap: 10px; padding: calc(var(--safe-t) + 10px) 12px 18px; background: linear-gradient(rgba(11, 18, 32, .92), rgba(11, 18, 32, 0)); pointer-events: none; }
