@media (prefers-reduced-motion: reduce) { .cl-bg span, .cl-orb.cl-ringing .cl-wave, .cl-bounce, .cl-bounce::before { animation: none; } }

/* ---------- chat thread: time and ticks in the bubble, day separators ---------- */
.cm-bubble { position: relative; overflow-wrap: anywhere; }
.cm-meta { float: left; display: inline-flex; align-items: center; gap: 3px; margin: 7px 10px -3px 0; font-size: 10px; line-height: 1; opacity: .72; white-space: nowrap; }
.cm-meta-blk { float: none; display: flex; justify-content: flex-end; margin: 4px 0 0; }
