.cm-tick { display: inline-flex; }
.cm-tick svg { width: 14px; height: 14px; }
.cm-tick svg + svg, .cm-tick.read svg:first-child { display: none; }
.cm-tick.read svg + svg { display: inline; color: #93C5FD; }
.bg-primary .cm-tick.read svg + svg { color: #BFDBFE; }
.cm-day { display: flex; justify-content: center; margin: 12px 0 6px; }
.cm-day span { padding: 4px 12px; border-radius: 999px; font-size: 11px; font-weight: 700; color: var(--text2); background: var(--surface); border: 1px solid var(--border); }
.cm-newpill { position: fixed; z-index: 45; left: 50%; bottom: calc(92px + var(--safe-b)); transform: translateX(-50%); display: flex; align-items: center; gap: 6px; padding: 8px 14px; border-radius: 999px; background: var(--primary, #0F766E); color: #fff; font-size: 12px; font-weight: 800; box-shadow: 0 8px 24px rgba(0,0,0,.2); animation: clPill .3s ease; }

/* ---------- a new version is ready (js/app.js _updateReady) ---------- */
