.tb-x { flex: none; width: 30px; height: 30px; border: 0; border-radius: 10px; background: rgba(220,38,38,.1); color: #DC2626; font-size: 20px; line-height: 1; }
.tb-time { width: 110px; padding: 8px 10px; border-radius: 12px; border: 1px solid var(--border); background: var(--input-bg); color: var(--text); font: inherit; text-align: center; direction: ltr; }
.tb-add { display: flex; gap: 8px; margin-top: 10px; }
.tb-add input { flex: 1; min-width: 0; padding: 11px 12px; border-radius: 12px; border: 1px solid var(--border); background: var(--input-bg); color: var(--text); font: inherit; }
.tb-add button { padding: 0 18px; border: 0; border-radius: 12px; background: #2563EB; color: #fff; font: inherit; font-weight: 800; }
.tb-total { margin-top: 10px; font-size: 12.5px; color: var(--text2); font-weight: 700; }
.tb-total.bad { color: #DC2626; }
.tb-main { width: 100%; padding: 14px; border: 0; border-radius: 16px; background: linear-gradient(135deg, #2563EB, #7C3AED); color: #fff; font: inherit; font-size: 15px; font-weight: 800; box-shadow: 0 8px 20px rgba(79,70,229,.3); }
.tb-sec { width: 100%; padding: 13px; margin-top: 8px; border: 1px solid var(--border); border-radius: 16px; background: var(--surface); color: var(--text); font: inherit; font-weight: 700; }
.tb-main:active, .tb-sec:active, .tb-act:active { transform: scale(.97); }
.tb-gridcard { padding: 12px 8px; }
.tb-gridcard .tb-head { padding: 0 6px; }
.tb-scroll { overflow-x: auto; -webkit-overflow-scrolling: touch; padding-bottom: 4px; }
.tb-grid { width: 100%; min-width: 100%; border-collapse: separate; border-spacing: 4px; table-layout: fixed; }
.tb-grid th { background: #1D4ED8; color: #fff; border-radius: 10px; padding: 8px 2px; font-size: 11.5px; font-weight: 800; cursor: pointer; }
.tb-grid th.today { background: linear-gradient(135deg, #F97316, #DC2626); box-shadow: 0 0 0 2px rgba(249,115,22,.35); }
.tb-grid th.off { background: #64748B; }
.tb-grid th.tb-p0 { background: transparent; width: 46px; }
.tb-grid th.tb-p { background: #134E4A; width: 46px; padding: 6px 1px; }
.tb-p b { display: block; font-size: 15px; } .tb-p small { display: block; font-size: 8.5px; font-weight: 500; opacity: .85; line-height: 1.3; direction: ltr; }
.tb-c { position: relative; height: 62px; padding: 3px; text-align: center; vertical-align: middle; border-radius: 12px; background: color-mix(in srgb, var(--c) 16%, var(--surface)); border-top: 3px solid var(--c); cursor: pointer; transition: transform .15s; animation: tbIn .45s both; }
.tb-c b { display: block; font-size: 11.5px; line-height: 1.35; color: var(--text); overflow-wrap: normal; word-break: keep-all; }
.tb-c small { display: block; margin-top: 2px; font-size: 8.5px; color: var(--text2); overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.tb-c:active { transform: scale(.94); }
.tb-c.e { background: var(--input-bg); border-top-color: transparent; border: 1.5px dashed var(--border); }
.tb-c.e i { font-style: normal; font-size: 18px; color: var(--text2); opacity: .5; }
.tb-c.now { box-shadow: 0 0 0 2px #F97316, 0 0 14px rgba(249,115,22,.55); animation: tbNow 1.8s ease-in-out infinite; }
.tb-off { border-radius: 12px; text-align: center; background: repeating-linear-gradient(45deg, var(--input-bg), var(--input-bg) 8px, var(--border) 8px, var(--border) 16px); color: var(--text2); font-weight: 800; font-size: 13px; }
.tb-off span { display: inline-block; writing-mode: vertical-rl; letter-spacing: 3px; }
.tb-stats { display: grid; grid-template-columns: repeat(2, 1fr); gap: 8px; }
.tb-st { display: flex; align-items: center; gap: 8px; padding: 9px 11px; border-radius: 14px; background: color-mix(in srgb, var(--c) 12%, var(--surface)); font-size: 13px; font-weight: 700; color: var(--text); }
.tb-st i { flex: none; width: 10px; height: 10px; border-radius: 50%; background: var(--c); }
.tb-st span { flex: 1; min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.tb-st b { font-size: 15px; } .tb-st small { font-size: 10px; color: var(--text2); }
.tb-acts { display: grid; grid-template-columns: repeat(2, 1fr); gap: 8px; }
.tb-act { display: flex; align-items: center; justify-content: center; gap: 7px; padding: 13px 8px; border: 1px solid var(--border); border-radius: 16px; background: var(--surface); color: var(--text); font: inherit; font-size: 13px; font-weight: 800; transition: transform .15s; }
.tb-act svg { width: 17px; height: 17px; }
.tb-act.hi { grid-column: 1 / -1; border: 0; color: #fff; background: linear-gradient(135deg, #F97316, #DB2777); box-shadow: 0 8px 20px rgba(219,39,119,.28); }
.tb-act.warn { color: #DC2626; }
.tb-sheet { position: fixed; inset: 0; z-index: 99980; display: flex; align-items: flex-end; justify-content: center; }
.tb-back { position: absolute; inset: 0; background: rgba(15,23,42,.45); opacity: 0; transition: opacity .25s; }
.tb-sh { position: relative; width: 100%; max-width: 520px; max-height: 80vh; overflow-y: auto; padding: 12px 16px calc(18px + var(--safe-b)); border-radius: 26px 26px 0 0; background: var(--bg); color: var(--text); transform: translateY(100%); transition: transform .28s cubic-bezier(.2,.9,.3,1); }
.tb-sheet.on .tb-back { opacity: 1; } .tb-sheet.on .tb-sh { transform: none; }
.tb-grab { width: 40px; height: 5px; border-radius: 3px; background: var(--border); margin: 0 auto 12px; }
.tb-sh-t { font-size: 16px; font-weight: 800; text-align: center; margin-bottom: 12px; }
.tb-sh-t small { display: block; font-size: 12px; color: var(--text2); font-weight: 600; margin-top: 2px; direction: ltr; }
.tb-picks { display: flex; flex-wrap: wrap; gap: 8px; margin-bottom: 12px; }
.tb-pick { padding: 10px 14px; border-radius: 14px; border: 1.5px solid var(--border); background: var(--surface); color: var(--text); font: inherit; font-size: 13.5px; font-weight: 700; transition: all .15s; }
.tb-pick.on { background: var(--c, #64748B); border-color: var(--c, #64748B); color: #fff; transform: scale(1.04); }
.tb-note { width: 100%; padding: 12px; margin-bottom: 12px; border-radius: 14px; border: 1px solid var(--border); background: var(--surface); color: var(--text); font: inherit; }
@keyframes tbIn { from { opacity: 0; transform: translateY(12px); } to { opacity: 1; transform: none; } }
@keyframes tbNow { 0%, 100% { box-shadow: 0 0 0 2px #F97316, 0 0 8px rgba(249,115,22,.35); } 50% { box-shadow: 0 0 0 2px #F97316, 0 0 18px rgba(249,115,22,.75); } }
@media (prefers-reduced-motion: reduce) { .tb-hero, .tb-hero::after, .tb-card, .tb-c { animation: none !important; } }
.nt-pop.tb .nt-ic { background: linear-gradient(135deg, #2563EB, #7C3AED); animation: ntDrop 1.6s ease-in-out infinite; }
.nt-pop.tb .nt-ok { background: #2563EB; }
.tb-sw { position: relative; display: inline-block; width: 46px; height: 26px; flex: none; }
.tb-sw input { position: absolute; inset: 0; opacity: 0; width: 100%; height: 100%; margin: 0; cursor: pointer; z-index: 1; }
.tb-sw span { position: absolute; inset: 0; border-radius: 99px; background: var(--border); transition: background .2s; }
.tb-sw span::after { content: ''; position: absolute; top: 3px; right: 3px; width: 20px; height: 20px; border-radius: 50%; background: #fff; box-shadow: 0 1px 4px rgba(0,0,0,.25); transition: transform .2s; }
.tb-sw input:checked + span { background: #2563EB; }
.tb-sw input:checked + span::after { transform: translateX(-20px); }

/* ---------- المنتدى (js/forum.js) ---------- */
.fm-wrap { padding: 14px 14px 110px; display: flex; flex-direction: column; gap: 12px; }
