.fm-tabs button { flex: 1 0 auto; padding: 9px 12px; border: 0; border-radius: 12px; background: transparent; color: var(--text2); font: inherit; font-size: 12.5px; font-weight: 800; white-space: nowrap; transition: all .25s; }
.fm-tabs button.on { background: var(--surface); color: #4338CA; box-shadow: 0 2px 8px rgba(0,0,0,.1); }
.fm-subjs { display: flex; gap: 8px; overflow-x: auto; scrollbar-width: none; margin: 0 -14px; padding: 2px 14px; }
.fm-subjs button { flex: none; display: flex; align-items: center; gap: 6px; padding: 8px 13px; border-radius: 99px; border: 1.5px solid var(--border); background: var(--surface); color: var(--text2); font: inherit; font-size: 12.5px; font-weight: 800; transition: all .2s; }
.fm-subjs button svg { width: 15px; height: 15px; color: var(--c); }
.fm-subjs button.on { background: var(--c); border-color: var(--c); color: #fff; transform: scale(1.04); }
.fm-subjs button.on svg { color: #fff; }
.fm-list { display: flex; flex-direction: column; gap: 12px; }
.fm-card { position: relative; padding: 14px 14px 6px; border-radius: 22px; background: var(--surface); border: 1px solid var(--border); border-inline-start: 5px solid var(--c, #64748B); box-shadow: var(--shadow-card); cursor: pointer; transition: transform .18s, box-shadow .25s; }
.fm-card:active { transform: scale(.985); }
