.fm-av.big { width: 46px; height: 46px; }
.fm-who { min-width: 0; } .fm-who b { display: flex; align-items: center; gap: 4px; font-size: 13.5px; font-weight: 800; color: var(--text); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
