.fm-sj svg, .fm-b svg { width: 12px; height: 12px; }
.fm-b.ok { background: rgba(22,163,74,.14); color: #16A34A; }
.fm-b.wait { background: rgba(245,158,11,.16); color: #D97706; }
.fm-card h3 { margin: 4px 0 4px; font-size: 16px; font-weight: 800; line-height: 1.55; color: var(--text); }
.fm-body { margin: 0 0 8px; font-size: 13.5px; line-height: 1.85; color: var(--text); display: -webkit-box; -webkit-line-clamp: 3; -webkit-box-orient: vertical; overflow: hidden; white-space: pre-wrap; }
.fm-body.full { display: block; overflow: visible; }
.fm-img { width: 100%; max-height: 190px; object-fit: cover; border-radius: 16px; margin-bottom: 8px; background: var(--input-bg); }
.fm-img.full { max-height: 420px; }
.fm-foot { display: flex; align-items: center; gap: 4px; margin: 0 -6px; padding-top: 4px; border-top: 1px solid var(--border); }
.fm-act { display: inline-flex; align-items: center; justify-content: center; gap: 6px; padding: 9px 10px; border: 0; background: transparent; color: var(--text2); font: inherit; font-size: 12.5px; font-weight: 800; border-radius: 12px; transition: color .2s, transform .15s; }
.fm-act svg { width: 17px; height: 17px; }
.fm-act b { font-size: 12.5px; }
button.fm-act:active { transform: scale(.9); }
.fm-act.on { color: #F59E0B; } .fm-act.on svg { fill: currentColor; animation: fmPop .45s; }
.fm-act.sv { margin-inline-start: auto; } .fm-act.sv.on { color: #4338CA; }
.fm-act.del { color: #DC2626; margin-inline-start: auto; } .fm-act.ok { color: #16A34A; }
.fm-ah { margin-top: 6px; font-size: 14.5px; font-weight: 800; color: var(--text); }
.fm-ans { position: relative; padding: 13px 14px 6px; border-radius: 20px; background: var(--surface); border: 1px solid var(--border); animation: fmIn .4s both; }
