.fm-more { display: flex; justify-content: center; }
.fm-older { padding: 11px 24px; border-radius: 14px; border: 1.5px solid var(--border); background: var(--surface); color: var(--text); font: inherit; font-size: 13px; font-weight: 800; }
.fm-empty { display: flex; flex-direction: column; align-items: center; gap: 10px; padding: 40px 20px; text-align: center; color: var(--text2); font-size: 13.5px; }
