.fm-empty-i svg { width: 32px; height: 32px; }
.fm-empty button { padding: 11px 26px; border: 0; border-radius: 14px; background: linear-gradient(135deg, #4338CA, #7C3AED); color: #fff; font: inherit; font-weight: 800; }
.fm-sk { height: 150px; border-radius: 22px; background: linear-gradient(90deg, var(--input-bg) 25%, var(--surface) 50%, var(--input-bg) 75%); background-size: 200% 100%; animation: fmShim 1.4s linear infinite; }
.fm-fab { position: fixed; z-index: 40; left: 16px; bottom: calc(92px + var(--safe-b)); display: flex; align-items: center; gap: 8px; padding: 14px 20px; border: 0; border-radius: 99px; background: linear-gradient(135deg, #4338CA, #DB2777); color: #fff; font: inherit; font-size: 14px; font-weight: 800; box-shadow: 0 10px 26px rgba(124,58,237,.45); animation: fmFab 3.2s ease-in-out infinite; }
.fm-fab svg { width: 18px; height: 18px; }
.fm-fab:active { transform: scale(.93); }
#forumThreadView .fm-wrap { padding-bottom: 20px; }
.fm-sheet { position: fixed; inset: 0; z-index: 99985; display: flex; align-items: flex-end; justify-content: center; }
.fm-back { position: absolute; inset: 0; background: rgba(15,23,42,.5); opacity: 0; transition: opacity .25s; }
.fm-sh { position: relative; width: 100%; max-width: 560px; max-height: 92vh; overflow-y: auto; padding: 12px 16px calc(18px + var(--safe-b)); border-radius: 28px 28px 0 0; background: var(--bg); color: var(--text); transform: translateY(100%); transition: transform .3s cubic-bezier(.2,.9,.3,1); }
.fm-sheet.on .fm-back { opacity: 1; } .fm-sheet.on .fm-sh { transform: none; }
.fm-grab { width: 40px; height: 5px; border-radius: 3px; background: var(--border); margin: 0 auto 10px; }
.fm-sh-t { text-align: center; font-size: 17px; font-weight: 800; margin-bottom: 12px; }
.fm-pk { display: flex; gap: 8px; margin-bottom: 10px; overflow-x: auto; scrollbar-width: none; }
.fm-pk button { flex: 1 0 auto; display: flex; align-items: center; justify-content: center; gap: 6px; padding: 10px 14px; border-radius: 14px; border: 1.5px solid var(--border); background: var(--surface); color: var(--text2); font: inherit; font-size: 13px; font-weight: 800; white-space: nowrap; transition: all .2s; }
.fm-pk button svg { width: 16px; height: 16px; }
.fm-pk button.on { background: #4338CA; border-color: #4338CA; color: #fff; }
.fm-pk.sj button { flex: none; padding: 8px 13px; font-size: 12.5px; } .fm-pk.sj button.on { background: var(--c); border-color: var(--c); }
.fm-in { width: 100%; padding: 13px 14px; margin-bottom: 10px; border-radius: 16px; border: 1.5px solid var(--border); background: var(--surface); color: var(--text); font: inherit; font-size: 14px; line-height: 1.8; resize: none; outline: 0; transition: border-color .2s; }
.fm-in:focus { border-color: #7C3AED; }
.fm-prev { position: relative; margin-bottom: 10px; } .fm-prev img { width: 100%; max-height: 200px; object-fit: cover; border-radius: 16px; }
.fm-prev button { position: absolute; top: 8px; left: 8px; width: 30px; height: 30px; border: 0; border-radius: 50%; background: rgba(15,23,42,.7); color: #fff; font-size: 20px; line-height: 1; }
.fm-row { display: flex; gap: 10px; align-items: center; }
.fm-attach { display: flex; align-items: center; gap: 7px; padding: 12px 16px; border-radius: 14px; border: 1.5px dashed var(--border); color: var(--text2); font-size: 13px; font-weight: 800; cursor: pointer; }
.fm-attach svg { width: 18px; height: 18px; }
.fm-post { flex: 1; padding: 13px; border: 0; border-radius: 16px; background: linear-gradient(135deg, #4338CA, #DB2777); color: #fff; font: inherit; font-size: 15px; font-weight: 800; box-shadow: 0 8px 20px rgba(124,58,237,.35); }
.fm-post:disabled { opacity: .6; }
@keyframes fmIn { from { opacity: 0; transform: translateY(16px); } to { opacity: 1; transform: none; } }
@keyframes fmFloat { 0%, 100% { transform: translate(0, 0); } 50% { transform: translate(10px, 12px); } }
@keyframes fmPop { 0% { transform: scale(.6) rotate(-12deg); } 60% { transform: scale(1.35) rotate(8deg); } 100% { transform: none; } }
@keyframes fmShim { to { background-position: -200% 0; } }
@keyframes fmFab { 0%, 100% { transform: translateY(0); box-shadow: 0 10px 26px rgba(124,58,237,.45); } 50% { transform: translateY(-4px); box-shadow: 0 16px 30px rgba(219,39,119,.4); } }
@media (prefers-reduced-motion: reduce) { .fm-hero, .fm-hero::before, .fm-hero::after, .fm-card, .fm-ans, .fm-fab, .fm-empty-i, .fm-sk { animation: none !important; } }

/* the strip behind the system navigation bar: same colour as the page, under the floating bottom bar */
#sysBottom { position: fixed; left: 0; right: 0; bottom: 0; height: var(--safe-b); background: var(--bg, #F1F5F3); z-index: 49; pointer-events: none; }
body.focus-mode #sysBottom, body.forest-on #sysBottom { display: none; }

/* ---------- reactions on news ---------- */
.rx-ic { display: block; flex: none; filter: drop-shadow(0 1px 2px rgba(0,0,0,.18)); }
.rx-sum { display: inline-flex; align-items: center; gap: 5px; margin-inline-start: auto; font-size: 12px; font-weight: 800; color: var(--text2); }
.rx-sum:empty { display: none; }
.rx-sum + .nw-bm { margin-inline-start: 4px; }
.rx-stack { display: inline-flex; flex-direction: row-reverse; }
.rx-stack .rx-ic { margin-inline-start: -6px; box-shadow: 0 0 0 1.5px var(--surface); border-radius: 50%; }
.rx-stack .rx-ic:last-child { margin-inline-start: 0; }
.rx-bar { display: flex; align-items: center; gap: 10px; flex-wrap: wrap; margin: 14px 0 4px; padding: 10px 12px; border-radius: 18px; background: var(--input-bg); }
.rx-me { display: inline-flex; align-items: center; gap: 7px; padding: 8px 14px; border: 1.5px solid var(--border); border-radius: 99px; background: var(--surface); color: var(--text); font: inherit; font-size: 13px; font-weight: 800; transition: transform .15s, border-color .2s; }
.rx-me svg { width: 18px; height: 18px; }
.rx-me.on { border-color: var(--c); color: var(--c); animation: rxPop .45s; }
.rx-me:active { transform: scale(.94); }
.rx-chips { display: flex; flex-wrap: wrap; gap: 6px; }
