/* ===== the chat thread (js/chat.js): a fixed column sized to the visible area ===== */
.ct-root { position: fixed; left: 0; right: 0; top: var(--ct-top, 0px); height: var(--ct-h, 100dvh); z-index: 60; display: flex; flex-direction: column; background: var(--bg); }
body.ct-open { overflow: hidden; overscroll-behavior: none; }
.ct-head { flex: 0 0 auto; display: flex; align-items: center; gap: 10px; padding: calc(10px + var(--safe-t, 0px)) 14px 10px; background: var(--surface); border-bottom: 1px solid var(--border); }
.ct-ic { width: 40px; height: 40px; border-radius: 12px; background: var(--input-bg); color: var(--text); display: inline-flex; align-items: center; justify-content: center; flex: 0 0 auto; }
.ct-ic.lg { width: 44px; height: 44px; align-self: flex-end; }
.ct-pres { font-size: 11px; color: var(--text2); min-height: 15px; transition: color .2s; }
