.ct-dots { display: inline-flex; gap: 3px; margin-inline-start: 4px; vertical-align: middle; }
.ct-dots i { width: 4px; height: 4px; border-radius: 50%; background: currentColor; animation: ct-dot 1.2s infinite; }
.ct-dots i:nth-child(2) { animation-delay: .2s; } .ct-dots i:nth-child(3) { animation-delay: .4s; }
@keyframes ct-dot { 0%, 60%, 100% { transform: translateY(0); opacity: .4; } 30% { transform: translateY(-3px); opacity: 1; } }
.ct-net { flex: 0 0 auto; padding: 6px 14px; text-align: center; font-size: 12px; font-weight: 700; background: #fef3c7; color: #92400e; }
.ct-scroll { flex: 1 1 auto; min-height: 0; overflow-y: auto; overscroll-behavior: contain; -webkit-overflow-scrolling: touch; padding: 10px 14px 6px; display: flex; flex-direction: column; scroll-behavior: auto; }
.ct-list { margin-top: auto; display: flex; flex-direction: column; gap: 10px; }
.ct-empty { text-align: center; padding: 40px 0; font-size: 14px; color: var(--text2); }
.ct-skel { display: flex; flex-direction: column; gap: 10px; padding: 20px 0; } .ct-skel i { height: 38px; width: 55%; border-radius: 16px; background: var(--input-bg); animation: ct-pulse 1.2s ease-in-out infinite; } .ct-skel i:nth-child(2) { align-self: flex-end; width: 40%; } .ct-skel i:nth-child(3) { width: 65%; }
@keyframes ct-pulse { 50% { opacity: .5; } }
.ct-typing { margin-top: 6px; display: flex; }
.ct-tb { display: inline-flex; align-items: center; gap: 6px; padding: 10px 14px; border-radius: 18px 18px 18px 6px; background: var(--surface); border: 1px solid var(--border); color: var(--text2); }
.ct-tb .ct-dots { margin: 0; } .ct-tb .ct-dots i { width: 6px; height: 6px; } .ct-tb.rec { color: #ef4444; }
.ct-down { position: absolute; z-index: 5; left: 14px; bottom: calc(86px + var(--ct-reply, 0px)); width: 42px; height: 42px; border-radius: 50%; background: var(--surface); border: 1px solid var(--border); color: var(--text); display: flex; align-items: center; justify-content: center; box-shadow: 0 6px 18px rgba(0,0,0,.2); }
.ct-down b { position: absolute; top: -6px; inset-inline-end: -4px; min-width: 20px; height: 20px; padding: 0 5px; border-radius: 99px; background: rgb(var(--p)); color: #fff; font-size: 11px; display: flex; align-items: center; justify-content: center; }
.ct-down b:empty { display: none; }
.ct-reply { flex: 0 0 auto; display: flex; align-items: center; gap: 10px; padding: 8px 14px; background: var(--surface); border-top: 1px solid var(--border); }
.ct-rp { flex: 1; min-width: 0; padding: 6px 10px; border-inline-start: 3px solid rgb(var(--p)); background: var(--input-bg); border-radius: 8px; display: flex; flex-direction: column; gap: 1px; }
.ct-rp b { font-size: 12px; color: rgb(var(--p)); } .ct-rp span { font-size: 12.5px; color: var(--text2); overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
