.cm-quote { margin: 0 0 6px; padding: 5px 9px; border-inline-start: 3px solid currentColor; border-radius: 8px; background: rgba(127,127,127,.18); display: flex; flex-direction: column; gap: 1px; cursor: pointer; max-width: 240px; }
.cm-quote b { font-size: 11.5px; opacity: .9; } .cm-quote span { font-size: 12px; opacity: .85; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; display: flex; align-items: center; gap: 4px; }
.cm-flash { animation: cm-flash 1.4s ease-out; } @keyframes cm-flash { 0%, 40% { box-shadow: 0 0 0 3px rgba(250,204,21,.9); } 100% { box-shadow: 0 0 0 0 rgba(250,204,21,0); } }
.ct-img { display: block; width: min(240px, 62vw); max-width: 100%; height: auto; border-radius: 12px; object-fit: cover; background: linear-gradient(110deg, rgba(127,127,127,.18) 8%, rgba(127,127,127,.3) 18%, rgba(127,127,127,.18) 33%); background-size: 200% 100%; }
.ct-img.ld { animation: ct-shimmer 1.2s linear infinite; } .ct-img.bad { min-height: 120px; opacity: .5; }
@keyframes ct-shimmer { to { background-position-x: -200%; } }
.ct-sheetw { position: absolute; inset: 0; z-index: 8; display: flex; align-items: flex-end; justify-content: center; opacity: 0; transition: opacity .2s; } .ct-sheetw.on { opacity: 1; }
.ct-bd { position: absolute; inset: 0; background: rgba(0,0,0,.5); }
.ct-sheet { position: relative; width: min(100%, 520px); max-height: 86%; overflow-y: auto; background: var(--surface); color: var(--text); border-radius: 22px 22px 0 0; padding: 12px 14px calc(14px + var(--safe-b, 0px)); display: flex; flex-direction: column; gap: 6px; transform: translateY(40px); transition: transform .25s cubic-bezier(.2,.8,.2,1); }
.ct-sheetw.on .ct-sheet { transform: none; }
.ct-sh-prev { padding: 10px 12px; border-radius: 12px; background: var(--input-bg); color: var(--text2); font-size: 13px; max-height: 64px; overflow: hidden; margin-bottom: 4px; }
.ct-sh-h { display: flex; align-items: center; justify-content: space-between; font-size: 16px; padding: 4px 2px 8px; }
.ct-x { width: 34px; height: 34px; border-radius: 50%; background: var(--input-bg); color: var(--text); display: inline-flex; align-items: center; justify-content: center; }
.ct-act { display: flex; align-items: center; gap: 12px; height: 50px; padding: 0 12px; border-radius: 14px; background: transparent; color: var(--text); font: inherit; font-weight: 700; font-size: 14.5px; text-align: start; }
