        .menu-item { transition: background-color 0.15s ease; }
        .menu-item:hover { background-color: var(--card-hover); }
        .menu-item:active { background-color: var(--input-bg); }

        .pdf-badge { background: linear-gradient(135deg, #EF4444 0%, #DC2626 100%); }

        .theme-transition { transition: background-color 0.3s ease, border-color 0.3s ease, color 0.3s ease; }

        .bg-urgent-bg { background-color: #FEF2F2; }
        .border-urgent-border { border-color: #FECACA; }
        .bg-announcement-bg { background-color: #EFF6FF; }
        .border-announcement-border { border-color: #BFDBFE; }
        .bg-circular-bg { background-color: #F0FDF4; }
        .border-circular-border { border-color: #BBF7D0; }
        .bg-update-bg { background-color: #FFFBEB; }
        .border-update-border { border-color: #FDE68A; }
        .bg-reminder-bg { background-color: #F5F3FF; }
        .border-reminder-border { border-color: #DDD6FE; }
        .bg-general-bg { background-color: #F8FAFC; }
        .border-general-border { border-color: #E2E8F0; }

        .dark .bg-urgent-bg { background-color: rgba(220, 38, 38, 0.15) !important; }
        .dark .border-urgent-border { border-color: rgba(220, 38, 38, 0.3) !important; }
