        .dark .border-announcement-border { border-color: rgb(var(--p) / 0.3) !important; }
        .dark .bg-circular-bg { background-color: rgba(22, 163, 74, 0.15) !important; }
        .dark .border-circular-border { border-color: rgba(22, 163, 74, 0.3) !important; }
        .dark .bg-update-bg { background-color: rgba(245, 158, 11, 0.15) !important; }
        .dark .border-update-border { border-color: rgba(245, 158, 11, 0.3) !important; }
        .dark .bg-reminder-bg { background-color: rgba(139, 92, 246, 0.15) !important; }
        .dark .border-reminder-border { border-color: rgba(139, 92, 246, 0.3) !important; }
        .dark .bg-general-bg { background-color: rgba(30, 41, 59, 1) !important; }
        .dark .border-general-border { border-color: rgba(51, 65, 85, 1) !important; }

        .auth-input {
