        }
        .auth-input::placeholder { color: var(--text2); opacity: 0.6; }

        .avatar-preview { object-fit: cover; border-radius: 50%; }

        .toggle-switch { position: relative; width: 48px; height: 28px; }
        .toggle-switch input { opacity: 0; width: 0; height: 0; }
        .toggle-slider { position: absolute; cursor: pointer; top: 0; left: 0; right: 0; bottom: 0; background-color: #CBD5E1; transition: .3s; border-radius: 28px; }
        .dark .toggle-slider { background-color: #475569; }
        .toggle-slider:before { position: absolute; content: ""; height: 22px; width: 22px; left: 3px; bottom: 3px; background-color: white; transition: .3s; border-radius: 50%; }
        input:checked + .toggle-slider { background-color: rgb(var(--p)); }
        input:checked + .toggle-slider:before { transform: translateX(20px); }
        html { overflow-x: clip; }
        body { width: 100%; }
        @media (min-width: 480px) {
            .app-header, #networkBar, #ptrIndicator, nav.fixed, #toastContainer {
                left: 0; right: 0; margin-left: auto; margin-right: auto;
