        /* ===== Breaking-news ticker (continuous TV-style marquee) =====
           Headlines glide left→right the way Arabic news channels run them: the first
           headline enters from the left and is read from its right edge. Hover, press-and-
           hold, keyboard focus, the open list or the pause button all freeze it in place. */
        /* Frame with a red light that keeps travelling around the border: a large rotating
           conic "spotlight" (::before) behind an opaque inner panel (::after) inset by the
           border width, so only a 2px ring of it shows. Uses transform rotation, which
           animates in every browser (no @property needed). */
        .tk { position: relative; background: var(--border); border-radius: 16px; box-shadow: var(--shadow-card); overflow: hidden; isolation: isolate; }
        .tk::before { content: ""; position: absolute; z-index: 0; top: 50%; left: 50%; width: 150vmax; height: 150vmax; pointer-events: none;
            background: conic-gradient(from 0deg, transparent 0deg 250deg, rgba(229, 72, 77, .35) 300deg, #E5484D 345deg, #FFE1E2 356deg, transparent 360deg);
            transform: translate(-50%, -50%) rotate(0deg); animation: tkBorderSpin 4.5s linear infinite; }
        .tk::after { content: ""; position: absolute; z-index: 1; inset: 2px; border-radius: 14px; pointer-events: none;
            background: linear-gradient(var(--surface), var(--surface)), var(--bg); }
        .tk > * { position: relative; z-index: 2; }
        .tk > .tk-sr { position: absolute; }
        @keyframes tkBorderSpin { to { transform: translate(-50%, -50%) rotate(360deg); } }
        /* Two rows: label + controls on top, the full card width for the headlines below —
           a single row left the text a narrow strip between the label and the buttons. */
        .tk-head { display: flex; align-items: center; gap: 6px; padding: 7px 8px 0; }
        .tk-count { flex: 1; min-width: 0; font-size: 11px; font-weight: 600; color: var(--text2); }
        .tk-live { position: relative; z-index: 2; flex-shrink: 0; display: inline-flex; align-items: center; gap: 7px; height: 24px; padding: 0 10px; border-radius: 8px; font-size: 11.5px; font-weight: 700; color: #fff; background: linear-gradient(135deg, #EF5A5F, #B42328); box-shadow: 0 8px 16px -8px rgba(229, 72, 77, .8); }
        .tk-dot { position: relative; width: 7px; height: 7px; border-radius: 50%; background: #fff; }
        .tk-dot::after { content: ""; position: absolute; inset: 0; border-radius: 50%; background: #fff; animation: tkPulse 1.6s ease-out infinite; }
        @keyframes tkPulse { from { transform: scale(1); opacity: .8; } to { transform: scale(2.8); opacity: 0; } }
        .tk-viewport { position: relative; height: 38px; margin: 2px 0 3px; overflow: hidden; direction: ltr; cursor: pointer; touch-action: pan-y;
            -webkit-mask-image: linear-gradient(to right, transparent, #000 18px, #000 calc(100% - 18px), transparent);
            mask-image: linear-gradient(to right, transparent, #000 18px, #000 calc(100% - 18px), transparent); }
        .tk-track { position: absolute; top: 0; bottom: 0; left: 0; display: flex; align-items: center; width: max-content; will-change: transform; animation: tkMarquee var(--tk-dur, 30s) linear infinite; }
        .tk.tk-paused .tk-track { animation-play-state: paused; }
        @keyframes tkMarquee { from { transform: translate3d(-50%, 0, 0); } to { transform: translate3d(0, 0, 0); } }
        .tk-chip { direction: rtl; display: inline-flex; align-items: center; gap: 8px; white-space: nowrap; font-size: 14.5px; line-height: 1.4; font-weight: 600; color: var(--text); padding: 4px 6px; border-radius: 10px; transition: background-color .2s ease; }
        .tk-chip:hover { background: var(--input-bg); }
        .tk-new { font-size: 10px; font-weight: 700; line-height: 1; color: #fff; background: var(--error); padding: 4px 6px; border-radius: 6px; }
        .tk-time { font-size: 11px; font-weight: 500; color: var(--text2); }
        .tk-sep { flex-shrink: 0; width: 6px; height: 6px; margin: 0 18px; border-radius: 1.5px; background: var(--error); transform: rotate(45deg); opacity: .85; }
        .tk-btn { position: relative; z-index: 2; flex-shrink: 0; width: 26px; height: 26px; border-radius: 8px; display: grid; place-items: center; color: var(--text2); background: var(--input-bg); border: 0; cursor: pointer; transition: background-color .2s ease, color .2s ease, transform .15s ease; }
        .tk-btn:hover { color: var(--text); }
        .tk-btn:active { transform: scale(.92); }
        .tk.tk-open #tkMore { background: rgb(var(--p) / 0.14); color: rgb(var(--p)); }
        .tk-btn:focus-visible, .tk-viewport:focus-visible, .tk-item:focus-visible { outline: 2px solid var(--primary); outline-offset: 2px; }
        .tk-sr { position: absolute; width: 1px; height: 1px; overflow: hidden; clip: rect(0 0 0 0); white-space: nowrap; }
        @media (prefers-reduced-motion: reduce) { #tkToggle { display: none; } }

        /* Fallback for Tailwind's `hidden` (same rule the admin panel has): every screen is
           switched with this class, so if the Tailwind CDN is blocked or slow all screens
           used to render on top of each other. !important matches Tailwind, where `hidden`
           always wins over `flex`/`block` on the same element. */
        .hidden { display: none !important; }

        /* ===== Holidays strip: compact chips that step along like a ticker =====
           Small enough for a card per governorate (18+). The strip slides one chip, rests,
           then slides again ("stop-and-go"); touch, hover or leaving the home screen pause it. */
        .hl-head { display: flex; align-items: center; justify-content: space-between; margin-bottom: 8px; }
        .hl-title { display: inline-flex; align-items: center; gap: 8px; font-size: 14px; font-weight: 700; color: var(--text); }
        .hl-live { position: relative; width: 8px; height: 8px; border-radius: 50%; background: var(--success, #16A34A); }
        .hl-live::after, .hl-dot::after { content: ""; position: absolute; inset: 0; border-radius: 50%; background: inherit; animation: tkPulse 1.6s ease-out infinite; }
        .hl-count { font-size: 11px; font-weight: 600; color: var(--text2); background: var(--input-bg); padding: 3px 8px; border-radius: 999px; }
        .hl-viewport { position: relative; overflow: hidden; touch-action: pan-y;
            -webkit-mask-image: linear-gradient(to left, transparent, #000 14px, #000 calc(100% - 22px), transparent);
            mask-image: linear-gradient(to left, transparent, #000 14px, #000 calc(100% - 22px), transparent); }
        .hl-track { display: flex; gap: 8px; width: max-content; padding: 2px 2px 4px; will-change: transform; }
        .hl-track.hl-sliding { transition: transform .7s cubic-bezier(.65, 0, .35, 1); }
        /* No max-width / ellipsis: the governorate and the holiday name must always show in full. */
        .hl-chip { flex-shrink: 0; display: flex; align-items: center; gap: 9px; padding: 7px 12px 7px 10px; border-radius: 14px;
            background: var(--surface); border: 1px solid var(--border); box-shadow: var(--shadow-card); animation: hlIn .5s var(--ease-out) both; }
        @keyframes hlIn { from { opacity: 0; transform: translateY(6px) scale(.97); } to { opacity: 1; transform: none; } }
        .hl-dot { position: relative; flex-shrink: 0; width: 8px; height: 8px; border-radius: 50%; }
        .hl-chip.is-now .hl-dot { background: #16A34A; }
        .hl-chip.is-soon .hl-dot { background: #F59E0B; }
        .hl-chip.is-later .hl-dot { background: var(--text2); }
        .hl-chip.is-later .hl-dot::after { animation: none; }
        .hl-body { min-width: 0; line-height: 1.3; }
        .hl-gov { display: flex; align-items: center; gap: 4px; font-size: 13px; font-weight: 800; color: var(--text); white-space: nowrap; }
        .hl-pin { font-size: 12px; line-height: 1; }
        .hl-name { display: flex; align-items: center; gap: 6px; margin-top: 2px; font-size: 12px; font-weight: 600; color: var(--text); white-space: nowrap; }
        .hl-tag { flex-shrink: 0; font-size: 9.5px; font-weight: 700; padding: 1px 6px; border-radius: 6px; }
        .hl-tag.gov { color: rgb(var(--p)); background: rgb(var(--p) / 0.12); }
        .hl-tag.school { color: #16A34A; background: rgba(22, 163, 74, 0.12); }
        .hl-meta { font-size: 11px; color: var(--text2); white-space: nowrap; }
        .hl-meta b { font-weight: 700; }
        .hl-chip.is-now .hl-meta b { color: #16A34A; }
        .hl-chip.is-soon .hl-meta b { color: #D97706; }

        /* Exam countdown chips reuse the holiday strip (.hl-*). Colour = urgency:
           red under a day, amber within a week, primary otherwise. */
        .ex-live { background: #E5484D; }
        .ex-chip .hl-dot { background: rgb(var(--p)); }
        .ex-chip.is-urgent .hl-dot { background: #E5484D; }
        .ex-chip.is-soon .hl-dot { background: #F59E0B; }
        .ex-date { flex-shrink: 0; font-size: 9.5px; font-weight: 700; padding: 1px 6px; border-radius: 6px; color: var(--text2); background: var(--input-bg); }
        .ex-clock { display: flex; align-items: baseline; gap: 5px; margin-top: 2px; font-size: 12px; font-weight: 700; color: rgb(var(--p)); white-space: nowrap; font-variant-numeric: tabular-nums; }
        .ex-chip.is-urgent .ex-clock { color: #E5484D; }
        .ex-chip.is-soon .ex-clock { color: #D97706; }
        .ex-clock small { font-size: 10px; font-weight: 600; color: var(--text2); }

        /* Daily tip: same header/dot as the holiday & exam strips; the tips themselves are
           full-width slides that step along (today's tip first, a long rest to read each). */
        .tip-live { background: #8B5CF6; }
        .tip-tools { display: inline-flex; align-items: center; gap: 6px; }
        .tip-x { width: 24px; height: 24px; border-radius: 8px; display: grid; place-items: center; color: #8B5CF6; background: var(--reminder-bg); border: 0; cursor: pointer; }
        .tip-card { border-radius: 16px; background: var(--reminder-bg); border: 1px solid var(--reminder-border); -webkit-mask-image: none; mask-image: none; }
        .tip-track { padding: 0; }
        .tip-slide { box-sizing: border-box; flex: 0 0 auto; display: flex; align-items: flex-start; gap: 10px; padding: 10px 12px; }
        .tip-ic { flex-shrink: 0; width: 28px; height: 28px; border-radius: 9px; display: grid; place-items: center; font-size: 15px; background: rgba(139, 92, 246, 0.12); }
        .tip-text { font-size: 13px; line-height: 1.65; font-weight: 500; color: var(--text); display: -webkit-box; -webkit-box-orient: vertical; -webkit-line-clamp: 2; overflow: hidden; min-height: calc(13px * 1.65 * 2); }

        /* ===== Holidays calendar page (تقويم العطل) ===== */
        .hp-hero { position: relative; overflow: hidden; border-radius: 22px; padding: 16px; color: #fff;
            background: linear-gradient(135deg, rgb(var(--p)), #0B5E54 55%, #134E4A); box-shadow: 0 18px 36px -18px rgb(var(--p) / 0.9); }
        .hp-hero::before { content: ""; position: absolute; inset: -40% -20% auto auto; width: 70%; height: 180%; background: radial-gradient(closest-side, rgba(255,255,255,.18), transparent); animation: hpFloat 7s ease-in-out infinite alternate; }
        .hp-hero::after { content: ""; position: absolute; inset: 0; background: linear-gradient(110deg, transparent 30%, rgba(255,255,255,.12) 45%, transparent 60%); background-size: 250% 100%; animation: hpShine 5s ease-in-out infinite; }
        @keyframes hpFloat { to { transform: translate(-30%, 20%); } }
        @keyframes hpShine { 0% { background-position: 120% 0; } 60%, 100% { background-position: -120% 0; } }
        .hp-hero > * { position: relative; z-index: 1; }
        .hp-hero-top { display: flex; align-items: center; justify-content: space-between; gap: 10px; margin-bottom: 14px; }
        .hp-hero-title { font-size: 16px; font-weight: 800; }
        .hp-hero-sub { font-size: 11.5px; opacity: .85; margin-top: 2px; }
        .hp-hero-ic { width: 44px; height: 44px; border-radius: 14px; display: grid; place-items: center; background: rgba(255,255,255,.16); font-size: 22px; animation: hpBob 3s ease-in-out infinite; }
        @keyframes hpBob { 50% { transform: translateY(-4px) rotate(-6deg); } }
        .hp-stats { display: grid; grid-template-columns: repeat(3, 1fr); gap: 8px; }
        .hp-stat { background: rgba(255,255,255,.13); border: 1px solid rgba(255,255,255,.18); border-radius: 14px; padding: 9px 6px; text-align: center; }
        .hp-stat b { display: block; font-size: 22px; font-weight: 800; line-height: 1.1; font-variant-numeric: tabular-nums; }
        .hp-stat span { font-size: 10.5px; opacity: .9; }
        .hp-sec-title { display: flex; align-items: center; justify-content: space-between; margin: 18px 2px 10px; font-size: 14px; font-weight: 800; color: var(--text); }
        .hp-sec-title small { font-size: 11px; font-weight: 600; color: var(--text2); }
        .hp-govs { display: grid; grid-template-columns: repeat(3, 1fr); gap: 8px; }
        .hp-gov { position: relative; display: flex; flex-direction: column; align-items: flex-start; gap: 3px; padding: 9px 10px; border-radius: 14px; text-align: start;
            background: var(--surface); border: 1px solid var(--border); box-shadow: var(--shadow-card); cursor: pointer; color: var(--text);
            animation: hpPop .45s var(--ease-spring) both; transition: transform .15s ease, border-color .2s ease, background-color .2s ease; }
        .hp-gov:active { transform: scale(.95); }
        .hp-gov.all { grid-column: 1 / -1; flex-direction: row; align-items: center; justify-content: space-between; }
        .hp-gov.sel { border-color: rgb(var(--p)); background: rgb(var(--p) / 0.08); box-shadow: 0 0 0 3px rgb(var(--p) / 0.14); }
        @keyframes hpPop { from { opacity: 0; transform: scale(.85) translateY(8px); } to { opacity: 1; transform: none; } }
        .hp-gov-name { display: flex; align-items: center; gap: 6px; font-size: 12.5px; font-weight: 800; white-space: nowrap; }
        .hp-gov-meta { font-size: 10.5px; color: var(--text2); }
        .hp-gov .hl-dot { width: 7px; height: 7px; }
        .hp-gov.is-now .hl-dot { background: #16A34A; }
        .hp-gov.is-soon .hl-dot { background: #F59E0B; }
        .hp-gov.is-later .hl-dot { background: rgb(var(--p)); }
        /* no holiday in this governorate → red dot that keeps blinking */
        .hp-gov.is-none .hl-dot { background: #E5484D; animation: hpBlink 1.1s ease-in-out infinite; }
        .hp-gov.is-later .hl-dot::after { animation: none; }
        @keyframes hpBlink { 0%, 100% { opacity: 1; box-shadow: 0 0 0 0 rgba(229, 72, 77, .55); } 50% { opacity: .35; box-shadow: 0 0 0 4px rgba(229, 72, 77, 0); } }
        .hp-gov.is-none .hp-gov-meta { color: #E5484D; font-weight: 600; }
        .hp-filters { display: flex; gap: 6px; overflow-x: auto; padding-bottom: 2px; }
        .hp-filter { flex-shrink: 0; padding: 7px 13px; border-radius: 999px; font-size: 12px; font-weight: 700; background: var(--surface); color: var(--text2); border: 1px solid var(--border); cursor: pointer; transition: all .2s ease; }
        .hp-filter.on { background: rgb(var(--p)); color: #fff; border-color: transparent; box-shadow: 0 8px 16px -10px rgb(var(--p)); }
        .hp-list { display: flex; flex-direction: column; gap: 10px; }
        .hp-card { display: flex; gap: 12px; padding: 12px; border-radius: 18px; background: var(--surface); border: 1px solid var(--border); box-shadow: var(--shadow-card); animation: cardIn .5s var(--ease-out) both; }
        .hp-date { flex-shrink: 0; width: 54px; border-radius: 14px; display: flex; flex-direction: column; align-items: center; justify-content: center; padding: 6px 0; color: #fff;
            background: linear-gradient(160deg, rgb(var(--p)), rgb(var(--p) / 0.75)); }
        .hp-card.is-now .hp-date { background: linear-gradient(160deg, #22C55E, #15803D); }
        .hp-card.is-soon .hp-date { background: linear-gradient(160deg, #FBBF24, #D97706); }
        .hp-date b { font-size: 21px; font-weight: 800; line-height: 1; }
        .hp-date span { font-size: 10px; font-weight: 700; margin-top: 3px; opacity: .95; }
        .hp-body { flex: 1; min-width: 0; }
        .hp-title { display: flex; align-items: center; gap: 6px; flex-wrap: wrap; font-size: 14px; font-weight: 800; color: var(--text); }
        .hp-where { margin-top: 3px; font-size: 12px; font-weight: 700; color: var(--text); }
        .hp-range { margin-top: 2px; font-size: 11px; color: var(--text2); }
        .hp-status { display: flex; align-items: center; gap: 6px; margin-top: 6px; font-size: 11.5px; font-weight: 700; color: rgb(var(--p)); }
        .hp-card.is-now .hp-status { color: #16A34A; }
        .hp-card.is-soon .hp-status { color: #D97706; }
        .hp-bar { height: 5px; margin-top: 6px; border-radius: 99px; background: var(--input-bg); overflow: hidden; }
        .hp-bar i { display: block; height: 100%; width: var(--w, 0%); border-radius: inherit; background: linear-gradient(90deg, #22C55E, #86EFAC); transform-origin: right; animation: hpGrow 1.1s var(--ease-out) both .2s; }
        @keyframes hpGrow { from { transform: scaleX(0); } }
        .hp-empty { text-align: center; padding: 36px 16px; color: var(--text2); font-size: 13px; }
