        .fc-durs { display: grid; grid-template-columns: repeat(4, 1fr); gap: 8px; }
        .fc-dur { display: flex; flex-direction: column; align-items: center; gap: 2px; padding: 12px 4px; border-radius: 18px; border: 1.5px solid var(--border); background: var(--surface); box-shadow: var(--shadow-card); cursor: pointer; color: var(--text); transition: all .2s ease; animation: hpPop .45s var(--ease-spring) both; }
        .fc-dur b { font-size: 22px; font-weight: 900; line-height: 1.1; font-variant-numeric: tabular-nums; }
        .fc-dur span { font-size: 11px; color: var(--text2); font-weight: 600; }
        .fc-dur em { margin-top: 4px; font-style: normal; font-size: 10.5px; font-weight: 800; color: #D97706; background: rgba(245,158,11,.12); padding: 1px 7px; border-radius: 99px; }
        .fc-dur.on { border-color: rgb(var(--p)); background: rgb(var(--p) / 0.07); box-shadow: 0 0 0 3px rgb(var(--p) / 0.15); }
        .fc-rules { display: flex; flex-direction: column; gap: 8px; }
        .fc-rule { display: flex; align-items: center; gap: 12px; padding: 11px 12px; border-radius: 16px; background: var(--surface); border: 1px solid var(--border); font-size: 12.5px; color: var(--text); line-height: 1.6; }
        .fc-rule span { flex-shrink: 0; width: 34px; height: 34px; border-radius: 11px; display: grid; place-items: center; color: var(--c); background: color-mix(in srgb, var(--c) 13%, transparent); }
        .fc-rule svg { width: 17px; height: 17px; }
        .fc-start { width: 100%; height: 56px; margin-top: 18px; border: 0; border-radius: 18px; display: flex; align-items: center; justify-content: center; gap: 10px; font-size: 16px; font-weight: 900; color: #fff; cursor: pointer;
            background: linear-gradient(135deg, rgb(var(--p)), #0B5E54); box-shadow: 0 16px 30px -14px rgb(var(--p)); }
        .fc-start svg { width: 20px; height: 20px; }
        .fc-stats { display: grid; grid-template-columns: repeat(3, 1fr); gap: 8px; }
        .fc-stat { text-align: center; padding: 11px 4px; border-radius: 16px; background: var(--surface); border: 1px solid var(--border); box-shadow: var(--shadow-card); }
        .fc-stat b { display: block; font-size: 19px; font-weight: 900; color: var(--c); font-variant-numeric: tabular-nums; }
        .fc-stat span { font-size: 10.5px; color: var(--text2); font-weight: 600; }
        .fc-rate { margin-top: 10px; padding: 11px 12px; border-radius: 16px; background: var(--surface); border: 1px solid var(--border); font-size: 12px; color: var(--text2); }
        .fc-rate div { height: 7px; margin-top: 7px; border-radius: 99px; background: rgba(229,72,77,.18); overflow: hidden; }
        .fc-rate i { display: block; height: 100%; width: var(--w); border-radius: inherit; background: linear-gradient(90deg, #16A34A, #4ADE80); transform-origin: right; animation: hpGrow 1s var(--ease-out) both .2s; }
        /* running */
        .fc-run { display: flex; flex-direction: column; align-items: center; padding-top: 10px; text-align: center; }
        .fc-ring { position: relative; width: 260px; height: 260px; margin: 8px auto 0; }
        .fc-ring::before { content: ""; position: absolute; inset: 18px; border-radius: 50%; background: radial-gradient(closest-side, rgb(var(--p) / .28), transparent); animation: fcBreathe 4s ease-in-out infinite; }
        @keyframes fcBreathe { 0%, 100% { transform: scale(.88); opacity: .6; } 50% { transform: scale(1.05); opacity: 1; } }
        .fc-ring svg { position: relative; width: 100%; height: 100%; transform: rotate(-90deg); }
        .fc-ring .bg { stroke: var(--input-bg); }
        .fc-ring .fg { stroke: url(#fcGrad); stroke-linecap: round; transition: stroke-dashoffset .9s linear; }
        .fc-time { position: absolute; inset: 0; display: flex; flex-direction: column; align-items: center; justify-content: center; }
        .fc-time b { font-size: 50px; font-weight: 900; color: var(--text); font-variant-numeric: tabular-nums; letter-spacing: 1px; }
        .fc-time span { font-size: 12px; color: var(--text2); font-weight: 600; }
        .fc-run h3 { margin: 18px 0 4px; font-size: 17px; font-weight: 900; color: var(--text); }
        .fc-run p { margin: 0 16px; font-size: 13px; color: var(--text2); line-height: 1.7; }
        .fc-warn { display: inline-flex; align-items: center; gap: 8px; margin-top: 14px; padding: 9px 14px; border-radius: 14px; font-size: 12.5px; font-weight: 700; color: #B45309; background: rgba(245,158,11,.12); }
        .fc-warn svg { width: 16px; height: 16px; }
        .fc-quit { margin-top: 22px; padding: 11px 22px; border-radius: 14px; border: 1px solid rgba(229,72,77,.3); font-size: 13px; font-weight: 800; color: #E5484D; background: rgba(229,72,77,.06); cursor: pointer; }
        /* result */
        .fc-res { display: flex; flex-direction: column; align-items: center; text-align: center; padding: 26px 8px 8px; animation: cardIn .5s var(--ease-out) both; }
        .fc-res-ic { width: 110px; height: 110px; border-radius: 50%; display: grid; place-items: center; color: #fff; animation: hpPop .6s var(--ease-spring) both; }
        .fc-res-ic svg { width: 52px; height: 52px; }
        .fc-res.ok .fc-res-ic { background: linear-gradient(135deg, #22C55E, #15803D); box-shadow: 0 0 0 12px rgba(34,197,94,.15), 0 20px 40px -16px #16A34A; }
        .fc-res.bad .fc-res-ic { background: linear-gradient(135deg, #F87171, #B91C1C); box-shadow: 0 0 0 12px rgba(239,68,68,.14), 0 20px 40px -16px #DC2626; }
        .fc-res h3 { margin: 24px 0 6px; font-size: 21px; font-weight: 900; color: var(--text); }
        .fc-res p { margin: 0; font-size: 13.5px; color: var(--text2); line-height: 1.8; }
        .fc-pts { margin-top: 14px; padding: 8px 18px; border-radius: 99px; font-size: 18px; font-weight: 900; color: #D97706; background: rgba(245,158,11,.14); }
        .fc-res-btns { display: flex; gap: 10px; width: 100%; margin-top: 26px; }
        .fc-res-btns button { flex: 1; height: 50px; border-radius: 16px; font-size: 14px; font-weight: 800; cursor: pointer; border: 1px solid var(--border); color: var(--text); background: var(--surface); }
        .fc-res-btns button.pri { border: 0; color: #fff; background: linear-gradient(135deg, rgb(var(--p)), #0B5E54); }

        /* ===== Before the exam (قبل الامتحان) ===== */
        .cm, .cm * { box-sizing: border-box; }
        .cm { padding: 14px 16px 28px; }
        .cm-sec { display: flex; align-items: center; justify-content: space-between; margin: 20px 4px 10px; font-size: 14px; font-weight: 800; color: var(--text); }
        .cm-sec small { font-size: 11px; font-weight: 700; color: var(--text2); }
        .cm-next { display: flex; align-items: center; gap: 12px; padding: 12px 14px; border-radius: 18px; background: var(--surface); border: 1px solid var(--border); box-shadow: var(--shadow-card); animation: cardIn .45s var(--ease-out) both; }
        .cm-next-ic { flex-shrink: 0; width: 42px; height: 42px; border-radius: 14px; display: grid; place-items: center; color: #7C3AED; background: rgba(124,58,237,.12); }
        .cm-next-ic svg { width: 20px; height: 20px; }
        .cm-next div { flex: 1; min-width: 0; }
        .cm-next b { display: block; font-size: 14px; font-weight: 800; color: var(--text); }
        .cm-next span { font-size: 11.5px; color: var(--text2); }
        .cm-next em { flex-shrink: 0; font-style: normal; font-size: 12px; font-weight: 900; padding: 6px 11px; border-radius: 99px; color: #7C3AED; background: rgba(124,58,237,.1); }
        .cm-dua { position: relative; overflow: hidden; margin-top: 12px; padding: 22px 18px 16px; border-radius: 26px; text-align: center; color: #fff;
            background: radial-gradient(120% 90% at 50% 0%, #1E3A5F 0%, #0F172A 55%, #111827 100%); box-shadow: 0 22px 44px -24px #1E3A5F; animation: cardIn .5s var(--ease-out) both; }
        .cm-dua::before { content: ""; position: absolute; inset: -40% -10% auto; height: 200px; background: radial-gradient(closest-side, rgba(250,204,21,.18), transparent); animation: hpFloat 7s ease-in-out infinite; pointer-events: none; }
        .cm-dua-lbl { position: relative; display: inline-flex; align-items: center; gap: 6px; font-size: 11px; font-weight: 800; letter-spacing: .3px; color: #FDE68A; background: rgba(250,204,21,.12); padding: 4px 11px; border-radius: 99px; }
        .cm-dua-lbl svg { width: 13px; height: 13px; }
        .cm-dua p { position: relative; margin: 16px 0 6px; min-height: 96px; display: flex; align-items: center; justify-content: center; font-size: 19px; line-height: 2; font-weight: 700; animation: cmFade .5s ease both; }
        .cm-dua small { position: relative; display: block; font-size: 11px; color: rgba(255,255,255,.55); }
        @keyframes cmFade { from { opacity: 0; transform: translateY(6px); } to { opacity: 1; transform: none; } }
        .cm-dua-nav { position: relative; display: flex; align-items: center; justify-content: center; gap: 14px; margin-top: 12px; }
        .cm-dua-nav button { width: 34px; height: 34px; border-radius: 12px; border: 0; display: grid; place-items: center; color: #fff; background: rgba(255,255,255,.1); cursor: pointer; }
        .cm-dua-nav button svg { width: 17px; height: 17px; }
        .cm-dots { display: flex; gap: 5px; }
        .cm-dots i { width: 6px; height: 6px; border-radius: 99px; background: rgba(255,255,255,.25); transition: all .3s ease; }
        .cm-dots i.on { width: 18px; background: #FDE68A; }
        /* breathing */
        .cm-br { padding: 18px 14px 16px; border-radius: 24px; background: var(--surface); border: 1px solid var(--border); box-shadow: var(--shadow-card); text-align: center; }
        .cm-orb-wrap { position: relative; width: 210px; height: 210px; margin: 4px auto 0; display: grid; place-items: center; }
        .cm-orb-wrap::before { content: ""; position: absolute; inset: 0; border-radius: 50%; border: 2px dashed rgb(var(--p) / .25); animation: tkBorderSpin 40s linear infinite; }
        .cm-orb { width: 200px; height: 200px; border-radius: 50%; display: grid; place-items: center; transform: scale(.5); transition-property: transform, box-shadow; transition-timing-function: ease-in-out;
            background: radial-gradient(circle at 35% 30%, #5EEAD4, rgb(var(--p)) 60%, #0B5E54); box-shadow: 0 0 0 10px rgb(var(--p) / .1), 0 18px 40px -16px rgb(var(--p)); }
        .cm-orb.in { transform: scale(1); box-shadow: 0 0 0 22px rgb(var(--p) / .12), 0 0 0 44px rgb(var(--p) / .06), 0 22px 50px -16px rgb(var(--p)); }
        .cm-orb.hold { transform: scale(1); }
        .cm-orb.idle { animation: cmIdle 4s ease-in-out infinite; }
        @keyframes cmIdle { 0%, 100% { transform: scale(.5); } 50% { transform: scale(.58); } }
        .cm-orb-txt { position: absolute; inset: 0; display: flex; flex-direction: column; align-items: center; justify-content: center; color: #fff; text-align: center; pointer-events: none; text-shadow: 0 1px 6px rgba(0,0,0,.18); }
        .cm-orb-txt b { display: block; font-size: 20px; font-weight: 900; }
        .cm-orb-txt small { font-size: 26px; font-weight: 900; font-variant-numeric: tabular-nums; opacity: .9; }
        .cm-br h4 { margin: 12px 0 4px; font-size: 15px; font-weight: 900; color: var(--text); }
        .cm-br p { margin: 0; font-size: 12.5px; color: var(--text2); line-height: 1.7; }
        .cm-bar { height: 6px; margin: 12px 8px 0; border-radius: 99px; background: var(--input-bg); overflow: hidden; }
        .cm-bar i { display: block; height: 100%; width: 0; border-radius: inherit; background: linear-gradient(90deg, #5EEAD4, rgb(var(--p))); transition: width .2s linear; }
        .cm-btn { margin-top: 14px; width: 100%; height: 50px; border: 0; border-radius: 16px; display: flex; align-items: center; justify-content: center; gap: 8px; font-size: 14.5px; font-weight: 900; color: #fff; cursor: pointer;
            background: linear-gradient(135deg, rgb(var(--p)), #0B5E54); box-shadow: 0 14px 28px -14px rgb(var(--p)); }
        .cm-btn svg { width: 18px; height: 18px; }
        .cm-btn.ghost { color: var(--text); background: var(--input-bg); box-shadow: none; }
        /* checklist */
        .cm-list { display: flex; flex-direction: column; gap: 8px; }
        .cm-chk { width: 100%; display: flex; align-items: center; gap: 12px; padding: 12px; border-radius: 16px; border: 1px solid var(--border); background: var(--surface); color: var(--text); font-size: 13px; font-weight: 700; text-align: right; cursor: pointer; transition: all .2s ease; animation: cardIn .4s var(--ease-out) both; }
        .cm-chk-box { flex-shrink: 0; width: 26px; height: 26px; border-radius: 9px; border: 2px solid var(--border); display: grid; place-items: center; color: #fff; transition: all .2s ease; }
        .cm-chk-box svg { width: 15px; height: 15px; opacity: 0; transform: scale(.5); transition: all .2s var(--ease-spring); }
        .cm-chk.on { border-color: rgba(22,163,74,.35); background: rgba(22,163,74,.06); }
        .cm-chk.on .cm-chk-box { border-color: #16A34A; background: #16A34A; }
        .cm-chk.on .cm-chk-box svg { opacity: 1; transform: none; }
        .cm-chk.on span:last-child { color: var(--text2); text-decoration: line-through; }
        .cm-tips { display: grid; grid-template-columns: 1fr 1fr; gap: 8px; }
        .cm-tip { padding: 12px; border-radius: 16px; background: var(--surface); border: 1px solid var(--border); font-size: 12px; color: var(--text); line-height: 1.6; animation: hpPop .45s var(--ease-spring) both; }
        .cm-tip b { display: flex; align-items: center; gap: 6px; margin-bottom: 4px; font-size: 12.5px; font-weight: 900; color: var(--c); }
        .cm-tip b i { width: 20px; height: 20px; border-radius: 7px; display: grid; place-items: center; font-style: normal; font-size: 11px; color: #fff; background: var(--c); }
        .cm-quote { margin-top: 18px; padding: 16px; border-radius: 20px; text-align: center; font-size: 14px; font-weight: 800; line-height: 1.8; color: var(--text); background: linear-gradient(135deg, rgba(245,158,11,.1), rgba(124,58,237,.08)); border: 1px solid var(--border); }

        /* ===== Grades progress (تطور درجاتي) ===== */
        .gr, .gr * { box-sizing: border-box; }
        .gr { padding: 14px 16px 28px; }
        .gr-sec { display: flex; align-items: center; justify-content: space-between; margin: 20px 4px 10px; font-size: 14px; font-weight: 800; color: var(--text); }
        .gr-sec small { font-size: 11px; font-weight: 700; color: var(--text2); }
        .gr-tiles { display: grid; grid-template-columns: repeat(3, 1fr); gap: 8px; }
        .gr-tile { min-width: 0; padding: 12px 10px; border-radius: 18px; background: var(--surface); border: 1px solid var(--border); box-shadow: var(--shadow-card); animation: hpPop .45s var(--ease-spring) both; }
        .gr-tile span { display: flex; align-items: center; gap: 5px; font-size: 10.5px; font-weight: 700; color: var(--text2); }
        .gr-tile span svg { width: 13px; height: 13px; color: var(--c); flex-shrink: 0; }
        .gr-tile b { display: block; margin-top: 4px; font-size: 22px; font-weight: 900; color: var(--text); font-variant-numeric: tabular-nums; }
        .gr-tile small { display: block; font-size: 11px; font-weight: 700; color: var(--text2); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
        .gr-chips { display: flex; gap: 6px; overflow-x: auto; padding: 2px 2px 6px; scrollbar-width: none; }
        .gr-chips::-webkit-scrollbar { display: none; }
        .gr-chip { flex-shrink: 0; height: 36px; padding: 0 14px; border-radius: 99px; border: 1px solid var(--border); background: var(--surface); color: var(--text); font-size: 12.5px; font-weight: 700; cursor: pointer; display: inline-flex; align-items: center; gap: 6px; }
        .gr-chip.on { color: #fff; background: rgb(var(--p)); border-color: transparent; }
        .gr-chip svg { width: 14px; height: 14px; }
        .gr-add { display: flex; gap: 8px; margin-top: 6px; }
        .gr-add input { flex: 1; min-width: 0; height: 42px; padding: 0 12px; border-radius: 14px; border: 1px solid var(--border); background: var(--input-bg); color: var(--text); font: inherit; font-size: 13px; }
        .gr-add button { height: 42px; padding: 0 16px; border: 0; border-radius: 14px; font: inherit; font-size: 13px; font-weight: 800; color: #fff; background: rgb(var(--p)); cursor: pointer; }
        .gr-card { position: relative; margin-top: 8px; padding: 14px 12px 10px; border-radius: 22px; background: var(--surface); border: 1px solid var(--border); box-shadow: var(--shadow-card); animation: cardIn .45s var(--ease-out) both; }
        .gr-card h4 { margin: 0 4px 2px; font-size: 14px; font-weight: 900; color: var(--text); }
        .gr-trend { margin: 0 4px 6px; font-size: 12px; font-weight: 700; color: var(--text2); display: flex; align-items: center; gap: 5px; }
        .gr-trend svg { width: 14px; height: 14px; }
        .gr-trend.up { color: #15803D; } .gr-trend.down { color: #DC2626; }
        .gr-chart { position: relative; }
        .gr-chart svg { display: block; width: 100%; height: auto; overflow: visible; }
        .gr-chart .grid { stroke: var(--border); stroke-width: 1; }
        .gr-chart .pass { stroke: #DC2626; stroke-width: 1; stroke-dasharray: 4 4; opacity: .55; }
        .gr-chart .ax { fill: var(--text2); font-size: 10px; font-family: inherit; }
        .gr-chart .ln { fill: none; stroke: rgb(var(--p)); stroke-width: 2; stroke-linecap: round; stroke-linejoin: round; stroke-dasharray: 1000; stroke-dashoffset: 1000; animation: grDraw 1.1s var(--ease-out) forwards .15s; }
        .gr-chart .area { fill: url(#grArea); opacity: 0; animation: hpFade .6s ease forwards .5s; }
        @keyframes grDraw { to { stroke-dashoffset: 0; } }
        @keyframes hpFade { to { opacity: 1; } }
        .gr-chart .pt { fill: rgb(var(--p)); stroke: var(--surface); stroke-width: 2; }
        .gr-chart .pt.low { fill: #DC2626; }
        .gr-chart .hit { fill: transparent; cursor: pointer; }
        .gr-chart .lbl { fill: var(--text); font-size: 11px; font-weight: 800; font-family: inherit; }
        .gr-tip { position: absolute; top: 0; transform: translate(50%, -100%); pointer-events: none; padding: 6px 10px; border-radius: 10px; background: var(--text); color: var(--surface); font-size: 11.5px; font-weight: 700; white-space: nowrap; box-shadow: 0 8px 18px -8px rgba(0,0,0,.4); }
        .gr-tip b { font-size: 13px; }
        .gr-empty { padding: 26px 10px; text-align: center; font-size: 12.5px; color: var(--text2); line-height: 1.8; }
        .gr-inputs { display: grid; grid-template-columns: repeat(4, 1fr); gap: 8px; }
        .gr-in { display: flex; flex-direction: column; gap: 4px; padding: 8px 6px; border-radius: 14px; background: var(--surface); border: 1px solid var(--border); }
        .gr-in label { font-size: 10.5px; font-weight: 700; color: var(--text2); text-align: center; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
        .gr-in input { width: 100%; height: 36px; border-radius: 10px; border: 1px solid var(--border); background: var(--input-bg); color: var(--text); text-align: center; font: inherit; font-size: 16px; font-weight: 800; font-variant-numeric: tabular-nums; }
        .gr-in input:focus { outline: none; border-color: rgb(var(--p)); box-shadow: 0 0 0 3px rgb(var(--p) / .15); }
        .gr-in.low input { color: #DC2626; }
        .gr-bars { display: flex; flex-direction: column; gap: 8px; padding: 12px; border-radius: 20px; background: var(--surface); border: 1px solid var(--border); }
        .gr-bar { display: grid; grid-template-columns: 74px 1fr 34px; align-items: center; gap: 8px; background: none; border: 0; padding: 2px 0; font: inherit; color: var(--text); cursor: pointer; text-align: right; }
        .gr-bar > span:first-child { font-size: 12px; font-weight: 700; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
        .gr-bar-track { height: 10px; border-radius: 4px; background: var(--input-bg); overflow: hidden; }
        .gr-bar-track i { display: block; height: 100%; width: var(--w); border-radius: 4px; background: rgb(var(--p)); transform-origin: right; animation: hpGrow .9s var(--ease-out) both; }
        .gr-bar.low .gr-bar-track i { background: #DC2626; }
        .gr-bar b { font-size: 13px; font-weight: 900; font-variant-numeric: tabular-nums; text-align: left; }
        .gr-bar.on > span:first-child { color: rgb(var(--p)); }
        .gr-flag { display: flex; align-items: center; gap: 6px; margin-top: 4px; padding: 8px 10px; border-radius: 12px; font-size: 11.5px; font-weight: 700; color: #B91C1C; background: rgba(220,38,38,.08); }
        .gr-flag svg { width: 14px; height: 14px; flex-shrink: 0; }
        .gr-acts { display: flex; gap: 8px; margin-top: 16px; }
        .gr-acts button { flex: 1; height: 48px; border-radius: 16px; font: inherit; font-size: 13.5px; font-weight: 800; display: flex; align-items: center; justify-content: center; gap: 7px; cursor: pointer; border: 1px solid var(--border); color: var(--text); background: var(--surface); }
        .gr-acts button.pri { border: 0; color: #fff; background: linear-gradient(135deg, rgb(var(--p)), #0B5E54); }
        .gr-acts button.del { flex: 0 0 48px; color: #DC2626; }
        .gr-acts svg { width: 17px; height: 17px; }

        /* ===== Mood of the day (مزاجي اليوم) ===== */
        .mo, .mo * { box-sizing: border-box; }
        .mo { position: relative; overflow: hidden; padding: 14px; border-radius: 22px; background: var(--surface); border: 1px solid var(--border); box-shadow: var(--shadow-card); }
        .mo::before { content: ""; position: absolute; inset: -60% -30% auto auto; width: 200px; height: 200px; border-radius: 50%; background: radial-gradient(closest-side, color-mix(in srgb, var(--mc, rgb(var(--p))) 16%, transparent), transparent); animation: hpFloat 8s ease-in-out infinite; pointer-events: none; }
        .mo-q { position: relative; display: flex; align-items: center; justify-content: space-between; font-size: 14px; font-weight: 900; color: var(--text); }
        .mo-q small { font-size: 11px; font-weight: 700; color: var(--text2); }
        .mo-opts { position: relative; display: grid; grid-template-columns: repeat(4, 1fr); gap: 8px; margin-top: 12px; }
        .mo-opt { display: flex; flex-direction: column; align-items: center; gap: 6px; padding: 10px 2px; border-radius: 16px; border: 1px solid var(--border); background: var(--surface); color: var(--text); font: inherit; font-size: 12px; font-weight: 800; cursor: pointer; transition: transform .2s var(--ease-spring); animation: hpPop .45s var(--ease-spring) both; }
        .mo-opt:active { transform: scale(.92); }
