        /* ===== Story share card (بطاقة ستوري) ===== */
        .sc-modal { position: fixed; inset: 0; z-index: 90; display: flex; align-items: flex-end; justify-content: center; background: rgba(2,6,23,.62); backdrop-filter: blur(4px); animation: hpFade .2s ease forwards; opacity: 0; }
        .sc-sheet { box-sizing: border-box; width: 100%; max-width: 480px; max-height: 96vh; overflow-y: auto; padding: 14px 16px 20px; border-radius: 26px 26px 0 0; background: var(--surface); animation: cardIn .35s var(--ease-out) both; }
        .sc-head { display: flex; align-items: center; justify-content: space-between; margin-bottom: 12px; font-size: 15px; font-weight: 900; color: var(--text); }
        .sc-head button { width: 36px; height: 36px; border-radius: 12px; border: 0; display: grid; place-items: center; background: var(--input-bg); color: var(--text); cursor: pointer; }
        .sc-prev { display: grid; place-items: center; min-height: 200px; border-radius: 18px; background: var(--input-bg); }
