        .sc-btns svg { width: 18px; height: 18px; }
        .sc-note { margin-top: 10px; text-align: center; font-size: 11.5px; color: var(--text2); }

        /* ===== Shared bits for the live pages ===== */
        .lv, .lv * { box-sizing: border-box; }
        .lv { padding: 14px 16px 28px; }
        .lv-sec { display: flex; align-items: center; justify-content: space-between; margin: 20px 4px 10px; font-size: 14px; font-weight: 800; color: var(--text); }
