        .lv-empty b { display: block; font-size: 15px; color: var(--text); }
        @keyframes lvPing { 0% { transform: scale(1); opacity: .7; } 100% { transform: scale(2.4); opacity: 0; } }

        /* ===== Governorate war (حرب المحافظات) ===== */
        .gw-hero { position: relative; overflow: hidden; padding: 16px; border-radius: 24px; color: #fff; background: linear-gradient(135deg, #7F1D1D, #991B1B 35%, #0F172A); box-shadow: 0 20px 40px -22px #991B1B; animation: cardIn .5s var(--ease-out) both; }
        .gw-hero::after { content: ""; position: absolute; inset: 0; background: linear-gradient(110deg, transparent 30%, rgba(255,255,255,.1) 45%, transparent 60%); background-size: 250% 100%; animation: hpShine 6s ease-in-out infinite; pointer-events: none; }
        .gw-hero-top { position: relative; display: flex; align-items: center; justify-content: space-between; gap: 8px; flex-wrap: wrap; font-size: 11px; font-weight: 700; }
        .gw-live { display: inline-flex; align-items: center; gap: 6px; padding: 4px 10px; border-radius: 99px; background: rgba(255,255,255,.14); }
