        .gw-crown { flex-shrink: 0; width: 54px; height: 54px; border-radius: 18px; display: grid; place-items: center; color: #FDE68A; background: rgba(250,204,21,.16); animation: hpBob 3s ease-in-out infinite; }
        .gw-crown svg { width: 28px; height: 28px; }
        .gw-lead small { display: block; font-size: 11px; opacity: .75; }
        .gw-lead b { display: block; font-size: 22px; font-weight: 900; }
        .gw-lead em { font-style: normal; font-size: 12px; opacity: .85; }
        .gw-last { display: flex; align-items: center; gap: 10px; margin-top: 10px; padding: 11px 12px; border-radius: 16px; background: var(--surface); border: 1px solid var(--border); font-size: 12px; color: var(--text2); }
        .gw-last > svg { width: 20px; height: 20px; color: #D97706; flex-shrink: 0; }
        .gw-last div { flex: 1; min-width: 0; }
        .gw-last b { display: block; font-size: 13px; color: var(--text); }
        .gw-last button { flex-shrink: 0; height: 36px; padding: 0 12px; border: 0; border-radius: 12px; font: inherit; font-size: 12px; font-weight: 800; color: #fff; background: #D97706; cursor: pointer; }
        .gw-last.win { border-color: rgba(217,119,6,.4); background: rgba(245,158,11,.08); }
        .gw-map { display: grid; grid-template-columns: repeat(5, 1fr); grid-template-rows: repeat(7, 52px); gap: 5px; direction: ltr; }
        .gw-tile { position: relative; min-width: 0; display: flex; flex-direction: column; align-items: center; justify-content: center; gap: 1px; padding: 2px; border-radius: 12px; text-align: center; background: var(--input-bg); border: 1px solid var(--border); color: var(--text); animation: hpPop .45s var(--ease-spring) both; direction: rtl; }
        .gw-tile b { font-size: 10px; font-weight: 800; line-height: 1.2; white-space: nowrap; }
        .gw-tile span { font-size: 9px; font-weight: 700; opacity: .75; white-space: nowrap; }
        .gw-tile.lv1 { background: rgb(var(--p) / .14); border-color: rgb(var(--p) / .2); }
        .gw-tile.lv2 { background: rgb(var(--p) / .32); border-color: transparent; }
        .gw-tile.lv3 { background: rgb(var(--p) / .6); border-color: transparent; color: #fff; }
        .gw-tile.lv4 { background: rgb(var(--p)); border-color: transparent; color: #fff; box-shadow: 0 8px 18px -8px rgb(var(--p)); }
        .gw-tile.me { outline: 2px solid #F59E0B; outline-offset: 1px; }
        .gw-tile em { position: absolute; top: -6px; left: -4px; min-width: 18px; height: 18px; padding: 0 4px; border-radius: 99px; font-style: normal; font-size: 10px; font-weight: 900; line-height: 18px; color: #fff; background: #16A34A; box-shadow: 0 0 0 2px var(--surface); }
        .gw-tile.on::after { content: ""; position: absolute; inset: -1px; border-radius: inherit; border: 2px solid #16A34A; animation: gwGlow 1.8s ease-in-out infinite; pointer-events: none; }
        @keyframes gwGlow { 0%, 100% { opacity: .25; } 50% { opacity: 1; } }
        .gw-t-crown { position: absolute; top: -9px; right: -3px; width: 16px; height: 16px; color: #F59E0B; }
        .gw-legend { display: flex; flex-wrap: wrap; align-items: center; gap: 4px 10px; margin-top: 10px; font-size: 10.5px; color: var(--text2); }
        .gw-legend span { display: inline-flex; align-items: center; gap: 4px; }
        .gw-legend i { width: 14px; height: 10px; border-radius: 3px; background: var(--input-bg); border: 1px solid var(--border); }
        .gw-legend i.lv1 { background: rgb(var(--p) / .14); } .gw-legend i.lv2 { background: rgb(var(--p) / .32); } .gw-legend i.lv3 { background: rgb(var(--p) / .6); } .gw-legend i.lv4 { background: rgb(var(--p)); }
        .gw-legend em { width: 10px; height: 10px; border-radius: 50%; background: #16A34A; }
        .gw-me { margin-top: 16px; padding: 14px; border-radius: 20px; background: var(--surface); border: 1px solid var(--border); box-shadow: var(--shadow-card); }
        .gw-me p { margin: 0; font-size: 13px; color: var(--text2); text-align: center; }
        .gw-me-row { display: flex; align-items: center; gap: 12px; }
        .gw-me-rank { flex-shrink: 0; width: 46px; height: 46px; border-radius: 15px; display: grid; place-items: center; font-size: 20px; font-weight: 900; color: #fff; background: linear-gradient(135deg, #F59E0B, #D97706); }
        .gw-me-row b { display: block; font-size: 14px; font-weight: 900; color: var(--text); }
        .gw-me-row small { font-size: 11.5px; color: var(--text2); }
        .gw-rank { display: flex; flex-direction: column; gap: 6px; }
        .gw-row { display: flex; align-items: center; gap: 10px; padding: 9px 11px; border-radius: 14px; background: var(--surface); border: 1px solid var(--border); animation: cardIn .4s var(--ease-out) both; }
        .gw-row.me { border-color: rgba(245,158,11,.5); background: rgba(245,158,11,.06); }
        .gw-n { flex-shrink: 0; width: 26px; height: 26px; border-radius: 9px; display: grid; place-items: center; font-size: 12px; font-weight: 900; color: var(--text2); background: var(--input-bg); }
        .gw-n.top1 { color: #fff; background: #D97706; } .gw-n.top2 { color: #fff; background: #64748B; } .gw-n.top3 { color: #fff; background: #B45309; }
        .gw-row-main { flex: 1; min-width: 0; }
        .gw-row-top { display: flex; align-items: center; gap: 6px; font-size: 12.5px; color: var(--text); }
        .gw-row-top b { font-weight: 800; }
        .gw-row-top em { margin-right: auto; font-style: normal; font-size: 11.5px; font-weight: 800; color: var(--text2); font-variant-numeric: tabular-nums; }
        .gw-row-live { display: inline-flex; align-items: center; gap: 4px; font-size: 10px; font-weight: 800; color: #16A34A; }
        .gw-row-live i { width: 6px; height: 6px; border-radius: 50%; background: #16A34A; animation: gwGlow 1.4s ease-in-out infinite; }
        .gw-bar { height: 6px; margin-top: 6px; border-radius: 4px; background: var(--input-bg); overflow: hidden; }
        .gw-bar i { display: block; height: 100%; width: var(--w); border-radius: 4px; background: rgb(var(--p)); transform-origin: right; animation: hpGrow .9s var(--ease-out) both; }
        .gw-more { display: block; width: 100%; height: 42px; margin-top: 8px; border-radius: 14px; border: 1px dashed var(--border); background: none; font: inherit; font-size: 12.5px; font-weight: 800; color: var(--text2); cursor: pointer; }
        /* ===== 3D satellite battlefield ===== */
        .gw3d { position: relative; height: 420px; margin: 0 -16px; overflow: hidden; touch-action: pan-y; user-select: none; -webkit-user-select: none;
            background: radial-gradient(120% 85% at 50% 35%, #10283a 0%, #071521 55%, #02070c 100%); }
        .gw3d canvas { position: absolute; inset: 0; width: 100%; height: 100%; display: block; cursor: grab; }
        .gw3d::after { content: ""; position: absolute; inset: 0; pointer-events: none; z-index: 2;
            background: repeating-linear-gradient(0deg, rgba(255,255,255,.028) 0 1px, transparent 1px 3px), radial-gradient(130% 100% at 50% 50%, transparent 60%, rgba(0,0,0,.55) 100%); }
        .gw3d-labels { position: absolute; inset: 0; pointer-events: none; z-index: 3; }
        .gw3d-lb { position: absolute; left: 0; top: 0; pointer-events: auto; display: inline-flex; align-items: center; gap: 4px; padding: 2px 7px; border-radius: 8px; border: 1px solid rgba(255,255,255,.2);
            background: rgba(3,12,20,.62); color: #fff; font: inherit; font-size: 10px; font-weight: 800; white-space: nowrap; text-shadow: 0 1px 3px #000; cursor: pointer; -webkit-backdrop-filter: blur(2px); backdrop-filter: blur(2px); transition: opacity .2s; }
        .gw3d-lb small { font-size: 9px; font-weight: 800; color: #99F6E4; }
