        .gw3d-lb.me { border-color: #FB923C; }
        .gw3d-lb.me small { color: #FDBA74; }
        .gw3d-c { position: absolute; width: 18px; height: 18px; border: 2px solid rgba(94,234,212,.55); z-index: 4; pointer-events: none; }
        .gw3d-c.tl { top: 10px; right: 10px; border-width: 2px 2px 0 0; } .gw3d-c.tr { top: 10px; left: 10px; border-width: 2px 0 0 2px; }
        .gw3d-c.bl { bottom: 10px; right: 10px; border-width: 0 2px 2px 0; } .gw3d-c.br { bottom: 10px; left: 10px; border-width: 0 0 2px 2px; }
        .gw3d-hud { position: absolute; top: 14px; left: 34px; right: 34px; z-index: 4; display: flex; align-items: center; justify-content: space-between; gap: 8px; pointer-events: none; font-size: 10.5px; font-weight: 800; color: rgba(204,251,241,.85); letter-spacing: .2px; }
        .gw3d-rec { display: inline-flex; align-items: center; gap: 6px; padding: 3px 9px; border-radius: 99px; background: rgba(220,38,38,.2); border: 1px solid rgba(248,113,113,.45); color: #FECACA; }
        .gw3d-rec i { width: 7px; height: 7px; border-radius: 50%; background: #EF4444; box-shadow: 0 0 8px #EF4444; animation: hpBlink 1s steps(2, start) infinite; }
        .gw3d-foot { position: absolute; bottom: 14px; left: 34px; right: 34px; z-index: 4; display: flex; justify-content: space-between; gap: 8px; pointer-events: none; font-size: 9.5px; font-weight: 700; color: rgba(204,251,241,.6); }
        .gw3d-coord { direction: ltr; font-family: ui-monospace, SFMono-Regular, Menlo, Consolas, monospace; }
        .gw3d-load { position: absolute; inset: 0; z-index: 5; display: flex; flex-direction: column; align-items: center; justify-content: center; gap: 14px; color: #99F6E4; font-size: 12px; background: rgba(2,7,12,.55); transition: opacity .8s ease; pointer-events: none; }
        .gw3d.ready .gw3d-load { opacity: 0; }
        .gw3d-radar { position: relative; width: 90px; height: 90px; border-radius: 50%; border: 1.5px solid rgba(94,234,212,.5); background: repeating-radial-gradient(circle, transparent 0 14px, rgba(94,234,212,.18) 14px 15px); overflow: hidden; }
        .gw3d-radar::after { content: ""; position: absolute; inset: 0; border-radius: 50%; background: conic-gradient(from 0deg, rgba(94,234,212,.55), transparent 25%); animation: tkBorderSpin 1.6s linear infinite; }
        .gw3d-legend { display: flex; flex-wrap: wrap; gap: 6px 12px; margin-top: 10px; font-size: 10.5px; font-weight: 700; color: var(--text2); }
        .gw3d-legend span { display: inline-flex; align-items: center; gap: 5px; }
        .gw3d-legend i { width: 9px; height: 9px; border-radius: 50%; box-shadow: 0 0 6px currentColor; }
