        /* ===== Points auction (مزاد النقاط) ===== */
        .au-hero { position: relative; overflow: hidden; padding: 16px; border-radius: 24px; color: #fff; background: linear-gradient(135deg, #1C1917, #44403C 45%, #78350F); box-shadow: 0 22px 44px -22px #78350F; animation: cardIn .5s var(--ease-out) both; }
        .au-hero::before { content: ""; position: absolute; inset: auto -40px -60px auto; width: 200px; height: 200px; border-radius: 50%; background: radial-gradient(closest-side, rgba(250,204,21,.3), transparent); animation: hpFloat 7s ease-in-out infinite; }
        .au-hero > * { position: relative; }
        .au-hero-top { display: flex; align-items: center; justify-content: space-between; gap: 8px; flex-wrap: wrap; font-size: 11px; font-weight: 700; }
        .au-tag { display: inline-flex; align-items: center; gap: 6px; padding: 4px 10px; border-radius: 99px; color: #FDE68A; background: rgba(250,204,21,.14); }
