        .au-top small { font-size: 11px; opacity: .75; }
        .au-top b { display: block; font-size: 38px; font-weight: 900; color: #FDE68A; font-variant-numeric: tabular-nums; animation: hpPop .5s var(--ease-spring) both; }
        .au-top b em { font-style: normal; font-size: 14px; margin-right: 6px; opacity: .8; }
        .au-top span { font-size: 12.5px; font-weight: 700; }
