        .au-mine { display: flex; align-items: baseline; gap: 8px; font-size: 12px; color: var(--text2); }
        .au-mine b { font-size: 18px; font-weight: 900; color: var(--text); font-variant-numeric: tabular-nums; }
        .au-mine em { font-style: normal; font-size: 11px; font-weight: 700; color: #D97706; }
