        .au-step > button svg { width: 20px; height: 20px; }
        .au-step div { flex: 1; text-align: center; }
        .au-step b { display: block; font-size: 30px; font-weight: 900; color: #B45309; font-variant-numeric: tabular-nums; }
        .au-step small { font-size: 11px; color: var(--text2); }
        .au-quick { display: flex; gap: 6px; margin-top: 10px; }
