        .au-win p { margin: 4px 0 0; font-size: 12.5px; color: var(--text2); line-height: 1.7; }
        .au-log { display: flex; flex-direction: column; gap: 6px; }
        .au-log div { display: flex; align-items: center; gap: 10px; padding: 9px 12px; border-radius: 14px; background: var(--surface); border: 1px solid var(--border); font-size: 12.5px; color: var(--text); animation: cardIn .35s var(--ease-out) both; }
        .au-log div:first-child { border-color: rgba(245,158,11,.45); }
        .au-log svg { width: 15px; height: 15px; color: #D97706; flex-shrink: 0; }
        .au-log b { flex: 1; font-weight: 700; }
        .au-log em { font-style: normal; font-weight: 900; color: #B45309; font-variant-numeric: tabular-nums; }
        .au-log span { font-size: 10.5px; color: var(--text2); }

        /* ===== Tomorrow: school or holiday? (باچر دوام لو عطلة؟) ===== */
        #dayStatusWrap { padding: 12px 16px 0; }
        .dsb, .dsb * { box-sizing: border-box; }
        .dsb { display: flex; align-items: center; gap: 8px; width: 100%; height: 40px; padding: 0 6px 0 12px; border-radius: 14px; border: 1px solid var(--bd); background: var(--bg2); color: var(--text); font: inherit; font-size: 12.5px; text-align: right; cursor: pointer; overflow: hidden; }
        .dsb.on { --c: #16A34A; --bd: rgba(22,163,74,.3); --bg2: rgba(22,163,74,.08); }
        .dsb.off { --c: #DC2626; --bd: rgba(220,38,38,.3); --bg2: rgba(220,38,38,.08); }
        .dsb.pending { --c: #D97706; --bd: rgba(217,119,6,.35); --bg2: rgba(245,158,11,.1); }
        .dsb.ask { --c: rgb(var(--p)); --bd: var(--border); --bg2: var(--surface); }
        .dsb-dot { position: relative; flex-shrink: 0; width: 8px; height: 8px; border-radius: 50%; background: var(--c); }
        .dsb-dot::after { content: ""; position: absolute; inset: 0; border-radius: 50%; background: var(--c); animation: dsbPing 1.8s ease-out infinite; }
        @keyframes dsbPing { 0% { transform: scale(1); opacity: .6; } 100% { transform: scale(2.6); opacity: 0; } }
        .dsb-when { flex-shrink: 0; font-weight: 700; color: var(--text2); white-space: nowrap; }
        .dsb-st { flex-shrink: 0; font-weight: 900; color: var(--c); white-space: nowrap; }
        .dsb-why { flex: 1; min-width: 0; font-size: 11.5px; color: var(--text2); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
        .dsb-gov { flex-shrink: 0; display: inline-flex; align-items: center; gap: 3px; height: 28px; padding: 0 9px; border-radius: 10px; border: 0; background: var(--surface); color: var(--text); font: inherit; font-size: 11.5px; font-weight: 800; cursor: pointer; box-shadow: 0 0 0 1px var(--border); }
        .dsb-gov svg { width: 12px; height: 12px; }
        .dsb-more { margin-top: 6px; padding: 10px; border-radius: 14px; background: var(--surface); border: 1px solid var(--border); font-size: 12px; color: var(--text2); }
        .dsb-more p { margin: 0 2px 8px; line-height: 1.6; color: var(--text); }
        .dsb-days { display: grid; grid-template-columns: repeat(5, 1fr); gap: 4px; }
        .dsb-day { display: flex; flex-direction: column; align-items: center; gap: 3px; padding: 5px 2px; border-radius: 10px; background: var(--input-bg); font-size: 10px; font-weight: 700; }
        .dsb-day.sel { box-shadow: inset 0 0 0 1.5px var(--text2); }
        .dsb-day i { width: 8px; height: 8px; border-radius: 50%; }
        .dsb-day i.on { background: #16A34A; } .dsb-day i.off { background: #DC2626; } .dsb-day i.pending { background: #D97706; }
        .ds-pick { margin-top: 6px; padding: 12px; border-radius: 18px; background: var(--surface); border: 1px solid var(--border); box-shadow: var(--shadow-card); animation: hpPop .3s var(--ease-spring) both; }
        .ds-pick p { margin: 0 2px 8px; font-size: 12px; font-weight: 700; color: var(--text2); }
        .ds-pick div { display: flex; flex-wrap: wrap; gap: 6px; }
        .ds-pick button { height: 32px; padding: 0 11px; border-radius: 99px; border: 1px solid var(--border); background: var(--surface); color: var(--text); font: inherit; font-size: 12px; font-weight: 700; cursor: pointer; }
        .ds-pick button.on { color: #fff; background: rgb(var(--p)); border-color: transparent; }
        .ds-push { display: flex; align-items: center; gap: 8px; width: 100%; margin-top: 8px; padding: 8px 10px; border-radius: 12px; border: 1px solid var(--border); background: var(--input-bg); color: var(--text); font: inherit; font-size: 12.5px; font-weight: 800; text-align: right; cursor: pointer; }
        .ds-push.on { cursor: default; font-weight: 700; }
        .ds-push svg { width: 17px; height: 17px; flex-shrink: 0; }
        .inb, .inb * { box-sizing: border-box; }
        .inb { position: fixed; left: 12px; right: 12px; bottom: calc(var(--safe-b) + 96px); z-index: 60; display: flex; align-items: center; gap: 10px; padding: 8px 8px 8px 10px; border-radius: 16px; background: var(--surface); border: 1px solid var(--border); box-shadow: 0 16px 36px -14px rgba(0,0,0,.35); font-size: 11.5px; color: var(--text2); animation: cardIn .35s var(--ease-out) both; }
        .inb img { width: 38px; height: 38px; border-radius: 11px; flex-shrink: 0; }
        .inb span { flex: 1; min-width: 0; line-height: 1.5; }
        .inb b { display: block; font-size: 13px; font-weight: 900; color: var(--text); }
        .inb-go { flex-shrink: 0; height: 34px; padding: 0 14px; border: 0; border-radius: 11px; font: inherit; font-size: 12.5px; font-weight: 800; color: #fff; background: rgb(var(--p)); cursor: pointer; }
        .inb-x { flex-shrink: 0; width: 30px; height: 30px; border: 0; border-radius: 10px; display: grid; place-items: center; background: var(--input-bg); color: var(--text2); cursor: pointer; }
        /* ===== Polls (استطلاع رأي) ===== */
        .pl, .pl * { box-sizing: border-box; }
        .pl { margin-bottom: 10px; padding: 12px; border-radius: 18px; background: var(--surface); border: 1px solid var(--border); box-shadow: var(--shadow-card); }
        .pl-head { display: flex; align-items: center; justify-content: space-between; gap: 8px; }
        .pl-head small { font-size: 11px; font-weight: 700; color: var(--text2); }
        .pl-tag { display: inline-flex; align-items: center; gap: 5px; padding: 3px 9px; border-radius: 99px; font-size: 11px; font-weight: 800; color: #7C3AED; background: rgba(124,58,237,.1); }
        .pl-tag.off { color: var(--text2); background: var(--input-bg); }
        .pl-tag svg { width: 13px; height: 13px; }
        .pl-q { display: block; margin: 8px 2px 10px; font-size: 14.5px; font-weight: 900; line-height: 1.6; color: var(--text); }
        .pl-body { display: flex; flex-direction: column; gap: 6px; }
        .pl-opt { width: 100%; min-height: 40px; padding: 8px 12px; border-radius: 12px; border: 1px solid rgba(124,58,237,.3); background: rgba(124,58,237,.05); color: var(--text); font: inherit; font-size: 13px; font-weight: 700; text-align: right; cursor: pointer; }
        .pl-res { position: relative; display: flex; align-items: center; gap: 8px; min-height: 38px; padding: 0 12px; border-radius: 12px; background: var(--input-bg); overflow: hidden; font-size: 13px; font-weight: 700; color: var(--text); }
        .pl-res i { position: absolute; inset: 0 0 0 auto; width: var(--w); background: rgba(124,58,237,.16); transform-origin: right; animation: hpGrow .8s var(--ease-out) both; }
        .pl-res.top i { background: rgba(124,58,237,.28); }
