.vn.playing .vn-play::before { content: ''; position: absolute; inset: -5px; border-radius: 50%; border: 2px solid rgb(var(--p)); opacity: .5; animation: vnRing 1.4s ease-out infinite; }
@keyframes vnRing { from { transform: scale(.9); opacity: .6; } to { transform: scale(1.25); opacity: 0; } }
.vn-spin { width: 20px; height: 20px; border-radius: 50%; border: 2.5px solid rgba(255,255,255,.35); border-top-color: #fff; animation: yrSpin .8s linear infinite; }
.vn-body { flex: 1; min-width: 0; }
.vn-top { display: flex; align-items: center; gap: 8px; }
.vn-top b { flex: 1; min-width: 0; font-size: 13.5px; font-weight: 800; color: var(--text); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.vn-top em { flex: none; font-style: normal; font-size: 10.5px; font-weight: 900; padding: 2px 8px; border-radius: 99px; color: #fff; background: #E11D48; }
.vn-wave { display: flex; align-items: center; gap: 2px; height: 30px; margin: 6px 0 2px; cursor: pointer; }
.vn-wave i { flex: 1; min-width: 2px; border-radius: 99px; background: color-mix(in srgb, var(--text2) 35%, transparent); transition: background .15s; }
.vn-wave i.on { background: rgb(var(--p)); }
.vn.playing .vn-wave i.on:last-of-type { animation: none; }
.vn-foot { display: flex; align-items: center; justify-content: space-between; }
.vn-foot span { font-size: 11.5px; font-weight: 700; color: var(--text2); direction: ltr; font-variant-numeric: tabular-nums; }
.vn-rate { font-size: 11px; font-weight: 900; padding: 2px 9px; border-radius: 99px; color: var(--text); background: var(--input-bg); }
@media (prefers-reduced-motion: reduce) { .vn.new::after, .vn.playing .vn-play::before { animation: none; } }

/* ===== شجرتي (solo focus tree) ===== */
#gardenView { animation: none !important; }
.gd { position: fixed; inset: 0; z-index: 55; overflow: hidden; color: #fff; background: linear-gradient(180deg, #7fb2e5 0%, #bcd7ee 45%, #3a2a1c 60%, #20160e 100%); }
