/* messages */
.vt-modal { position: fixed; inset: 0; z-index: 950; display: grid; place-items: center; padding: 20px; background: rgba(5, 2, 20, 0); transition: background .25s; }
.vt-modal.in { background: rgba(5, 2, 20, .7); }
.vt-m { width: 100%; max-width: 380px; padding: 24px 20px 18px; border-radius: 26px; text-align: center; color: #F5F3FF; background: linear-gradient(160deg, #2A1760, #1A1040); border: 1px solid rgba(255, 255, 255, .12); display: flex; flex-direction: column; align-items: center; gap: 10px; transform: scale(.9); opacity: 0; transition: all .3s cubic-bezier(.2, 1.3, .4, 1); }
