.cl-audio { display: none; }
.cl-call { position: fixed; inset: 0; z-index: 9990; display: flex; flex-direction: column; color: #fff; overflow: hidden; background: #0B1220; padding: max(14px, var(--safe-t)) 16px max(22px, var(--safe-b)); animation: clIn .45s cubic-bezier(.2,.8,.2,1); transition: transform .45s cubic-bezier(.6,0,.3,1), opacity .45s; }
.cl-call.cl-hide { transform: translateY(100%); opacity: 0; pointer-events: none; }
.cl-call.cl-bye { transform: scale(.94); opacity: 0; }
@keyframes clIn { from { transform: translateY(40px) scale(.97); opacity: 0; } to { transform: none; opacity: 1; } }
.cl-bg { position: absolute; inset: 0; z-index: 0; background: radial-gradient(120% 80% at 50% 0%, #1E3A8A 0%, #0B1220 60%); }
.cl-bg span { --c: 37,99,235; position: absolute; width: 90vmax; height: 90vmax; border-radius: 50%; background: radial-gradient(closest-side, rgba(var(--c), .55), rgba(var(--c), 0)); will-change: transform; animation: clBlob 14s ease-in-out infinite alternate; transition: opacity 1s; }
.cl-bg span:nth-child(1) { top: -40vmax; right: -35vmax; }
.cl-bg span:nth-child(2) { --c: 124,58,237; bottom: -45vmax; left: -40vmax; animation-duration: 18s; }
.cl-bg span:nth-child(3) { --c: 14,165,233; top: 20%; left: 10%; width: 60vmax; height: 60vmax; opacity: .5; animation-duration: 11s; }
.cl-call[data-st="in"] .cl-bg span:nth-child(1) { --c: 5,150,105; }
.cl-call[data-st="reconnect"] .cl-bg span:nth-child(3) { --c: 245,158,11; opacity: .8; }
.cl-call[data-st="bye"] .cl-bg span { opacity: .25; }
.cl-in { position: relative; z-index: 1; flex: 1; display: flex; flex-direction: column; min-height: 0; }
@keyframes clBlob { from { transform: translate3d(0,0,0) scale(1); } to { transform: translate3d(6vmax, 8vmax, 0) scale(1.12); } }
.cl-top, .cl-mid, .cl-btns, .cl-pts, .cl-code { position: relative; z-index: 1; }
.cl-top { display: flex; align-items: center; justify-content: space-between; gap: 8px; }
.cl-top > span:first-child { width: 42px; }
.cl-ic { width: 42px; height: 42px; border-radius: 50%; display: flex; align-items: center; justify-content: center; background: rgba(255,255,255,.12); color: #fff; transition: opacity .3s; }
.cl-lock { display: inline-flex; align-items: center; gap: 6px; padding: 7px 12px; border-radius: 999px; background: rgba(255,255,255,.1); font-size: 12px; font-weight: 700; color: rgba(255,255,255,.85); }
.cl-bars { width: 42px; display: flex; align-items: flex-end; justify-content: center; gap: 3px; height: 16px; }
.cl-bars i { width: 4px; border-radius: 2px; background: rgba(255,255,255,.3); transition: background .4s; }
.cl-bars i:nth-child(1) { height: 6px; } .cl-bars i:nth-child(2) { height: 11px; } .cl-bars i:nth-child(3) { height: 16px; }
.cl-bars[data-q="3"] i { background: #34D399; }
.cl-bars[data-q="2"] i:nth-child(-n+2) { background: #FBBF24; }
.cl-bars[data-q="1"] i:nth-child(1) { background: #F87171; }
.cl-code { margin: 14px auto 0; max-width: 360px; padding: 14px 16px; border-radius: 18px; background: rgba(15,23,42,.55); text-align: center; animation: clIn .3s ease; }
.cl-code-t { font-size: 12px; font-weight: 800; opacity: .75; }
.cl-code-n { font-size: 24px; font-weight: 900; letter-spacing: 3px; margin: 6px 0; font-variant-numeric: tabular-nums; }
.cl-code-d { font-size: 12px; line-height: 1.7; opacity: .8; }
.cl-mid { flex: 1; display: flex; flex-direction: column; align-items: center; justify-content: center; gap: 10px; }
.cl-orb { --lv: 0; position: relative; width: 150px; height: 150px; margin-bottom: 18px; }
.cl-avw { position: absolute; inset: 0; z-index: 2; border-radius: 50%; overflow: hidden; border: 3px solid rgba(255,255,255,.9); box-shadow: 0 20px 60px rgba(0,0,0,.45); transform: scale(calc(1 + var(--lv) * .06)); transition: transform .4s ease-out; -webkit-mask-image: -webkit-radial-gradient(white, black); isolation: isolate; }
.cl-orb.cl-ringing .cl-avw { animation: clBreath 2.4s ease-in-out infinite; }
@keyframes clBreath { 50% { transform: scale(1.045); } }
.cl-av { position: absolute; inset: 0; background: center / cover no-repeat; opacity: 0; transition: opacity .5s; }
.cl-av.on { opacity: 1; } .cl-av.now { transition: none; }
.cl-halo { position: absolute; inset: -12px; z-index: 1; border-radius: 50%; background: conic-gradient(#60A5FA, #A78BFA, #F472B6, #FBBF24, #34D399, #60A5FA); -webkit-mask: radial-gradient(farthest-side, transparent calc(100% - 4px), #000 calc(100% - 3px)); mask: radial-gradient(farthest-side, transparent calc(100% - 4px), #000 calc(100% - 3px)); animation: clSpin 3.2s linear infinite; opacity: calc(.2 + var(--lv) * 1.2); transition: opacity .4s ease-out; }
.cl-orb.cl-ringing .cl-halo { opacity: .95; animation-duration: 1.8s; }
.cl-call[data-st="bye"] .cl-halo { opacity: 0; }
@keyframes clSpin { to { transform: rotate(360deg); } }
.cl-dots { display: inline-flex; gap: 3px; margin-inline-start: 4px; vertical-align: middle; }
.cl-dots i { width: 5px; height: 5px; border-radius: 50%; background: currentColor; animation: clDot 1.2s ease-in-out infinite; }
.cl-dots i:nth-child(2) { animation-delay: .15s; } .cl-dots i:nth-child(3) { animation-delay: .3s; }
@keyframes clDot { 0%, 60%, 100% { transform: translateY(0); opacity: .4; } 30% { transform: translateY(-5px); opacity: 1; } }
.cl-ini { position: absolute; inset: 0; display: flex; align-items: center; justify-content: center; font-size: 50px; font-weight: 900; background: linear-gradient(135deg, #3B82F6, #8B5CF6); }
.cl-wave { position: absolute; inset: 0; border-radius: 50%; border: 2px solid rgba(255,255,255,.35); background: radial-gradient(circle, rgba(147,197,253,0) 55%, rgba(147,197,253,.22) 100%); opacity: 0; }
.cl-orb.cl-ringing .cl-wave { animation: clRipple 2.4s cubic-bezier(.2,.6,.3,1) infinite; }
.cl-orb.cl-ringing .cl-wave:nth-child(2) { animation-delay: .8s; }
.cl-orb.cl-ringing .cl-wave:nth-child(3) { animation-delay: 1.6s; }
@keyframes clRipple { 0% { transform: scale(1); opacity: .8; } 100% { transform: scale(2.2); opacity: 0; } }
.cl-orb:not(.cl-ringing) .cl-wave:nth-child(1) { opacity: calc(.15 + var(--lv) * .8); transform: scale(calc(1.06 + var(--lv) * .35)); background: radial-gradient(circle, rgba(96,165,250,.35), transparent 70%); border-color: rgba(147,197,253,.6); transition: transform .4s ease-out, opacity .4s ease-out; }
.cl-orb:not(.cl-ringing) .cl-wave:nth-child(2) { opacity: calc(var(--lv) * .6); transform: scale(calc(1.12 + var(--lv) * .6)); border-color: rgba(167,139,250,.5); transition: transform .55s ease-out, opacity .55s ease-out; }
.cl-name { font-size: 26px; font-weight: 900; text-align: center; text-shadow: 0 2px 20px rgba(0,0,0,.3); }
.cl-status { font-size: 15px; font-weight: 700; opacity: .8; font-variant-numeric: tabular-nums; min-height: 22px; }
.cl-call[data-st="out"] .cl-status::after, .cl-call[data-st="connecting"] .cl-status::after { content: ''; }
.cl-status.warn { color: #FCD34D; opacity: 1; animation: clBlink 1.2s ease-in-out infinite; }
@keyframes clBlink { 50% { opacity: .45; } }
.cl-chip { display: inline-flex; align-items: center; gap: 6px; padding: 6px 12px; border-radius: 999px; background: rgba(255,255,255,.12); font-size: 12px; font-weight: 700; animation: clIn .3s ease; }
.cl-weak { display: none; background: rgba(239,68,68,.25); }
.cl-weak.show { display: inline-flex; }
.cl-weak[data-lvl="lost"] { background: rgba(239,68,68,.45); font-weight: 700; }
.cl-gold { background: linear-gradient(90deg, #F59E0B, #FBBF24); color: #1F2937; font-weight: 900; }
.cl-pts { display: flex; align-items: center; gap: 12px; margin: 0 auto 18px; padding: 10px 16px; border-radius: 18px; background: rgba(255,255,255,.08); font-size: 13px; transition: opacity .3s; }
.cl-pts svg { width: 40px; height: 40px; transform: rotate(-90deg); flex: none; }
.cl-pts circle { fill: none; stroke-width: 4; stroke: rgba(255,255,255,.15); }
.cl-pts circle + circle { stroke: #FBBF24; stroke-linecap: round; stroke-dasharray: 113.1; transition: stroke-dashoffset 1s linear; }
.cl-pts b { color: #FCD34D; }
.cl-pts small { display: block; font-size: 11px; opacity: .7; margin-top: 2px; }
.cl-btns { display: flex; justify-content: center; gap: 28px; transition: opacity .3s; }
.cl-b { display: flex; flex-direction: column; align-items: center; gap: 8px; font-size: 12px; font-weight: 700; opacity: .9; }
.cl-enter .cl-b { animation: clUp .5s cubic-bezier(.2,.8,.2,1) backwards; }
.cl-enter .cl-b:nth-child(2) { animation-delay: .06s; } .cl-enter .cl-b:nth-child(3) { animation-delay: .12s; }
@keyframes clUp { from { transform: translateY(30px); opacity: 0; } }
.cl-round { position: relative; width: 68px; height: 68px; border-radius: 50%; display: flex; align-items: center; justify-content: center; color: #fff; transition: transform .15s, background .25s; }
.cl-round:active { transform: scale(.9); }
.cl-round:disabled { opacity: .4; }
.cl-red { background: #EF4444; box-shadow: 0 10px 30px rgba(239,68,68,.45); }
.cl-green { background: #22C55E; box-shadow: 0 10px 30px rgba(34,197,94,.5); }
.cl-soft { background: rgba(255,255,255,.14); }
.cl-soft.on { background: #fff; color: #0B1220; }
.cl-bounce { animation: clBounce 1.4s ease-in-out infinite; }
.cl-bounce::before { content: ''; position: absolute; inset: 0; border-radius: 50%; background: #22C55E; animation: clRipple 1.4s ease-out infinite; z-index: -1; }
@keyframes clBounce { 0%, 100% { transform: translateY(0); } 30% { transform: translateY(-10px) rotate(-12deg); } 45% { transform: translateY(0) rotate(10deg); } 60% { transform: rotate(-6deg); } }
.cl-me { --lv: 0; position: absolute; inset: -4px; border-radius: 50%; border: 2px solid #34D399; opacity: calc(var(--lv) * 1.2); transform: scale(calc(1 + var(--lv) * .15)); transition: opacity .4s ease-out, transform .4s ease-out; pointer-events: none; }
.cl-soft.on .cl-me { display: none; }
.cl-float { position: absolute; z-index: 3; left: 50%; top: 22%; transform: translateX(-50%); font-size: 30px; font-weight: 900; color: #FCD34D; text-shadow: 0 4px 24px rgba(245,158,11,.6); animation: clFloat 2.5s cubic-bezier(.2,.8,.2,1) forwards; pointer-events: none; }
@keyframes clFloat { 0% { opacity: 0; transform: translate(-50%, 30px) scale(.6); } 20% { opacity: 1; transform: translate(-50%, 0) scale(1.15); } 35% { transform: translate(-50%, -6px) scale(1); } 100% { opacity: 0; transform: translate(-50%, -120px) scale(1); } }
.cl-pill { position: fixed; z-index: 9989; top: max(10px, var(--safe-t)); left: 50%; transform: translateX(-50%); display: flex; align-items: center; gap: 8px; padding: 9px 16px; border-radius: 999px; background: #16A34A; color: #fff; font-size: 13px; font-weight: 800; box-shadow: 0 10px 30px rgba(22,163,74,.45); animation: clPill .4s cubic-bezier(.2,.8,.2,1); max-width: calc(100vw - 32px); }
.cl-pill > span:nth-of-type(2) { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; max-width: 40vw; }
.cl-pill-dot { width: 8px; height: 8px; border-radius: 50%; background: #fff; animation: clBlink 1.2s ease-in-out infinite; }
@keyframes clPill { from { transform: translate(-50%, -30px); opacity: 0; } }
@media (prefers-reduced-motion: reduce) { .cl-bg span, .cl-orb.cl-ringing .cl-wave, .cl-bounce, .cl-bounce::before { animation: none; } }

/* ---------- chat thread: time and ticks in the bubble, day separators ---------- */
.cm-bubble { position: relative; overflow-wrap: anywhere; }
