/* ---------- a new version is ready (js/app.js _updateReady) ---------- */
.upd-bar { position: fixed; z-index: 9000; left: 12px; right: 12px; bottom: calc(84px + var(--safe-b)); display: flex; align-items: center; gap: 8px; padding: 10px 12px; border-radius: 16px; background: #0F172A; color: #fff; font-size: 13px; font-weight: 700; box-shadow: 0 12px 30px rgba(0,0,0,.25); animation: clPill .35s ease; }
