/* ===== أبو الهمّة (js/mascot.js) ===== */
.mc-wrap { --hid: translateY(130%); --dx: 0px; position: fixed; z-index: 9300; width: min(88vw, 340px); display: flex; flex-direction: column; gap: 4px; pointer-events: none; direction: ltr; transform: var(--hid) translateX(var(--dx)); opacity: 0; transition: transform .6s cubic-bezier(.2,1.45,.4,1), opacity .25s; touch-action: pan-y; }
.mc-wrap.on { transform: translateX(var(--dx)); opacity: 1; }
.mc-wrap.off { transform: var(--hid); opacity: 0; transition: transform .45s ease-in, opacity .4s; }
.mc-wrap[data-fling="l"].off { transform: translateX(-130vw) rotate(-14deg); transition: transform .5s ease-in; }
.mc-wrap[data-fling="r"].off { transform: translateX(130vw) rotate(14deg); transition: transform .5s ease-in; }
/* corners at the bottom */
.mc-wrap[data-from="bl"], .mc-wrap[data-from="br"] { bottom: calc(86px + var(--safe-b, 0px)); }
body.sub-nav-hidden .mc-wrap[data-from="bl"], body.sub-nav-hidden .mc-wrap[data-from="br"] { bottom: calc(14px + var(--safe-b, 0px)); }
.mc-wrap[data-from="bl"] { left: calc(6px + env(safe-area-inset-left, 0px)); align-items: flex-start; }
.mc-wrap[data-from="br"] { right: calc(6px + env(safe-area-inset-right, 0px)); align-items: flex-end; }
.mc-wrap[data-from="br"] .mc-owl .mc-ob { transform: scaleX(-1); }
/* corners at the top: drops down like on a spring, bubble under it */
.mc-wrap[data-from="tl"], .mc-wrap[data-from="tr"] { --hid: translateY(-160%); top: calc(70px + env(safe-area-inset-top, 0px)); flex-direction: column-reverse; }
.mc-wrap[data-from="tl"] { left: 6px; align-items: flex-start; }
.mc-wrap[data-from="tr"] { right: 6px; align-items: flex-end; }
.mc-wrap[data-from="tr"] .mc-owl .mc-ob { transform: scaleX(-1); }
.mc-wrap[data-from="tl"] .mc-bub::after, .mc-wrap[data-from="tr"] .mc-bub::after { bottom: auto; top: -13px; transform: rotate(225deg); }
.mc-wrap[data-from="tr"] .mc-bub::after { inset-inline-start: auto; left: auto; right: 46px; }
/* peeking from the side edge: half behind the screen edge, bubble beside it */
.mc-wrap[data-from="l"], .mc-wrap[data-from="r"] { top: 34%; width: min(96vw, 380px); flex-direction: row; align-items: flex-end; }
.mc-wrap[data-from="l"] { left: 0; --hid: translateX(-110%); flex-direction: row-reverse; }
.mc-wrap[data-from="r"] { right: 0; --hid: translateX(110%); flex-direction: row; }
.mc-wrap[data-from="l"] .mc-owl { margin-left: -44px; margin-right: 0; }
.mc-wrap[data-from="r"] .mc-owl { margin-right: -44px; margin-left: 0; }
.mc-wrap[data-from="r"] .mc-owl .mc-ob { transform: scaleX(-1); }
.mc-wrap[data-from="l"] .mc-bub { margin: 0 0 30px 4px; }
.mc-wrap[data-from="r"] .mc-bub { margin: 0 4px 30px 0; }
.mc-wrap[data-from="l"] .mc-bub::after { bottom: 26px; left: -13px; right: auto; inset-inline-start: auto; transform: rotate(135deg); }
.mc-wrap[data-from="r"] .mc-bub::after { bottom: 26px; right: -13px; left: auto; inset-inline-start: auto; transform: rotate(-45deg); }
/* flying in from far away, flapping, and landing */
.mc-wrap.mc-fly[data-side="l"] { --hid: none; }
.mc-wrap.mc-fly { transition: opacity .2s; animation: mc-fly-in 1.15s cubic-bezier(.25,.8,.3,1.12) both; }
.mc-wrap.mc-fly[data-side="r"] { animation-name: mc-fly-in-r; }
@keyframes mc-fly-in { 0% { transform: translate(-120vw, -55vh) rotate(-18deg) scale(.7); } 55% { transform: translate(8vw, -8vh) rotate(8deg) scale(1.08); } 100% { transform: translate(0, 0) rotate(0) scale(1); } }
@keyframes mc-fly-in-r { 0% { transform: translate(120vw, -55vh) rotate(18deg) scale(.7); } 55% { transform: translate(-8vw, -8vh) rotate(-8deg) scale(1.08); } 100% { transform: translate(0, 0) rotate(0) scale(1); } }
.mc-wrap.mc-fly.off { animation: none; }
.mc-wrap.mc-fly-out { transition: transform .95s cubic-bezier(.5,0,.9,.6), opacity .8s .15s; transform: translate(-30vw, -90vh) rotate(-12deg) scale(.6); }
.mc-wrap.mc-fly-out[data-side="r"] { transform: translate(30vw, -90vh) rotate(12deg) scale(.6); }
.mc-bub { pointer-events: auto; position: relative; align-self: stretch; margin-left: 14px; margin-right: 14px; direction: rtl; background: #fffdf6; color: #2a1a0e; border: 2.5px solid #7a4d27; border-radius: 20px; padding: 10px 14px 12px; box-shadow: 0 10px 28px rgba(0,0,0,.28); transform-origin: 20% 100%; animation: mc-pop .5s .35s both cubic-bezier(.2,1.6,.4,1); touch-action: pan-y; }
.mc-bub::after { content: ""; position: absolute; bottom: -13px; left: 46px; width: 22px; height: 22px; background: #fffdf6; border-right: 2.5px solid #7a4d27; border-bottom: 2.5px solid #7a4d27; transform: rotate(45deg); border-bottom-right-radius: 5px; }
.mc-wrap[data-from="br"] .mc-bub::after { left: auto; right: 46px; }
