@keyframes mc-hop { 0%, 100% { transform: translateY(0) scale(1); } 25% { transform: translateY(2px) scale(1.06, .92); } 55% { transform: translateY(-22px) scale(.95, 1.08); } 80% { transform: translateY(0) scale(1.05, .95); } }
