@keyframes mc-tilt { 0%, 100% { transform: rotate(0); } 30%, 70% { transform: rotate(-9deg); } }
.mc-owl.act-shake .mc-ob svg { animation: mc-jit .1s linear 7; }
.mc-owl .mc-pu { transition: transform .25s ease-out; }
.mc-wl, .mc-wr { transform-box: fill-box; }
.mc-wl { transform-origin: 85% 12%; }
.mc-wr { transform-origin: 15% 12%; }
.mc-owl.act-flap .mc-wl { animation: mc-flapl .22s ease-in-out 4; }
