/* ===== أبو الهمّة: 30 tap reactions, particles, and the chat pause ===== */
.mc-owl[class*="r-"] .mc-ob svg { transform-origin: 50% 90%; animation-fill-mode: both; }
.mc-owl.r-laugh .mc-ob svg { animation: mcr-laugh .28s ease-in-out 7; }
.mc-owl.r-mad .mc-ob svg { animation: mc-jit .09s linear 14; filter: hue-rotate(-18deg) saturate(1.5); }
.mc-owl.r-flip .mc-ob svg { animation: mcr-flip 1s ease-in-out; }
.mc-owl.r-spin .mc-ob svg { animation: mcr-spin 1.3s ease-in-out; }
.mc-owl.r-dizzy .mc-ob svg { animation: mcr-dizzy 1.6s ease-in-out; }
.mc-owl.r-sleep .mc-ob svg { animation: mcr-sleep 2s ease-in-out; }
.mc-owl.r-wink .mc-ob svg { animation: mcr-tilt2 1.1s ease-in-out; }
.mc-owl.r-cry .mc-ob svg { animation: mcr-shiver .12s linear 16; }
.mc-owl.r-love .mc-ob svg { animation: mcr-pulse .45s ease-in-out 4; }
.mc-owl.r-jump .mc-ob svg { animation: mcr-jump 1s cubic-bezier(.3,.7,.4,1); }
.mc-owl.r-grow .mc-ob svg { animation: mcr-grow 2s ease-in-out; }
.mc-owl.r-shrink .mc-ob svg { animation: mcr-shrink 2s ease-in-out; }
.mc-owl.r-wings .mc-ob svg { animation: mcr-hover 1.8s ease-in-out; }
.mc-owl.r-wings .mc-wl { animation: mc-flapl .12s ease-in-out infinite; } .mc-owl.r-wings .mc-wr:not(.mc-wingup) { animation: mc-flapr .12s ease-in-out infinite; }
.mc-owl.r-peek .mc-ob svg { animation: mcr-peek 1.8s ease-in-out; }
.mc-owl.r-salute .mc-ob svg { animation: mcr-salute 1.6s ease-in-out; }
.mc-owl.r-sneeze .mc-ob svg { animation: mcr-sneeze 1.4s ease-in-out; }
.mc-owl.r-yawn .mc-ob svg { animation: mcr-yawn 2s ease-in-out; }
.mc-owl.r-yawn .mc-jaw { animation: mcr-jaw 2s ease-in-out; transform-box: fill-box; }
.mc-owl.r-party .mc-ob svg { animation: mcr-party .35s ease-in-out 6; }
.mc-owl.r-facepalm .mc-ob svg { animation: mcr-face 1.8s ease-in-out; }
.mc-owl.r-think .mc-ob svg { animation: mcr-think 2s ease-in-out; }
.mc-owl.r-shock .mc-ob svg { animation: mcr-shockk .9s ease-out; }
.mc-owl.r-kiss .mc-ob svg { animation: mcr-kiss 1.2s ease-in-out; }
.mc-owl.r-super .mc-ob svg { animation: mcr-super 1.8s ease-in-out; }
.mc-owl.r-cold .mc-ob svg { animation: mcr-shiver .07s linear 26; filter: hue-rotate(160deg) saturate(.8) brightness(1.1); }
.mc-owl.r-hot .mc-ob svg { animation: mcr-pulse .3s ease-in-out 6; filter: hue-rotate(-30deg) saturate(2) brightness(1.05); }
.mc-owl.r-roll .mc-ob svg { animation: mcr-roll 1.6s ease-in-out; }
.mc-owl.r-stretch .mc-ob svg { animation: mcr-stretch 1.8s ease-in-out; }
.mc-owl.r-dance .mc-ob svg { animation: mcr-dance .5s ease-in-out 5; }
.mc-owl.r-pop .mc-ob svg { animation: mcr-pop 1s cubic-bezier(.2,1.5,.4,1); }
.mc-owl.r-teach .mc-ob svg { animation: mcr-teach .5s ease-in-out 4; }
@keyframes mcr-laugh { 0%,100% { transform: translateY(0) rotate(0); } 50% { transform: translateY(-9px) rotate(-4deg); } }
@keyframes mcr-flip { 0% { transform: translateY(0) rotate(0); } 50% { transform: translateY(-50px) rotate(-180deg); } 100% { transform: translateY(0) rotate(-360deg); } }
@keyframes mcr-spin { to { transform: rotateY(720deg); } }
@keyframes mcr-dizzy { 0%,100% { transform: rotate(0); } 15% { transform: rotate(14deg) translateX(8px); } 35% { transform: rotate(-16deg) translateX(-10px); } 55% { transform: rotate(12deg) translateX(8px); } 75% { transform: rotate(-8deg); } }
@keyframes mcr-sleep { 0% { transform: rotate(0); } 25%,80% { transform: rotate(18deg) translateY(10px); } 100% { transform: rotate(0); } }
@keyframes mcr-tilt2 { 0%,100% { transform: rotate(0); } 30%,70% { transform: rotate(8deg) translateY(-4px); } }
@keyframes mcr-shiver { 0%,100% { transform: translateX(-2px); } 50% { transform: translateX(2px); } }
@keyframes mcr-pulse { 0%,100% { transform: scale(1); } 50% { transform: scale(1.12); } }
@keyframes mcr-jump { 0%,100% { transform: translateY(0) scale(1,1); } 15% { transform: translateY(4px) scale(1.1,.88); } 50% { transform: translateY(-70px) scale(.92,1.12); } 85% { transform: translateY(0) scale(1.08,.92); } }
@keyframes mcr-grow { 0%,100% { transform: scale(1); } 25%,75% { transform: scale(1.45); } }
@keyframes mcr-shrink { 0%,100% { transform: scale(1); } 25%,75% { transform: scale(.55); } }
@keyframes mcr-hover { 0%,100% { transform: translateY(0); } 25%,75% { transform: translateY(-45px) rotate(-4deg); } 50% { transform: translateY(-55px) rotate(4deg); } }
@keyframes mcr-peek { 0%,100% { transform: translateY(0); } 25%,75% { transform: translateY(78%); } }
@keyframes mcr-salute { 0%,100% { transform: rotate(0); } 25%,75% { transform: rotate(-6deg) translateY(-6px); } }
@keyframes mcr-sneeze { 0%,40% { transform: scale(1); } 50% { transform: scale(1.14,1.14) translateY(-4px); } 60% { transform: scale(.9,.88) translateY(6px) rotate(6deg); } 100% { transform: scale(1); } }
@keyframes mcr-yawn { 0%,100% { transform: scaleY(1); } 40%,70% { transform: scaleY(1.1) translateY(-4px); } }
@keyframes mcr-jaw { 0%,100% { transform: translateY(0) scaleY(1); } 40%,70% { transform: translateY(14px) scaleY(2.4); } }
@keyframes mcr-party { 0%,100% { transform: translateY(0) rotate(-6deg); } 50% { transform: translateY(-16px) rotate(6deg); } }
@keyframes mcr-face { 0%,100% { transform: rotate(0) translateY(0); } 30%,75% { transform: rotate(-12deg) translateY(14px) scale(.96); } }
@keyframes mcr-think { 0%,100% { transform: rotate(0); } 20%,80% { transform: rotate(-7deg) translateX(-6px); } 50% { transform: rotate(5deg) translateX(6px); } }
@keyframes mcr-shockk { 0% { transform: scale(1); } 20% { transform: scale(1.2,1.25) translateY(-22px); } 100% { transform: scale(1); } }
@keyframes mcr-kiss { 0%,100% { transform: scale(1) rotate(0); } 40% { transform: scale(1.12) rotate(-6deg) translateY(-8px); } 60% { transform: scale(1.12) rotate(4deg) translateY(-8px); } }
@keyframes mcr-super { 0% { transform: translate(0,0) rotate(0); } 30% { transform: translate(0,-70px) rotate(0); } 55% { transform: translate(70px,-120px) rotate(35deg); } 80% { transform: translate(-50px,-60px) rotate(-25deg); } 100% { transform: translate(0,0) rotate(0); } }
@keyframes mcr-roll { 0% { transform: translateX(0) rotate(0); } 40% { transform: translateX(-70px) rotate(-360deg); } 80% { transform: translateX(40px) rotate(180deg); } 100% { transform: translateX(0) rotate(0); } }
@keyframes mcr-stretch { 0%,100% { transform: scale(1,1); } 30%,70% { transform: scale(.78,1.35); } }
@keyframes mcr-dance { 0%,100% { transform: translateX(-10px) rotate(-8deg); } 50% { transform: translateX(10px) rotate(8deg) translateY(-12px); } }
@keyframes mcr-pop { 0% { transform: scale(0); } 55% { transform: scale(1.3); } 100% { transform: scale(1); } }
@keyframes mcr-teach { 0%,100% { transform: rotate(-3deg); } 50% { transform: rotate(3deg) translateY(-6px); } }
/* particles */
.mc-fx { position: absolute; left: var(--x, 0); top: var(--y, 0); pointer-events: none; opacity: 0; font-style: normal; font-weight: 900; }
.mc-fx.f-hearts { width: 18px; height: 16px; background: #f43f5e; transform: rotate(-45deg); animation: mcf-up 2s ease-out forwards; }
.mc-fx.f-hearts::before, .mc-fx.f-hearts::after { content: ""; position: absolute; width: 18px; height: 16px; background: inherit; border-radius: 50%; } .mc-fx.f-hearts::before { left: 9px; } .mc-fx.f-hearts::after { top: -9px; }
.mc-fx.f-stars, .mc-fx.f-sparks { width: 16px; height: 16px; background: #fbbf24; clip-path: polygon(50% 0, 62% 38%, 100% 50%, 62% 62%, 50% 100%, 38% 62%, 0 50%, 38% 38%); animation: mcf-up 1.6s ease-out forwards; }
.mc-fx.f-sparks { background: #fde68a; width: 12px; height: 12px; animation: mcf-burst 1.2s ease-out forwards; }
.mc-fx.f-tears, .mc-fx.f-drops { width: 9px; height: 13px; background: #60a5fa; border-radius: 50% 50% 50% 50% / 62% 62% 38% 38%; animation: mcf-fall 1.4s ease-in forwards; }
.mc-fx.f-anger { width: 18px; height: 18px; background: #ef4444; clip-path: polygon(40% 0, 60% 0, 60% 40%, 100% 40%, 100% 60%, 60% 60%, 60% 100%, 40% 100%, 40% 60%, 0 60%, 0 40%, 40% 40%); animation: mcf-burst 1s ease-out forwards; }
.mc-fx.f-zzz { color: #93c5fd; font-size: 22px; font-family: sans-serif; animation: mcf-up 2.2s ease-out forwards; }
.mc-fx.f-steam { width: 18px; height: 18px; border-radius: 50%; background: rgba(226,232,240,.85); filter: blur(3px); animation: mcf-up 1.6s ease-out forwards; }
.mc-fx.f-confetti { width: 8px; height: 12px; background: var(--c); animation: mcf-conf 1.8s ease-out forwards; }
.mc-fx.f-dots { color: #7a4d27; font-size: 40px; line-height: 1; animation: mcf-up 1.8s ease-out forwards; }
.mc-fx.f-notes { color: var(--c); font-size: 24px; animation: mcf-up 2s ease-out forwards; }
@keyframes mcf-up { 0% { opacity: 0; transform: translateY(0) scale(.4); } 20% { opacity: 1; } 100% { opacity: 0; transform: translateY(-110px) scale(1.1) rotate(25deg); } }
@keyframes mcf-fall { 0% { opacity: 0; transform: translateY(10px); } 25% { opacity: 1; } 100% { opacity: 0; transform: translateY(70px); } }
@keyframes mcf-burst { 0% { opacity: 0; transform: scale(.3); } 25% { opacity: 1; transform: scale(1.2); } 100% { opacity: 0; transform: translate(calc(var(--x) * 1.6), -60px) scale(.6); } }
@keyframes mcf-conf { 0% { opacity: 1; transform: translateY(-20px) rotate(0); } 100% { opacity: 0; transform: translate(calc(var(--x) * 2), 110px) rotate(540deg); } }
/* the chat pause */
.mc-lock { position: absolute; left: 0; right: 0; bottom: 0; z-index: 30; display: flex; flex-direction: column; align-items: center; justify-content: center; gap: 10px; padding: 24px; text-align: center; background: color-mix(in srgb, var(--bg) 94%, #7a4d27); }
.mc-lock h3 { margin: 0; font-size: 20px; font-weight: 900; color: var(--text); }
.mc-lock p { margin: 0; font-size: 14.5px; line-height: 1.8; font-weight: 700; color: var(--text); max-width: 320px; }
.mc-lock small { color: var(--text2); font-size: 12px; }
.mc-lk-owl { width: 110px; animation: mc-bob 2.6s ease-in-out infinite; filter: drop-shadow(0 6px 8px rgba(0,0,0,.25)); }
.mc-lk-owl svg { width: 100%; display: block; }
.mc-lk-t { font-size: 40px; font-weight: 900; font-variant-numeric: tabular-nums; color: #b45309; letter-spacing: .04em; }
.mc-lk-b { display: flex; gap: 8px; flex-wrap: wrap; justify-content: center; margin-top: 4px; }
.mc-lk-b button { padding: 11px 18px; border-radius: 14px; font: inherit; font-size: 13.5px; font-weight: 800; }
.mc-lk-off { margin-top: 10px; background: transparent; color: var(--text2); font: inherit; font-size: 12px; text-decoration: underline; padding: 6px; }
@media (prefers-reduced-motion: reduce) { .mc-owl[class*="r-"] .mc-ob svg, .mc-fx, .mc-lk-owl { animation: none !important; } }

/* ===== promo pop-up ===== */
.pp-w { position: fixed; inset: 0; z-index: 9400; display: flex; align-items: center; justify-content: center; padding: 22px; opacity: 0; transition: opacity .25s ease; pointer-events: none; }
.pp-w.on { opacity: 1; pointer-events: auto; }
.pp-bd { position: absolute; inset: 0; background: rgba(8, 15, 28, .62); backdrop-filter: blur(6px); -webkit-backdrop-filter: blur(6px); }
.pp-card { position: relative; width: min(100%, 360px); max-height: 88vh; overflow: auto; border-radius: 28px; background: var(--surface); color: var(--text); box-shadow: 0 30px 70px -20px rgba(0,0,0,.55); transform: translateY(24px) scale(.94); transition: transform .38s cubic-bezier(.2,1.2,.4,1); }
.pp-w.on .pp-card { transform: none; }
.pp-x { position: absolute; top: 12px; inset-inline-start: 12px; z-index: 2; width: 34px; height: 34px; border-radius: 50%; display: grid; place-items: center; color: #fff; background: rgba(0,0,0,.38); backdrop-filter: blur(4px); }
.pp-img { position: relative; aspect-ratio: 16 / 10; background: var(--input-bg); }
.pp-img img { width: 100%; height: 100%; object-fit: cover; display: block; }
.pp-img::after { content: ''; position: absolute; inset: auto 0 0 0; height: 46%; background: linear-gradient(to top, var(--surface), transparent); }
.pp-glow { height: 74px; background: radial-gradient(circle at 30% 30%, rgb(var(--p)), transparent 70%), linear-gradient(135deg, color-mix(in srgb, rgb(var(--p)) 55%, #7c3aed), rgb(var(--p))); border-radius: 28px 28px 0 0; }
.pp-body { padding: 8px 22px 20px; display: flex; flex-direction: column; gap: 10px; text-align: center; }
.pp-body h3 { margin: 0; font-size: 20px; font-weight: 900; line-height: 1.4; }
.pp-body p { margin: 0; font-size: 14px; line-height: 1.85; color: var(--text2); font-weight: 600; white-space: pre-line; }
.pp-go { margin-top: 6px; height: 50px; border-radius: 16px; font: inherit; font-size: 15px; font-weight: 900; color: #fff; background: linear-gradient(135deg, rgb(var(--p)), color-mix(in srgb, rgb(var(--p)) 55%, #7c3aed)); box-shadow: 0 10px 22px -10px rgb(var(--p)); }
.pp-go:active { transform: scale(.97); }
.pp-later { padding: 8px; font: inherit; font-size: 13px; font-weight: 700; color: var(--text2); background: transparent; }
@media (prefers-reduced-motion: reduce) { .pp-card, .pp-w { transition: none !important; animation: none !important; } }

/* ===== Sign in with Google ===== */
.g-wrap { margin-top: 18px; display: flex; flex-direction: column; }
.g-wrap .g-note { order: 1; } .g-wrap .g-or { order: 2; } .g-wrap .g-btn { order: 3; }
.g-wrap.top { margin: 4px 0 16px; } .g-wrap.top .g-btn { order: 2; } .g-wrap.top .g-or { order: 3; margin: 14px 0 0; }
.g-or { display: flex; align-items: center; gap: 12px; color: var(--text2); font-size: 12px; font-weight: 700; margin: 4px 0 14px; }
.g-or::before, .g-or::after { content: ''; flex: 1; height: 1px; background: var(--border); }
.g-btn { width: 100%; height: 50px; border-radius: 14px; display: flex; align-items: center; justify-content: center; gap: 10px; font: inherit; font-size: 14.5px; font-weight: 800; color: #1f1f1f; background: #fff; border: 1.5px solid #dadce0; box-shadow: 0 1px 2px rgba(0,0,0,.08); transition: transform .12s ease, box-shadow .2s; }
.g-btn:active { transform: scale(.98); }
.g-btn.busy { opacity: .6; pointer-events: none; }
@media (prefers-color-scheme: dark) { :root:not([data-theme="light"]) .g-btn { background: #fff; } }
.g-note { margin: 0 0 12px; padding: 12px 14px; border-radius: 14px; font-size: 13px; font-weight: 700; line-height: 1.8; color: var(--text); background: color-mix(in srgb, rgb(var(--p)) 10%, var(--surface)); border: 1px solid color-mix(in srgb, rgb(var(--p)) 30%, transparent); }
.gp-w { position: fixed; inset: 0; z-index: 9500; display: flex; align-items: flex-end; justify-content: center; opacity: 0; transition: opacity .25s; }
.gp-w.on { opacity: 1; }
.gp-bd { position: absolute; inset: 0; background: rgba(8,15,28,.6); backdrop-filter: blur(5px); -webkit-backdrop-filter: blur(5px); }
.gp-card { position: relative; width: min(100%, 460px); max-height: 92vh; overflow: auto; padding: 20px 18px calc(18px + var(--safe-b, 0px)); border-radius: 26px 26px 0 0; background: var(--surface); color: var(--text); display: flex; flex-direction: column; gap: 12px; transform: translateY(40px); transition: transform .32s cubic-bezier(.2,1,.4,1); }
.gp-w.on .gp-card { transform: none; }
.gp-top { display: flex; align-items: center; gap: 12px; }
.gp-top b { display: block; font-size: 17px; font-weight: 900; } .gp-top small { color: var(--text2); font-size: 12px; }
