.tu-skel { display: flex; flex-direction: column; gap: 18px; padding: 12px 16px; }
.tu-skel i { display: block; aspect-ratio: 16 / 9; border-radius: 16px; background: linear-gradient(90deg, var(--input-bg), color-mix(in srgb, var(--input-bg) 50%, transparent), var(--input-bg)); background-size: 200% 100%; animation: tuSk 1.3s linear infinite; }
