.tu-x, .tu-fs { position: absolute; top: calc(var(--safe-t, 0px) + 8px); z-index: 3; width: 40px; height: 40px; border-radius: 50%; display: grid; place-items: center; color: #fff; background: rgba(0,0,0,.5); backdrop-filter: blur(4px); }
