.ex-bar { display: flex; align-items: center; gap: 10px; padding: calc(var(--safe-t, 0px) + 10px) 12px 8px; background: var(--surface); border-bottom: 1px solid var(--border); }
.ex-bar button { width: 40px; height: 40px; border-radius: 12px; display: grid; place-items: center; background: var(--input-bg); color: var(--text); }
.ex-bar b { flex: 1; min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; color: var(--text); }
.ex-acts { display: flex; gap: 8px; padding: 8px 12px; overflow-x: auto; background: var(--surface); }
.ex-acts button { flex: none; display: inline-flex; align-items: center; gap: 6px; padding: 8px 14px; border-radius: 999px; font: inherit; font-size: 13px; font-weight: 700; color: #fff; background: #7C3AED; }
.ex-acts button svg { width: 16px; height: 16px; }
.ex-pages { flex: 1; overflow-y: auto; padding: 10px 8px calc(var(--safe-b, 0px) + 20px); background: #64748b33; }
.ex-pw { margin: 0 auto 12px; position: relative; box-shadow: 0 4px 18px rgba(0,0,0,.25); background: #fff; overflow: hidden; direction: ltr; }
.ex-pi { width: 794px; transform-origin: top left; }
.ex-timer { position: fixed; top: calc(var(--safe-t, 0px) + 8px); left: 50%; transform: translateX(-50%); z-index: 500; display: flex; align-items: center; gap: 12px; padding: 8px 10px 8px 16px; border-radius: 999px; background: #1e1b4b; color: #fff; box-shadow: 0 6px 20px rgba(0,0,0,.35); }
.ex-timer span { display: inline-flex; align-items: center; gap: 6px; font-variant-numeric: tabular-nums; font-weight: 800; }
.ex-timer svg { width: 16px; height: 16px; }
.ex-timer button { padding: 6px 12px; border-radius: 999px; font: inherit; font-size: 12px; font-weight: 800; background: #fff; color: #1e1b4b; }
.ex-load { position: fixed; bottom: calc(var(--safe-b, 0px) + 90px); left: 50%; transform: translateX(-50%); z-index: 600; padding: 8px 16px; border-radius: 999px; background: #1e1b4b; color: #fff; font-size: 13px; }

/* the bottom sheet (settings, notification choices, ...) scrolls inside itself when its content is tall, and never drags the page behind it */
#walletModal > div.relative { max-height: 90vh; max-height: 90dvh; display: flex; flex-direction: column; }
#walletModal > div.relative > .p-4 { overflow-y: auto; overscroll-behavior: contain; -webkit-overflow-scrolling: touch; padding-bottom: calc(32px + var(--safe-b, 0px)); }
#walletModal { overscroll-behavior: contain; touch-action: none; }
#walletModal > div.relative { touch-action: pan-y; }

/* a notification banner that drops from the top while the app is open (like chat apps) */
.hds { position: fixed; left: 10px; right: 10px; top: calc(var(--safe-t, 0px) + 8px); z-index: 9000; display: flex; align-items: center; gap: 12px; padding: 12px 14px; border-radius: 20px; background: color-mix(in srgb, var(--surface) 94%, transparent); color: var(--text); border: 1px solid var(--border); box-shadow: 0 10px 30px rgba(0,0,0,.28); backdrop-filter: blur(14px); transform: translateY(-140%); opacity: 0; transition: transform .28s cubic-bezier(.2,.9,.3,1), opacity .2s; max-width: 520px; margin: 0 auto; cursor: pointer; }
.hds.on { transform: translateY(0); opacity: 1; }
.hds img { width: 40px; height: 40px; border-radius: 11px; flex: none; }
.hds div { min-width: 0; display: flex; flex-direction: column; }
.hds small { font-size: 11px; color: var(--text2); }
.hds b { font-size: 14px; line-height: 1.4; }
.hds span { font-size: 12.5px; color: var(--text2); display: -webkit-box; -webkit-line-clamp: 2; -webkit-box-orient: vertical; overflow: hidden; }

/* weekly study plan */
.pl-ctl { display: flex; flex-direction: column; gap: 10px; padding: 14px; margin-bottom: 14px; border-radius: 18px; background: var(--surface); border: 1px solid var(--border); }
.pl-ctl label { display: flex; align-items: center; justify-content: space-between; gap: 10px; font-size: 13px; font-weight: 700; color: var(--text); }
.pl-ctl select, .pl-ctl input { padding: 9px 12px; border-radius: 12px; border: 1px solid var(--border); background: var(--input-bg); color: var(--text); font: inherit; font-size: 13px; }
.pl-ctl input { width: 100%; }
.pl-go { padding: 12px; border-radius: 14px; font: inherit; font-weight: 800; color: #fff; background: #0EA5E9; }
.pl-go:disabled { opacity: .6; }
.pl-err, .pl-old { margin: 0; font-size: 12.5px; color: #DC2626; }
.pl-old { padding: 10px 12px; margin-bottom: 12px; border-radius: 12px; background: color-mix(in srgb, #F59E0B 14%, var(--surface)); color: var(--text); }
.pl-empty { display: flex; flex-direction: column; align-items: center; gap: 8px; padding: 30px 16px; text-align: center; color: var(--text2); }
.pl-empty svg { width: 40px; height: 40px; }
.pl-sum { padding: 14px; margin-bottom: 12px; border-radius: 18px; background: color-mix(in srgb, #0EA5E9 10%, var(--surface)); border: 1px solid color-mix(in srgb, #0EA5E9 30%, transparent); color: var(--text); }
.pl-sum small { display: block; margin-top: 6px; color: var(--text2); }
.pl-bar { height: 8px; margin-top: 10px; border-radius: 99px; background: var(--border); overflow: hidden; }
.pl-bar i { display: block; height: 100%; background: #0EA5E9; border-radius: 99px; transition: width .3s; }
.pl-day { padding: 12px; margin-bottom: 10px; border-radius: 18px; background: var(--surface); border: 1px solid var(--border); }
.pl-day.today { border-color: #0EA5E9; box-shadow: 0 0 0 2px color-mix(in srgb, #0EA5E9 25%, transparent); }
.pl-day.past { opacity: .65; }
.pl-dh { display: flex; justify-content: space-between; align-items: center; margin-bottom: 6px; color: var(--text); }
.pl-dh span { font-size: 12px; color: var(--text2); }
.pl-t { display: flex; align-items: center; gap: 10px; padding: 8px 0; border-top: 1px solid var(--border); font-size: 13px; color: var(--text); }
.pl-t input { width: 20px; height: 20px; flex: none; accent-color: #0EA5E9; }
.pl-t > span { flex: 1; min-width: 0; display: flex; flex-direction: column; }
.pl-t > span b { font-size: 12px; color: #0EA5E9; }
.pl-t em { font-style: normal; font-size: 12px; color: var(--text2); flex: none; }
.pl-t.on > span { text-decoration: line-through; opacity: .55; }
.pl-rest { margin: 0; padding: 6px 0; font-size: 13px; color: var(--text2); }

/* notification list: glass cards on the plain background (swipe right = read, left = delete) */
.ng-sw { position: relative; border-radius: 22px; overflow: hidden; }
.ng-act { position: absolute; inset: 0; display: none; align-items: center; gap: 8px; padding: 0 22px; font-weight: 800; font-size: 13px; }
.ng-act svg { width: 18px; height: 18px; }
.ng-read { background: #14532d; color: #bbf7d0; justify-content: flex-start; }
.ng-del { background: #7f1d1d; color: #fecaca; justify-content: flex-end; }
.ng-del button { display: flex; align-items: center; gap: 6px; color: inherit; font-weight: 800; font-size: 13px; padding: 12px 4px; }
.ng-sw.r .ng-read, .ng-sw.l .ng-del { display: flex; }
.ng-card { position: relative; display: flex; align-items: center; gap: 12px; padding: 13px 14px 13px 52px; background: var(--surface); border: 1px solid var(--border); border-radius: 22px; backdrop-filter: blur(14px); -webkit-backdrop-filter: blur(14px); box-shadow: inset 0 1px 0 var(--glass-highlight); touch-action: pan-y; cursor: pointer; }
.ng-rg { width: 48px; height: 48px; flex: none; border-radius: 50%; padding: 2px; display: grid; place-items: center; background: var(--border); color: var(--text2); }
.ng-card.un .ng-rg { background: conic-gradient(var(--c), color-mix(in srgb, var(--c) 30%, #fff), var(--c)); color: var(--c); }
.ng-rg > i { width: 100%; height: 100%; border-radius: 50%; background: var(--bg); display: grid; place-items: center; }
.ng-rg svg { width: 21px; height: 21px; }
.ng-tx { flex: 1; min-width: 0; }
.ng-tx b { display: block; font-size: 14px; line-height: 1.45; color: var(--text); font-weight: 800; }
.ng-card:not(.un) .ng-tx b { font-weight: 600; }
.ng-tx p { font-size: 12px; color: var(--text2); margin-top: 2px; line-height: 1.5; display: -webkit-box; -webkit-line-clamp: 2; -webkit-box-orient: vertical; overflow: hidden; }
.ng-card time { position: absolute; left: 14px; top: 12px; font-size: 10.5px; color: var(--text2); }
.ng-hint { text-align: center; color: var(--text2); opacity: .7; font-size: 11px; margin-top: 2px; }

/* أبو الهمّة: surprise stunts (js/mascot2.js): he peeks from the screen edges, speech bubble beside him */
.ms-owl { position: fixed !important; left: 0; top: 0; margin: 0 !important; z-index: 9290; transform-origin: 50% 60%; will-change: transform; touch-action: none; }
.ms-b { position: fixed; z-index: 9291; max-width: 230px; direction: rtl; background: #fffdf6; color: #2a1a0e; border: 2.5px solid #7a4d27; border-radius: 16px; padding: 8px 12px; font-size: 13.5px; line-height: 1.7; font-weight: 800; box-shadow: 0 8px 22px rgba(0,0,0,.28); opacity: 0; transform: scale(.85); transition: opacity .2s, transform .25s cubic-bezier(.3,1.5,.5,1); pointer-events: none; }
.ms-b.on { opacity: 1; transform: scale(1); pointer-events: auto; }

/* شكاوي ومشاكل inside the ideas box */
.id-sw { display: flex; gap: 6px; padding: 4px; border-radius: 16px; background: var(--input-bg); margin-bottom: 12px; }
.id-sw button { flex: 1; display: flex; align-items: center; justify-content: center; gap: 6px; padding: 9px 6px; border-radius: 12px; font-size: 13px; font-weight: 800; color: var(--text2); }
.id-sw button.on { background: var(--surface); color: var(--text); box-shadow: 0 2px 8px rgba(0,0,0,.12); }
.id-sw svg { width: 16px; height: 16px; }
.id-hero.cm { background: linear-gradient(135deg, #DC2626, #7C3AED); }
.id-sub { font-size: 13px; font-weight: 900; color: var(--text2); margin: 4px 2px; }
.id-card.cm { padding: 12px 14px; }
.cm-img { max-width: 100%; max-height: 160px; border-radius: 12px; margin-top: 8px; object-fit: cover; cursor: zoom-in; }
.cm-prev { position: relative; align-self: flex-start; }
.cm-prev img { max-height: 150px; max-width: 100%; border-radius: 14px; display: block; }
.cm-prev button { position: absolute; top: 6px; left: 6px; width: 28px; height: 28px; border-radius: 50%; background: rgba(0,0,0,.65); color: #fff; display: flex; align-items: center; justify-content: center; }
.cm-file { display: flex !important; align-items: center; justify-content: center; gap: 8px; padding: 14px; border-radius: 14px; border: 2px dashed var(--border); color: var(--text2); font-weight: 800 !important; cursor: pointer; margin-top: 0 !important; }
.cm-file svg { width: 20px; height: 20px; }
.cm-note { color: var(--text2); line-height: 1.7; font-size: 12px; }
.cm-zoom { position: fixed; inset: 0; z-index: 9600; background: rgba(0,0,0,.88); display: flex; align-items: center; justify-content: center; padding: 12px; }
.cm-zoom img { max-width: 100%; max-height: 100%; border-radius: 12px; }

/* ===== رحلة الطالب الجوية (js/flights.js, js/flightsui.js) ===== */
#flightsView { animation: none !important; }
.fl { --fl-a: #38bdf8; --fl-a2: #0ea5e9; --fl-bg: rgba(10, 16, 30, .88); --fl-line: rgba(148, 163, 184, .22); --fl-tx: #eaf2ff; --fl-mut: #93a4bf; position: fixed; inset: 0; z-index: 55; overflow: hidden; color: var(--fl-tx); background: #0b1220; font-family: inherit; }
.fl-map { position: absolute; inset: 0; z-index: 0; touch-action: none; background: #0b1220; }
.fl-map .leaflet-control-attribution { font-size: 9px; opacity: .65; margin-bottom: 0; }
.fl-cv { position: absolute; inset: 0; pointer-events: none; z-index: 4; }
.fl-top { position: absolute; top: 0; left: 0; right: 0; z-index: 8; display: flex; align-items: center; gap: 8px; padding: calc(var(--safe-t, 0px) + 10px) 12px 26px; background: linear-gradient(180deg, rgba(8, 12, 24, .72), transparent); pointer-events: none; }
.fl-top > * { pointer-events: auto; }
.fl-ic { width: 42px; height: 42px; flex: none; border-radius: 14px; display: grid; place-items: center; color: #fff; background: rgba(15, 23, 42, .72); border: 1px solid var(--fl-line); backdrop-filter: blur(10px); -webkit-backdrop-filter: blur(10px); }
.fl-ic svg { width: 19px; height: 19px; }
.fl-ic.on { background: var(--fl-a2); border-color: transparent; }
.fl-title { flex: 1; min-width: 0; display: flex; flex-direction: column; text-shadow: 0 1px 6px rgba(0, 0, 0, .6); }
.fl-title b { font-size: 16px; font-weight: 900; }
.fl-title small { font-size: 11.5px; opacity: .85; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.fl-chips { position: absolute; z-index: 8; top: calc(var(--safe-t, 0px) + 62px); left: 0; right: 0; display: flex; gap: 6px; padding: 0 12px; overflow-x: auto; scrollbar-width: none; }
.fl-chips::-webkit-scrollbar { display: none; }
.fl-chips button { flex: none; padding: 7px 13px; border-radius: 99px; font-size: 12.5px; font-weight: 800; color: #dbe7fb; background: rgba(15, 23, 42, .78); border: 1px solid var(--fl-line); backdrop-filter: blur(8px); }
.fl-chips button.on { background: var(--fl-a2); color: #fff; border-color: transparent; }
.fl-net { position: absolute; z-index: 9; top: calc(var(--safe-t, 0px) + 66px); left: 50%; transform: translateX(-50%); display: flex; align-items: center; gap: 7px; padding: 8px 14px; border-radius: 99px; font-size: 12.5px; font-weight: 800; background: #b45309; color: #fff; box-shadow: 0 6px 18px rgba(0, 0, 0, .35); }
.fl-net svg { width: 15px; height: 15px; }
.fl-banner { position: absolute; z-index: 9; top: calc(var(--safe-t, 0px) + 66px); left: 12px; right: 12px; display: flex; align-items: center; gap: 8px; padding: 10px 12px; border-radius: 16px; background: var(--fl-bg); border: 1px solid var(--fl-line); font-size: 13px; font-weight: 800; backdrop-filter: blur(12px); }
.fl-banner span { flex: 1; }
.fl-banner svg { width: 18px; height: 18px; color: var(--fl-a); }
.fl-banner button { padding: 6px 12px; border-radius: 10px; background: rgba(148, 163, 184, .2); color: #fff; font-size: 12px; font-weight: 800; }
.fl-cam { position: absolute; z-index: 8; right: 12px; top: 92px; display: flex; flex-direction: column; gap: 8px; }
.fl-cam button { width: 42px; height: 42px; border-radius: 14px; display: grid; place-items: center; color: #dbe7fb; background: rgba(15, 23, 42, .78); border: 1px solid var(--fl-line); backdrop-filter: blur(10px); }
.fl-cam button.on { background: var(--fl-a2); color: #fff; border-color: transparent; }
.fl-cam svg { width: 19px; height: 19px; }
.fl-card { position: absolute; z-index: 9; left: 12px; right: 12px; top: calc(var(--safe-t, 0px) + 112px); max-width: 360px; margin-inline: auto; padding: 12px 14px; border-radius: 18px; background: var(--fl-bg); border: 1px solid var(--fl-line); backdrop-filter: blur(14px); box-shadow: 0 14px 34px rgba(0, 0, 0, .4); }
.fl-card .c-h { display: flex; align-items: center; justify-content: space-between; font-size: 14px; }
.fl-card .c-h b { display: flex; align-items: center; gap: 6px; }
.fl-card .c-h svg { width: 16px; height: 16px; color: var(--fl-a); }
.fl-card .c-h button { width: 28px; height: 28px; border-radius: 9px; background: rgba(148, 163, 184, .16); display: grid; place-items: center; }
.fl-card .c-r { display: flex; align-items: center; gap: 8px; margin: 8px 0; font-size: 15px; font-weight: 900; }
.fl-card .c-r svg { width: 16px; height: 16px; color: var(--fl-mut); }
.fl-card .c-g { display: grid; grid-template-columns: repeat(3, 1fr); gap: 8px; }
.fl-card .c-g div, .hud-grid div, .hud-sim div, .fl-stats div { background: rgba(148, 163, 184, .1); border-radius: 12px; padding: 8px 6px; text-align: center; }
.fl-card small, .hud-grid small, .hud-sim small, .fl-stats span { display: block; font-size: 11px; color: var(--fl-mut); }
.fl-card .c-g b { font-size: 15px; }
.fl-card .c-n { display: block; margin-top: 8px; font-size: 11px; color: var(--fl-mut); text-align: center; }
/* the sheet: draggable on a phone, a side panel on a big screen */
.fl-sheet { position: absolute; z-index: 10; left: 0; right: 0; bottom: 0; height: 46vh; display: flex; flex-direction: column; border-radius: 24px 24px 0 0; background: var(--fl-bg); border-top: 1px solid var(--fl-line); backdrop-filter: blur(18px) saturate(140%); -webkit-backdrop-filter: blur(18px) saturate(140%); box-shadow: 0 -16px 40px rgba(0, 0, 0, .45); transition: height .3s cubic-bezier(.2, .8, .25, 1); padding-bottom: var(--safe-b, 0px); }
.fl-sheet.drag { transition: none; }
.fl-grab { flex: none; height: 26px; display: grid; place-items: center; touch-action: none; cursor: grab; }
.fl-grab span { width: 42px; height: 5px; border-radius: 9px; background: rgba(148, 163, 184, .5); }
.fl-body { flex: 1; min-height: 0; overflow-y: auto; overscroll-behavior: contain; padding: 0 16px 18px; display: flex; flex-direction: column; gap: 12px; }
@media (min-width: 900px) { .fl-sheet { left: 16px; right: auto; top: 76px; bottom: 16px; width: 380px; height: auto !important; border-radius: 22px; border: 1px solid var(--fl-line); } .fl-grab { display: none; } .fl-cam { right: 18px; } .fl-card { margin-inline: 0; left: auto; right: 18px; } }
.fl-h { display: flex; align-items: center; justify-content: space-between; font-size: 18px; font-weight: 900; }
.fl-x { width: 36px; height: 36px; border-radius: 12px; background: rgba(148, 163, 184, .16); display: grid; place-items: center; color: #fff; }
.fl-x svg { width: 18px; height: 18px; }
.fl-hero { display: flex; gap: 12px; align-items: center; padding: 14px; border-radius: 20px; background: linear-gradient(135deg, rgba(14, 165, 233, .28), rgba(99, 102, 241, .22)); border: 1px solid rgba(56, 189, 248, .3); }
.fl-hero-ic { width: 48px; height: 48px; flex: none; border-radius: 16px; display: grid; place-items: center; background: linear-gradient(135deg, #38bdf8, #0284c7); }
.fl-hero-ic svg { width: 26px; height: 26px; color: #fff; transform: rotate(-20deg); }
.fl-hero b { font-size: 16px; font-weight: 900; }
.fl-hero p { margin: 3px 0 0; font-size: 12.5px; line-height: 1.7; color: #c9d7ee; }
.fl-go { display: flex; align-items: center; justify-content: center; gap: 9px; min-height: 52px; padding: 0 18px; border-radius: 18px; font-size: 16px; font-weight: 900; color: #fff; background: linear-gradient(135deg, #38bdf8, #0284c7); box-shadow: 0 12px 26px -10px rgba(14, 165, 233, .8); }
.fl-go:disabled { opacity: .55; }
.fl-go svg { width: 21px; height: 21px; }
.fl-row2 { display: grid; grid-template-columns: 1fr 1fr; gap: 10px; }
.fl-row2 button, .fl-sec-btn { display: flex; align-items: center; justify-content: center; gap: 7px; min-height: 46px; border-radius: 15px; font-size: 13.5px; font-weight: 800; color: #e2ecff; background: rgba(148, 163, 184, .14); border: 1px solid var(--fl-line); }
.fl-row2 button.on { background: rgba(14, 165, 233, .25); border-color: var(--fl-a2); }
.fl-row2 svg { width: 18px; height: 18px; }
.fl-row2 small { font-size: 11px; opacity: .7; }
.fl-stats { display: grid; grid-template-columns: repeat(3, 1fr); gap: 8px; }
.fl-stats b { display: block; font-size: 18px; font-weight: 900; }
.fl-sub { font-size: 13px; font-weight: 900; color: var(--fl-mut); margin-top: 2px; }
.fl-badges { display: grid; grid-template-columns: repeat(3, 1fr); gap: 8px; }
.fl-badges > div { padding: 10px 6px; border-radius: 14px; text-align: center; background: rgba(148, 163, 184, .1); opacity: .7; }
.fl-badges > div.ok { opacity: 1; background: rgba(34, 197, 94, .14); }
.fl-badges span { display: grid; place-items: center; width: 34px; height: 34px; margin: 0 auto 4px; border-radius: 50%; background: rgba(148, 163, 184, .18); }
.fl-badges .ok span { background: #16a34a; }
.fl-badges svg { width: 17px; height: 17px; }
.fl-badges b { display: block; font-size: 11.5px; }
.fl-badges i.bar { display: block; height: 4px; border-radius: 9px; background: rgba(148, 163, 184, .25); margin-top: 6px; overflow: hidden; }
.fl-badges i.bar u { display: block; height: 100%; background: var(--fl-a); }
.fl-note { margin: 0; font-size: 11.5px; line-height: 1.8; color: var(--fl-mut); text-align: center; }
/* the wizard */
.flw-sec { display: flex; flex-direction: column; gap: 8px; padding: 12px; border-radius: 18px; background: rgba(148, 163, 184, .08); border: 1px solid var(--fl-line); }
.flw-sec > label { font-size: 13px; font-weight: 900; color: var(--fl-mut); }
.flw-sel { display: flex; align-items: center; gap: 9px; padding: 11px 12px; border-radius: 14px; background: rgba(15, 23, 42, .6); font-size: 15px; font-weight: 800; color: var(--fl-mut); }
.flw-sel.set { color: #fff; border: 1px solid var(--fl-a2); }
.flw-sel svg { width: 18px; height: 18px; color: var(--fl-a); }
.flw-in { display: flex; align-items: center; gap: 8px; padding: 0 12px; border-radius: 14px; background: rgba(15, 23, 42, .6); border: 1px solid var(--fl-line); }
.flw-in svg { width: 17px; height: 17px; color: var(--fl-mut); }
.flw-in input { flex: 1; min-width: 0; height: 44px; background: transparent; color: #fff; font: inherit; font-size: 15px; outline: none; }
.flw-res { display: flex; flex-direction: column; gap: 2px; }
.flw-res button { display: flex; align-items: center; gap: 10px; padding: 9px 8px; border-radius: 12px; text-align: start; color: #fff; }
.flw-res button:active { background: rgba(14, 165, 233, .2); }
.flw-res svg { width: 17px; height: 17px; flex: none; color: var(--fl-a); }
