/* the flight HUD */
.hud-top { display: flex; align-items: center; justify-content: space-between; }
.hud-no { display: flex; align-items: center; gap: 6px; font-size: 13.5px; font-weight: 900; letter-spacing: 1px; }
.hud-no svg { width: 17px; height: 17px; color: var(--fl-a); transform: rotate(-30deg); }
.hud-chip { padding: 5px 12px; border-radius: 99px; font-size: 12px; font-weight: 900; background: #475569; }
.hud-chip.st-prep { background: #b45309; } .hud-chip.st-board { background: #2563eb; } .hud-chip.st-fly { background: #15803d; } .hud-chip.st-land { background: #7c3aed; } .hud-chip.st-done { background: #dc2626; }
.st-fly { color: #4ade80; } .st-done { color: #f87171; } .st-land { color: #c4b5fd; } .st-board { color: #93c5fd; } .st-prep { color: #fbbf24; }
.hud-route { display: flex; align-items: center; gap: 9px; font-size: 18px; font-weight: 900; }
