.hud-time { font-size: 46px; font-weight: 900; letter-spacing: 1.5px; text-align: center; line-height: 1.1; font-variant-numeric: tabular-nums; }
.hud-cap { text-align: center; font-size: 12px; color: var(--fl-mut); margin-top: -6px; }
.hud-bar { position: relative; height: 22px; border-radius: 99px; background: rgba(148, 163, 184, .2); overflow: hidden; }
.hud-bar i { position: absolute; inset: 0 auto 0 0; width: 0; border-radius: 99px; background: linear-gradient(90deg, #38bdf8, #22c55e); transition: width .3s linear; }
.hud-bar span { position: absolute; inset: 0; display: grid; place-items: center; font-size: 11.5px; font-weight: 900; text-shadow: 0 1px 3px rgba(0, 0, 0, .6); }
.hud-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 8px; }
.hud-grid b { display: block; font-size: 16px; font-weight: 900; }
.hud-sim { display: grid; grid-template-columns: repeat(3, 1fr); gap: 8px; }
.hud-sim em { grid-column: 1 / -1; font-style: normal; text-align: center; font-size: 10.5px; color: var(--fl-mut); }
.hud-sim b { font-size: 14px; font-variant-numeric: tabular-nums; }
.hud-acts { display: flex; align-items: center; justify-content: space-between; gap: 8px; }
.hud-acts .danger { display: flex; align-items: center; gap: 6px; padding: 10px 14px; border-radius: 14px; font-size: 13px; font-weight: 800; color: #fecaca; background: rgba(220, 38, 38, .2); border: 1px solid rgba(248, 113, 113, .35); }
.hud-acts svg, .hud-pub svg { width: 16px; height: 16px; }
.hud-pub { display: flex; align-items: center; gap: 5px; font-size: 11.5px; color: var(--fl-mut); }
.hud-rep { display: flex; gap: 6px; }
.hud-rep button { flex: 1; min-height: 42px; border-radius: 12px; font-size: 13px; font-weight: 900; color: #dbe7fb; background: rgba(148, 163, 184, .14); display: grid; place-items: center; }
.hud-rep button.on { background: var(--fl-a2); color: #fff; }
.hud-rep svg { width: 17px; height: 17px; }
.fl-done { display: flex; flex-direction: column; align-items: center; gap: 12px; text-align: center; }
.fl-done .ring { width: 72px; height: 72px; border-radius: 50%; display: grid; place-items: center; background: #16a34a; box-shadow: 0 0 0 10px rgba(34, 197, 94, .18); animation: flpop .5s cubic-bezier(.2, 1.6, .4, 1); }
.fl-done .ring svg { width: 36px; height: 36px; color: #fff; }
.fl-done b { font-size: 21px; font-weight: 900; }
.fl-done p { margin: 0; font-size: 14px; color: #c9d7ee; }
.fl-done .fl-stats, .fl-done .fl-go, .fl-done .fl-row2 { width: 100%; }
.fl-new { display: flex; flex-wrap: wrap; justify-content: center; gap: 6px; }
.fl-new span { display: flex; align-items: center; gap: 5px; padding: 6px 12px; border-radius: 99px; font-size: 12.5px; font-weight: 800; background: rgba(34, 197, 94, .2); color: #86efac; }
.fl-new svg { width: 15px; height: 15px; }
@keyframes flpop { from { transform: scale(.4); opacity: 0; } to { transform: scale(1); opacity: 1; } }
.fl-his { display: flex; flex-direction: column; gap: 6px; padding: 12px; border-radius: 16px; background: rgba(148, 163, 184, .09); border: 1px solid var(--fl-line); }
.fl-his .r { display: flex; align-items: center; gap: 8px; font-size: 15px; }
.fl-his .r svg { width: 16px; height: 16px; color: var(--fl-mut); }
.fl-his .m { display: flex; flex-wrap: wrap; gap: 6px 12px; font-size: 12px; color: var(--fl-mut); }
.fl-his .okc { color: #4ade80; font-weight: 800; } .fl-his .cxc { color: #fbbf24; font-weight: 800; }
.fl-his .a { display: flex; gap: 8px; }
.fl-his .a button { display: flex; align-items: center; gap: 6px; padding: 7px 13px; border-radius: 11px; font-size: 12.5px; font-weight: 800; color: #dbe7fb; background: rgba(14, 165, 233, .2); }
.fl-his .a .dl { margin-inline-start: auto; background: rgba(220, 38, 38, .18); color: #fca5a5; padding: 7px 10px; }
.fl-his .a svg { width: 15px; height: 15px; }
.fl-empty { display: flex; flex-direction: column; align-items: center; gap: 6px; padding: 30px 0; color: var(--fl-mut); }
.fl-empty svg { width: 40px; height: 40px; }
.fl-empty b { color: #fff; }
.fl-load, .fl-err, .fl-gate { position: absolute; inset: 0; z-index: 20; display: flex; flex-direction: column; align-items: center; justify-content: center; gap: 12px; background: #0b1220; text-align: center; padding: 24px; }
.fl-load.hidden, .fl-err.hidden { display: none; }
.fl-load span, .fl-load2 span { width: 38px; height: 38px; border-radius: 50%; border: 3px solid rgba(148, 163, 184, .25); border-top-color: var(--fl-a); animation: flspin .9s linear infinite; display: block; margin: 20px auto; }
.fl-err svg, .fl-gate svg { width: 44px; height: 44px; color: var(--fl-a); }
.fl-err small { color: var(--fl-mut); }
.fl-err button, .fl-gate button { padding: 11px 22px; border-radius: 14px; font-weight: 900; color: #fff; background: var(--fl-a2); }
@keyframes flspin { to { transform: rotate(360deg); } }
/* a small reminder on the other pages while a flight is running */
.fl-chip { position: fixed; z-index: 9100; top: calc(var(--safe-t, 0px) + 74px); inset-inline-start: 10px; display: flex; align-items: center; gap: 7px; padding: 7px 12px 7px 10px; border-radius: 99px; font-size: 13px; font-weight: 900; color: #fff; background: linear-gradient(135deg, #0284c7, #0ea5e9); box-shadow: 0 8px 22px rgba(2, 132, 199, .5); font-variant-numeric: tabular-nums; }
.fl-chip svg { width: 16px; height: 16px; transform: rotate(-30deg); }
@media (prefers-reduced-motion: reduce) { .fl-sheet, .hud-bar i { transition: none; } .fl-done .ring { animation: none; } }

/* night map: the same street tiles, darkened (the free dark tile servers need a key) */
.fl-map.fl-night .leaflet-tile-pane, .tile-night .leaflet-tile-pane { filter: invert(1) hue-rotate(180deg) brightness(.82) contrast(.92) saturate(.5); }
/* satellite photos: never inverted at night, only dimmed */
