.tg-feed { padding: 4px 14px 0; display: flex; flex-direction: column; gap: 12px; }
.tg-card { padding: 12px; border-radius: 20px; background: var(--surface); border: 1px solid var(--border); overflow: hidden; }
.tg-hd { display: flex; align-items: center; gap: 10px; }
.tg-hd .tu-av { flex: none; width: 38px; height: 38px; border-radius: 50%; overflow: hidden; display: grid; place-items: center; background: #229ED9; color: #fff; font-weight: 800; }
