.nt-sheetw { z-index: 9300; }
.nt-lbl { margin: 14px 0 6px; font-size: 12px; font-weight: 800; color: var(--text2); }
.nt-pps, .nt-cols, .nt-pgs { display: flex; flex-wrap: wrap; gap: 8px; }
