.nt-pv-grid { background: linear-gradient(#bfd0ea 1px, transparent 1px) 0 0 / 8px 8px, linear-gradient(90deg, #bfd0ea 1px, transparent 1px) 0 0 / 8px 8px, #fff; }
.nt-pv-dots { background: radial-gradient(#7d93b8 1px, transparent 1.4px) 0 0 / 8px 8px, #fff; }
.nt-pv-axes { background: linear-gradient(#111 0 0) 50% 0 / 2px 100% no-repeat, linear-gradient(#111 0 0) 0 50% / 100% 2px no-repeat, linear-gradient(#cfd9ea 1px, transparent 1px) 0 0 / 8px 8px, linear-gradient(90deg, #cfd9ea 1px, transparent 1px) 0 0 / 8px 8px, #fff; }
