/* ===== غرفة المشرفين: a voice room like a voice-chat app (dark green, round mic seats), moderators only ===== */
#mdrView { position: fixed; inset: 0; z-index: 40; background: #07302b; overscroll-behavior: contain; }
body.mdr-on #bottomNav, body.mdr-on #appHeaderBar { display: none !important; }
.mdr { position: relative; height: 100%; display: flex; flex-direction: column; color: #fff; overflow: hidden; background: linear-gradient(170deg, #0c4a40 0%, #073a35 45%, #052622 100%); }
.mdr-bg { position: absolute; inset: 0; pointer-events: none; }
.mdr-bg i { position: absolute; border-radius: 50%; border: 1.5px solid rgba(214,185,98,.35); background: radial-gradient(circle at 30% 30%, rgba(255,255,255,.06), rgba(255,255,255,0) 60%); }
.mdr-bg i:nth-child(1) { width: 150vw; height: 150vw; right: -35vw; top: 18vh; }
.mdr-bg i:nth-child(2) { width: 110vw; height: 110vw; left: -50vw; top: 48vh; border-color: rgba(255,255,255,.12); }
.mdr-top { position: relative; display: flex; align-items: center; gap: 10px; padding: calc(var(--safe-t, 0px) + 12px) 14px 8px; }
.mdr-title { flex: 1; min-width: 0; display: flex; flex-direction: column; }
.mdr-title b { display: flex; align-items: center; gap: 6px; font-size: 17px; font-weight: 800; }
.mdr-title b svg { width: 18px; height: 18px; color: #4ade80; }
.mdr-title small { font-size: 11.5px; opacity: .75; margin-top: 2px; }
.mdr-ic { position: relative; min-width: 42px; height: 42px; padding: 0 10px; border-radius: 14px; display: inline-flex; align-items: center; justify-content: center; gap: 4px; background: rgba(255,255,255,.12); color: #fff; font-size: 13px; font-weight: 700; }
.mdr-ic svg { width: 20px; height: 20px; }
.mdr-seats { position: relative; display: grid; grid-template-columns: repeat(4, 1fr); gap: 14px 6px; padding: 14px 10px 6px; direction: rtl; }
.mdr-seat { display: flex; flex-direction: column; align-items: center; gap: 6px; color: #fff; min-width: 0; }
.mdr-seat em { font-style: normal; font-size: 12px; opacity: .85; max-width: 100%; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.mdr-av { position: relative; width: 64px; height: 64px; border-radius: 50%; display: grid; place-items: center; font-size: 24px; font-weight: 800; background: var(--c, rgba(255,255,255,.14)); color: #fff; box-shadow: 0 0 0 3px rgba(255,255,255,.18); transition: box-shadow .15s; }
.mdr-av.empty { background: rgba(255,255,255,.12); box-shadow: none; }
.mdr-av.empty svg { width: 26px; height: 26px; opacity: .9; }
.mdr-av.sm { width: 36px; height: 36px; font-size: 15px; box-shadow: none; }
.mdr-seat.on .mdr-av { box-shadow: 0 0 0 3px #60a5fa; }
.mdr-seat.on.me .mdr-av { box-shadow: 0 0 0 3px #4ade80; }
.mdr-seat.talk .mdr-av { box-shadow: 0 0 0 3px #4ade80, 0 0 0 9px rgba(74,222,128,.28); animation: mdrTalk .7s ease-in-out infinite alternate; }
@keyframes mdrTalk { from { transform: scale(1); } to { transform: scale(1.06); } }
.mdr-off { position: absolute; right: -2px; bottom: -2px; width: 24px; height: 24px; border-radius: 50%; background: #ef4444; display: grid; place-items: center; }
.mdr-off svg { width: 13px; height: 13px; }
.mdr-note { position: relative; margin: 8px 14px 0; padding: 9px 12px; border-radius: 12px; background: rgba(0,0,0,.22); font-size: 12px; line-height: 1.6; display: flex; gap: 8px; align-items: flex-start; }
.mdr-note svg { width: 14px; height: 14px; flex: none; margin-top: 3px; color: #d6b962; }
.mdr-chat { position: relative; flex: 1; min-height: 0; overflow-y: auto; padding: 10px 14px; display: flex; flex-direction: column; gap: 6px; }
.mdr-m { align-self: flex-start; max-width: 86%; background: rgba(0,0,0,.28); border-radius: 14px; padding: 7px 11px; font-size: 14px; line-height: 1.5; }
.mdr-m b { display: block; font-size: 11.5px; color: #86efac; margin-bottom: 1px; }
.mdr-m.me { align-self: flex-end; background: rgba(34,197,94,.3); }
.mdr-m.me b { color: #bbf7d0; }
.mdr-empty { margin: auto; opacity: .6; font-size: 13px; }
.mdr-bar { position: relative; display: flex; align-items: center; gap: 8px; padding: 8px 12px calc(var(--safe-b, 0px) + 10px); }
.mdr-bar input { flex: 1; min-width: 0; height: 44px; border-radius: 22px; border: 0; padding: 0 16px; background: rgba(255,255,255,.14); color: #fff; font-size: 15px; outline: none; }
.mdr-bar input::placeholder { color: rgba(255,255,255,.55); }
.mdr-b { width: 44px; height: 44px; flex: none; border-radius: 50%; display: grid; place-items: center; background: rgba(255,255,255,.14); color: #fff; }
.mdr-b svg { width: 21px; height: 21px; }
.mdr-b.live { background: #16a34a; }
.mdr-b.off { background: #ef4444; }
.mdr-b.send { background: #2563eb; }
.mdr-sheet { position: fixed; inset: 0; z-index: 9000; background: rgba(0,0,0,.5); display: flex; align-items: flex-end; justify-content: center; }
.mdr-sp { width: 100%; max-width: 520px; max-height: 70vh; overflow: auto; background: #0a3a34; color: #fff; border-radius: 20px 20px 0 0; padding: 16px; display: flex; flex-direction: column; gap: 8px; direction: rtl; }
.mdr-sp > b { font-size: 16px; margin-bottom: 4px; }
.mdr-mem { display: flex; align-items: center; gap: 10px; padding: 6px 4px; font-size: 14px; }
.mdr-mem small { opacity: .7; }
.mdr-onmic { width: 16px; height: 16px; margin-inline-start: auto; color: #4ade80; }
.mdr-acts { display: flex; gap: 6px; margin-inline-start: auto; }
.mdr-acts button { width: 34px; height: 34px; border-radius: 10px; display: grid; place-items: center; background: rgba(255,255,255,.12); color: #fff; }
.mdr-acts button.bad { background: rgba(239,68,68,.35); }
.mdr-acts svg { width: 17px; height: 17px; }
.mdr-x { margin-top: 6px; padding: 11px; border-radius: 12px; background: rgba(255,255,255,.12); color: #fff; font-weight: 700; }

.mdr-ic.on { background: #d97706; }
.mdr-av.locked { background: rgba(0,0,0,.28); }
.mdr-p { font-size: 13px; opacity: .8; margin: 0 0 4px; line-height: 1.6; }
.mdr-opt { display: flex; align-items: center; gap: 10px; padding: 13px 14px; border-radius: 14px; background: rgba(255,255,255,.1); color: #fff; font-size: 15px; font-weight: 700; text-align: start; }
.mdr-opt svg { width: 20px; height: 20px; flex: none; }
.mdr-opt.go { background: #16a34a; }
.mdr-opt.warn { background: rgba(217,119,6,.35); }
.mdr-opt.bad { background: rgba(239,68,68,.35); }
.mdr-sp { padding-bottom: calc(var(--safe-b, 0px) + 16px); }
.mdr-bar input:disabled { opacity: .5; }
.mdr-ic.hidden { display: none !important; }

/* ===== وضع الصيانة: an apology screen with moving gears, a swinging wrench, drifting stars; touching it makes sparks and speeds the gears ===== */
#maintenanceOverlay { position: fixed; inset: 0; z-index: 9999; display: flex; flex-direction: column; align-items: center; justify-content: center; padding: calc(var(--safe-t, 0px) + 20px) 22px calc(var(--safe-b, 0px) + 22px); text-align: center; color: #fff; overflow: hidden; touch-action: manipulation; user-select: none; -webkit-user-select: none;
    background: radial-gradient(120% 80% at 50% 0%, #0f766e 0%, #0a3d3a 38%, #061d22 100%); --spd: 1; --px: 0; --py: 0; }
#maintenanceOverlay.hidden { display: none; }
#mtFx { position: absolute; inset: 0; width: 100%; height: 100%; pointer-events: none; z-index: 3; }
.mt-stars { position: absolute; inset: 0; pointer-events: none; }
.mt-stars i { position: absolute; width: 3px; height: 3px; border-radius: 50%; background: #fff; opacity: .0; animation: mtTw 4s ease-in-out infinite; }
@keyframes mtTw { 0%, 100% { opacity: .05; transform: scale(.6) translateY(0); } 50% { opacity: .9; transform: scale(1.2) translateY(-8px); } }
.mt-scene { position: relative; width: min(78vw, 330px); aspect-ratio: 300 / 210; margin-bottom: 14px; z-index: 2; transform: translate(calc(var(--px) * 10px), calc(var(--py) * 8px)); transition: transform .25s ease-out; }
.mt-scene svg { width: 100%; height: 100%; overflow: visible; display: block; }
.mt-gear { transform-box: fill-box; transform-origin: center; animation: mtSpin calc(var(--t, 10s) / var(--spd)) linear infinite; cursor: pointer; transition: filter .2s; -webkit-tap-highlight-color: transparent; }
.mt-gear.rev { animation-direction: reverse; }
.mt-gear:active { filter: brightness(1.25); }
@keyframes mtSpin { to { transform: rotate(360deg); } }
.mt-wrench { transform-box: fill-box; transform-origin: 85% 85%; animation: mtWrench 1.6s ease-in-out infinite; }
@keyframes mtWrench { 0%, 100% { transform: rotate(-18deg); } 50% { transform: rotate(14deg); } }
.mt-spark { animation: mtSpark 1.6s ease-in-out infinite; transform-box: fill-box; transform-origin: center; }
@keyframes mtSpark { 0%, 40%, 100% { opacity: 0; transform: scale(.3); } 55% { opacity: 1; transform: scale(1.1); } 75% { opacity: 0; transform: scale(1.6); } }
.mt-box { position: relative; z-index: 2; max-width: 340px; width: 100%; animation: mtIn .8s cubic-bezier(.2, 1.1, .3, 1) both; }
@keyframes mtIn { from { opacity: 0; transform: translateY(24px); } to { opacity: 1; transform: none; } }
.mt-sorry { display: inline-flex; align-items: center; gap: 6px; padding: 5px 12px; border-radius: 99px; background: rgba(255,255,255,.14); font-size: 12.5px; font-weight: 700; color: #fde68a; margin-bottom: 10px; }
.mt-sorry svg { color: #fb7185; animation: mtBeat 1.2s ease-in-out infinite; }
@keyframes mtBeat { 0%, 100% { transform: scale(1); } 50% { transform: scale(1.3); } }
#maintenanceOverlay h2 { font-size: 1.45rem; font-weight: 800; margin: 0 0 8px; color: #fff; text-shadow: 0 2px 14px rgba(0,0,0,.35); }
#maintenanceOverlay p { font-size: .98rem; line-height: 1.8; margin: 0; color: rgba(255,255,255,.88); white-space: pre-line; }
.mt-eta { margin-top: 14px; display: inline-flex; align-items: center; gap: 10px; padding: 8px 16px; border-radius: 14px; background: rgba(0,0,0,.28); font-size: 13px; }
.mt-eta.hidden { display: none; }
.mt-eta b { font-size: 20px; font-variant-numeric: tabular-nums; letter-spacing: .04em; color: #fde68a; }
.mt-bar { margin: 18px auto 10px; width: 70%; max-width: 240px; height: 6px; border-radius: 6px; background: rgba(255,255,255,.16); overflow: hidden; }
.mt-bar i { display: block; height: 100%; width: 40%; border-radius: 6px; background: linear-gradient(90deg, #34d399, #fde68a, #34d399); background-size: 200% 100%; animation: mtBar calc(2.2s / var(--spd)) ease-in-out infinite, mtShine 1.4s linear infinite; }
@keyframes mtBar { 0% { transform: translateX(-110%); } 100% { transform: translateX(260%); } }
@keyframes mtShine { to { background-position: -200% 0; } }
.mt-hint { font-size: 12.5px; opacity: .8; min-height: 20px; transition: opacity .3s; }
.mt-retry { margin-top: 12px; padding: 11px 26px; border-radius: 14px; background: #fff; color: #0f766e; font-weight: 800; font-size: 14px; box-shadow: 0 8px 24px -8px rgba(0,0,0,.5); }
.mt-retry:active { transform: scale(.96); }
.mt-retry.glow { animation: mtGlow 1.4s ease-in-out infinite; }
@keyframes mtGlow { 0%, 100% { box-shadow: 0 0 0 0 rgba(253,230,138,.6); } 50% { box-shadow: 0 0 0 12px rgba(253,230,138,0); } }
@media (prefers-reduced-motion: reduce) {
  .mt-gear, .mt-wrench, .mt-spark, .mt-stars i, .mt-sorry svg, .mt-bar i, .mt-box, .mt-retry.glow { animation: none !important; }
  .mt-bar i { width: 60%; }
}


/* study rooms: saved marks and notes */
