.yr-msg.quick { background: color-mix(in srgb, #7C3AED 10%, var(--surface)); }
.yr-msg button.qs { background: #7C3AED; }
.yr-vc { display: flex; align-items: center; gap: 10px; margin: 10px 0 0; padding: 8px 10px; border-radius: 14px; background: var(--input-bg); }
.yr-vc small { flex: 1; min-width: 0; font-size: 11.5px; line-height: 1.6; color: var(--text2); }
.yr-vc-j { flex: none; display: inline-flex; align-items: center; gap: 6px; padding: 9px 14px; border-radius: 12px; font-size: 13px; font-weight: 900; color: #fff; background: #16A34A; }
.yr-vc-j:disabled { opacity: .6; }
.yr-vc-j svg { width: 16px; height: 16px; }
.yr-vc.on { background: color-mix(in srgb, #16A34A 12%, var(--surface)); }
.yr-vc-l { flex: 1; display: flex; flex-wrap: wrap; gap: 6px; min-width: 0; }
.yr-vc-p { display: inline-flex; align-items: center; gap: 4px; padding: 4px 10px; border-radius: 99px; font-size: 12px; font-weight: 800; color: var(--text); background: var(--surface); border: 1px solid var(--border); }
.yr-vc-p svg { width: 12px; height: 12px; }
.yr-vc-p.s-connected, .yr-vc-p.s-me { border-color: #16A34A; }
.yr-vc-p.s-failed { border-color: #E11D48; }
.yr-vc-b { flex: none; width: 38px; height: 38px; border-radius: 12px; display: grid; place-items: center; color: #fff; background: #16A34A; }
.yr-vc-b.red { background: #E11D48; }
.yr-vc-b svg { width: 18px; height: 18px; }

/* study rooms, full-screen view: the side buttons hide by themselves; a small handle brings them back; clear of the phone's gesture bar */
.yr-rail-tog { display: none; }
.yr-stage.land .yr-rail { width: 78px; padding: 8px 22px 8px 0; box-sizing: border-box; }
.yr-stage.land.rail-off .yr-rail { display: none; }
.yr-stage.land.rail-off .yr-rail-tog { display: grid; place-items: center; position: absolute; z-index: 5; top: 12px; right: 34px; width: 40px; height: 40px; border-radius: 12px; color: #fff; background: rgba(0,0,0,.45); opacity: .75; }
.yr-rail-tog svg { width: 18px; height: 18px; }

/* study rooms: delete from the home list, note box in the full-screen view */
.yr-recent-w { display: flex; align-items: center; gap: 6px; }
.yr-recent-w .yr-recent { flex: 1; min-width: 0; }
.yr-lnote { display: none; position: absolute; z-index: 7; left: 10px; right: 10px; bottom: 12px; gap: 6px; padding: 8px; border-radius: 14px; background: rgba(0,0,0,.78); direction: rtl; }
.yr-lnote.on { display: flex; }
.yr-lnote input { flex: 1; min-width: 0; height: 40px; padding: 0 12px; border-radius: 10px; font-size: 14px; color: #fff; background: rgba(255,255,255,.14); border: 0; }
.yr-lnote button { flex: none; width: 40px; height: 40px; border-radius: 10px; display: grid; place-items: center; color: #fff; background: #E11D48; }
.yr-lnote button.ask { background: #7C3AED; }
.yr-lnote button.x { background: rgba(255,255,255,.16); }
.yr-lnote.noask button.ask { display: none; }
.yr-lnote svg { width: 18px; height: 18px; }
.yr-rail button.n { color: #93C5FD; background: rgba(37,99,235,.25); }
.yr-recent-w { margin-bottom: 8px; } .yr-recent-w .yr-recent { margin-bottom: 0; }

/* study rooms: the teachers' videos picker */
.yr-tch { display: flex; gap: 8px; overflow-x: auto; padding: 2px 0 8px; margin-bottom: 4px; scrollbar-width: none; }
.yr-tch::-webkit-scrollbar { display: none; }
.yr-tch button { flex: none; display: inline-flex; align-items: center; gap: 7px; padding: 5px 12px 5px 6px; border-radius: 99px; font-size: 12.5px; font-weight: 900; color: var(--text); background: var(--input-bg); border: 1px solid var(--border); }
.yr-tch button.on { color: #fff; background: #E11D48; border-color: #E11D48; }
.yr-tch .yr-av { width: 26px; height: 26px; }
.yr-tp-h { display: flex; align-items: center; gap: 8px; margin: 2px 2px 8px; font-size: 14px; font-weight: 900; color: var(--text); }
.yr-tp-h b { flex: 1; min-width: 0; }
.yr-tp-h button { width: 30px; height: 30px; border-radius: 10px; display: grid; place-items: center; color: var(--text2); background: var(--input-bg); }
.yr-tp-more { margin: 6px 0 12px; }
